-- The views every output is built from.
--
-- Exports are generated by copying these views, so devices.csv, the report and
-- an analyst's ad-hoc query cannot disagree about what the evidence said. A
-- second implementation of the same logic in Go would be a second answer.

-- ---- identity -------------------------------------------------------------

-- The serial rule, written once. A device known only from event records has no
-- registry key to read a serial from, and the rule has to give the same answer
-- there as it does for a devnode or the two will not join.

-- A device instance id is ENUMERATOR\device-id\instance-id. SetupAPI install
-- sections name some devices by hardware id instead — USB\VID_8087&PID_0AAA&REV_0002
-- has no third segment — and reading its last segment as a serial would invent
-- a serial out of the product id, which would then join every device sharing it.
CREATE MACRO has_instance_id(instance_id) AS
    length(instance_id) - length(replace(instance_id, '\', '')) >= 2;

CREATE MACRO identity_tail(instance_id) AS
    CASE WHEN has_instance_id(instance_id)
         THEN regexp_extract(instance_id, '([^\\]+)$', 1)
         ELSE '' END;

-- Windows generates an instance id with '&' as its second character when the
-- device reported no serial. Those are not unique and must never be used to say
-- two records are the same device.
CREATE MACRO is_generated_serial(instance_id) AS
    length(identity_tail(instance_id)) > 1
    AND substr(identity_tail(instance_id), 2, 1) = '&';

-- The enumerator is the first node of an instance id, which is how a macro
-- that is handed nothing but the id can tell one form from another.
CREATE MACRO identity_enumerator(instance_id) AS
    upper(regexp_extract(instance_id, '^([^\\]+)', 1));

-- Whether this enumerator appends an instance index to the tail.
--
-- The '&0' on a USBSTOR tail is Windows numbering the instance, not something
-- the device reported, and stripping it is what makes one stick's USBSTOR node
-- match its USB node. Stripping it everywhere is a different claim: a serial a
-- device genuinely reported ending in '&0' would be silently altered, and the
-- altered value is what every downstream join matches on.
--
-- The five named here are the storage enumerators, which is where the index
-- appears. Across the five reference collections every tail carrying the
-- suffix is on SWD, STORAGE or USBSTOR — SCSI and WPDBUSENUM are included
-- because they key storage the same way and their tails are almost always
-- generated anyway. Nothing on USB or HID carries it.
CREATE MACRO appends_instance_index(instance_id) AS
    identity_enumerator(instance_id) IN
        ('USBSTOR', 'STORAGE', 'SWD', 'SCSI', 'WPDBUSENUM');

-- The tail as the hive stores it, once the two forms that are not a serial at
-- all are excluded. This is what device_serial normalises, and it is kept
-- beside the normalised value so the alteration is checkable rather than
-- something an analyst has to know about.
CREATE MACRO device_serial_recorded(instance_id) AS
    CASE
        WHEN is_generated_serial(instance_id) THEN ''
        -- A WPDBUSENUM node can be keyed by a volume GUID and offset rather
        -- than by a device. That names a volume, and calling it a serial would
        -- put a volume identifier in the column analysts match devices on.
        WHEN starts_with(identity_tail(instance_id), '{') THEN ''
        ELSE identity_tail(instance_id)
    END;

CREATE MACRO device_serial(instance_id) AS
    CASE
        WHEN device_serial_recorded(instance_id) = '' THEN ''
        WHEN appends_instance_index(instance_id)
             THEN regexp_replace(device_serial_recorded(instance_id), '&[0-9]+$', '')
        ELSE device_serial_recorded(instance_id)
    END;

-- Which rule produced the serial, so a value that was altered says so.
CREATE MACRO device_serial_rule(instance_id) AS
    CASE
        WHEN device_serial_recorded(instance_id) = '' THEN ''
        WHEN device_serial(instance_id) <> device_serial_recorded(instance_id)
             THEN 'the trailing instance index this enumerator appends was removed'
        ELSE 'as recorded'
    END;

-- Whether a string names somewhere a file could have been, as opposed to
-- naming a thing.
--
-- A shell link records its target in three places and the weaker two are shell
-- namespace values as often as they are paths: the Control Panel is
-- `{871c5380-42a0-1069-a2ea-08002b30309d}` and a Store application is
-- `Microsoft.WindowsStore_8wekyb3d8bbwe!App`. Both are evidence and neither is
-- a location, so neither may stand in for one — the same line prefetch already
-- draws around a packaged executable_path, and for the same reason: a row whose
-- path column holds an identity invites an analyst to ask which device it was
-- on, and there is no such question.
--
-- A separator or a drive letter is the whole test. It admits a relative path
-- (`..\Reports\payroll.xlsx`), which is the point, and refuses both forms
-- above.
CREATE MACRO is_location(value) AS
    value IS NOT NULL AND value <> ''
    AND (contains(value, '\') OR regexp_matches(value, '^[A-Za-z]:'));

-- ---- provenance -----------------------------------------------------------

-- Ordered by the sequence and not by the id.
--
-- The id's number is padded to four digits, and Go's %04d is a minimum width
-- rather than a maximum, so a collection with more than 9999 sources produces
-- 'src-10000' — which sorts lexicographically *before* 'src-9999'. Ordering
-- this file by the id was reconstructing read order from the id's text, which
-- coupled a formatting choice to the meaning of the custody record: widening
-- the padding would silently reorder every sources.csv ever produced.
--
-- It is a case real evidence reaches rather than a theoretical one. The
-- reference collections carry 302 to 539 sources, but every shortcut, jump list
-- and prefetch file is one of its own, so a full image with several user
-- profiles passes 9999 without being unusual.
--
-- The id stays exactly as it was. It is unique, every join on it is an exact
-- string match and so is unaffected, and it is what an examiner quotes.
CREATE VIEW v_source AS
SELECT
    id            AS source_id,
    sequence      AS read_order,
    artefact,
    path          AS source_path,
    staged_path,
    size_bytes,
    sha256,
    read_at,
    replayed,
    replay_logs,
    replay_note,
    modified_at,
    verified,
    verify_note
FROM source
ORDER BY sequence;

-- Every observation carrying the file and hash it came from, which is what
-- makes a reported figure checkable without the manifest open beside it.
CREATE VIEW v_observation AS
SELECT
    o.id            AS observation_id,
    o.source_id,
    s.artefact,
    s.path          AS source_path,
    s.sha256        AS source_sha256,
    o.kind,
    o.field,
    o.raw,
    o.value,
    o.summary,
    o.raw_timestamp,
    o.time_utc,
    o.registry_key,
    o.registry_value,
    o.control_set,
    o.event_record_id,
    o.channel,
    o.line_number,
    o.byte_offset
FROM observation o
LEFT JOIN source s ON s.id = o.source_id
ORDER BY observation_id;

CREATE VIEW v_warning AS
SELECT w.severity, w.artefact, coalesce(w.path, s.path) AS path,
       w.message, w.source_id, w.recorded_at
FROM warning w
LEFT JOIN source s ON s.id = w.source_id;

-- What the parsers could not read inside records that otherwise parsed,
-- gathered by artefact and reason.
--
-- These warnings were held only as a semicolon-joined column on the row that
-- carries them, and the ledger's warnings are mostly whole-file failures. So a
-- run whose manifest said "1 warning" could have had three hundred shortcuts
-- with a structure that failed to parse and one absent hive, and the number an
-- analyst reads in the report's limitations answered the wrong question. It has
-- to answer "did this run meet evidence it could not fully read", not "did a
-- file fail to open at all".
--
-- reason is the message with runs of digits replaced, because a warning naming
-- an offset or a declared size is one reason seen many times and grouping on
-- the literal text would give one row per record — which is the column this
-- replaces. The first message is kept in full beside it, so the numbers are
-- still reachable without opening the artefact's own CSV.
CREATE VIEW v_parse_warning AS
WITH carried AS (
    SELECT 'shell_bag'   AS artefact, warnings       AS text, source_id FROM shell_bag
    UNION ALL SELECT 'mru_entry',     warnings,       source_id FROM mru_entry
    UNION ALL SELECT 'user_assist',   warnings,       source_id FROM user_assist
    UNION ALL SELECT 'disk_layout',   warnings,       source_id FROM disk_layout
    UNION ALL SELECT 'file_record',   parse_warnings, source_id FROM file_target
    UNION ALL SELECT 'prefetch',      parse_warnings, source_id FROM prefetch_run
),
split AS (
    SELECT c.artefact, c.source_id, trim(part) AS message
    FROM carried c, unnest(string_split(c.text, ';')) AS t(part)
    WHERE coalesce(c.text, '') <> '' AND trim(part) <> ''
)
SELECT
    artefact,
    regexp_replace(message, '[0-9]+', '#', 'g') AS reason,
    count(*)                   AS records,
    count(DISTINCT source_id)  AS source_files,
    min(message)               AS example
FROM split
GROUP BY ALL
ORDER BY records DESC, artefact, reason;

-- ---- device nodes ---------------------------------------------------------

CREATE VIEW v_devnode AS
SELECT
    d.device_key,
    d.device_instance_id,
    d.normalised_instance_id,
    d.enumerator,
    d.device_id,
    d.instance_id,
    -- Read from the normalised identity, not the stored instance id: a
    -- WPDBUSENUM node stores another device's whole path there, and reading
    -- that as a serial produces a "serial" that is a device path.
    is_generated_serial(d.normalised_instance_id) AS serial_is_generated,
    device_serial(d.normalised_instance_id)       AS serial,
    -- The tail as stored, and the rule that turned it into the column above.
    -- Removing a trailing instance index is a normalisation every join then
    -- matches on, so it has to be visible rather than assumed.
    device_serial_recorded(d.normalised_instance_id) AS serial_recorded,
    device_serial_rule(d.normalised_instance_id)     AS serial_rule,
    d.control_set,
    d.device_desc,
    d.friendly_name,
    d.mfg,
    d.class,
    d.class_guid,
    d.service,
    d.container_id,
    d.parent_id_prefix,
    d.hardware_id,
    d.compatible_ids,
    d.location_information,
    d.bus_reported_desc,
    d.raw_key_last_write,
    d.key_last_write_utc,
    d.raw_install_date,
    d.install_date_utc,
    d.raw_first_install_date,
    d.first_install_date_utc,
    d.raw_last_arrival_date,
    d.last_arrival_date_utc,
    d.raw_last_removal_date,
    d.last_removal_date_utc,
    d.registry_key,
    d.source_id,
    s.path   AS source_path,
    s.sha256 AS source_sha256,
    s.replayed
FROM devnode d
LEFT JOIN source s ON s.id = d.source_id
ORDER BY d.device_key, d.control_set, d.registry_key, d.source_id;

-- ---- events ---------------------------------------------------------------

CREATE VIEW v_event AS
SELECT
    e.device_key,
    e.device_instance_id,
    e.time_utc,
    e.raw_file_time,
    e.channel,
    e.event_id,
    e.rule_id,
    e.kind,
    e.meaning,
    e.provider,
    e.record_id,
    e.source_id,
    s.path   AS source_path,
    s.sha256 AS source_sha256
FROM event e
LEFT JOIN source s ON s.id = e.source_id
ORDER BY e.time_utc NULLS LAST, e.source_file, e.record_id,
         e.rule_id, e.device_key;

-- ---- the device inventory -------------------------------------------------

-- Every place a device identity was named, one row per naming.
--
-- The inventory is a union rather than a registry walk with extras attached.
-- The reference evidence holds a device with fourteen event records and no
-- registry key at all: starting from the registry would have lost it, and
-- losing it would look exactly like the device never existing.
CREATE VIEW v_device_evidence AS
SELECT device_key, normalised_instance_id AS device_instance_id,
       'registry.devnode' AS evidence, source_id, source_path,
       key_last_write_utc AS observed_utc
FROM v_devnode
WHERE device_key <> ''
UNION ALL
SELECT device_key, device_instance_id,
       'event.' || kind, source_id, source_path, time_utc
FROM v_event
WHERE device_key <> ''
UNION ALL
SELECT device_key, device_instance_id,
       'setupapi.' || kind, source_id, source_file, start_utc
FROM setup_section
WHERE device_key <> ''
UNION ALL
SELECT device_key, device_instance_id,
       'registry.portable_device', source_id, registry_path, NULL
FROM portable_device
WHERE device_key <> ''
UNION ALL
SELECT device_key, device_instance_id,
       'registry.mounted_devices', source_id, 'MountedDevices\' || value_name, NULL
FROM mount_entry
WHERE device_key <> '';

CREATE VIEW v_device AS
WITH evidence AS (
    SELECT
        device_key,
        max(device_instance_id)                  AS device_instance_id,
        count(*)                                 AS evidence_count,
        count(DISTINCT evidence)                 AS evidence_kinds,
        min(observed_utc)                        AS first_seen_utc,
        max(observed_utc)                        AS last_seen_utc,
        bool_or(evidence = 'registry.devnode')   AS in_registry
    FROM v_device_evidence
    GROUP BY device_key
),
evidence_names AS (
    SELECT device_key, string_agg(evidence, '; ' ORDER BY evidence) AS evidence_sources
    FROM (SELECT DISTINCT device_key, evidence FROM v_device_evidence)
    GROUP BY device_key
),
-- A device appears once per control set. Aggregating rather than picking one
-- keeps a value an alternate set holds and the current one does not.
attributes AS (
    SELECT
        device_key,
        max(normalised_instance_id)      AS device_instance_id,
        max(enumerator)                  AS enumerator,
        max(nullif(serial, ''))          AS serial,
        bool_and(serial_is_generated)    AS serial_is_generated,
        max(nullif(friendly_name, ''))   AS friendly_name,
        max(nullif(device_desc, ''))     AS device_desc,
        max(nullif(bus_reported_desc, '')) AS bus_reported_desc,
        max(nullif(mfg, ''))             AS mfg,
        max(nullif(class, ''))           AS class,
        max(nullif(class_guid, ''))      AS class_guid,
        max(nullif(service, ''))         AS service,
        max(nullif(container_id, ''))    AS container_id,
        max(nullif(hardware_id, ''))     AS hardware_id,
        max(nullif(location_information, '')) AS location_information,
        max(first_install_date_utc)      AS first_install_date_utc,
        max(install_date_utc)            AS install_date_utc,
        max(last_arrival_date_utc)       AS last_arrival_date_utc,
        max(last_removal_date_utc)       AS last_removal_date_utc,
        max(key_last_write_utc)          AS key_last_write_utc,
        count(DISTINCT control_set)      AS control_sets
    FROM v_devnode
    WHERE device_key <> ''
    GROUP BY device_key
),
event_activity AS (
    SELECT
        device_key,
        count(*)                                             AS event_count,
        count(*) FILTER (WHERE kind = 'connect')             AS connect_events,
        count(*) FILTER (WHERE kind = 'disconnect')          AS disconnect_events,
        count(*) FILTER (WHERE kind = 'install')             AS install_events,
        count(*) FILTER (WHERE kind = 'fault')               AS fault_events,
        min(time_utc)                                        AS first_event_utc,
        max(time_utc)                                        AS last_event_utc,
        min(time_utc) FILTER (WHERE kind = 'connect')        AS first_connect_utc,
        max(time_utc) FILTER (WHERE kind = 'disconnect')     AS last_disconnect_utc,
        count(DISTINCT channel)                              AS event_channels
    FROM v_event
    WHERE device_key <> ''
    GROUP BY device_key
),
setup_activity AS (
    SELECT device_key,
           count(*)         AS setup_sections,
           min(start_local) AS first_setup_local,
           max(start_local) AS last_setup_local
    FROM setup_section
    WHERE device_key <> ''
    GROUP BY device_key
),
-- The letters MountedDevices maps to this device now. Not the letters it held
-- when a file was opened: nothing in MountedDevices is time-bound.
letters AS (
    SELECT device_key, string_agg(drive_letter, ',' ORDER BY drive_letter) AS current_drive_letters
    FROM (SELECT DISTINCT device_key, drive_letter FROM mount_entry
          WHERE device_key <> '' AND drive_letter <> '')
    GROUP BY device_key
),
-- Usually the volume label, which is the route from a file record back to a
-- device on hosts where EMDMgmt is not written.
portable AS (
    SELECT device_key, string_agg(friendly_name, '; ' ORDER BY friendly_name) AS portable_names
    FROM (SELECT DISTINCT device_key, friendly_name FROM portable_device
          WHERE device_key <> '' AND friendly_name <> '')
    GROUP BY device_key
)
SELECT
    e.device_key,
    -- The registry form is preferred: it is the device's own casing, where an
    -- event provider may have upper-cased it.
    coalesce(a.device_instance_id, e.device_instance_id) AS device_instance_id,
    coalesce(a.enumerator, split_part(e.device_key, '\', 1)) AS enumerator,
    -- A device known only from events has no devnode to read a serial from,
    -- and its identity is the only thing carrying one.
    coalesce(a.serial, device_serial(e.device_instance_id), '') AS serial,
    coalesce(a.serial_is_generated,
             is_generated_serial(e.device_instance_id)) AS serial_is_generated,
    coalesce(a.friendly_name, '')      AS friendly_name,
    coalesce(a.device_desc, '')        AS device_desc,
    coalesce(a.bus_reported_desc, '')  AS bus_reported_desc,
    coalesce(a.mfg, '')                AS mfg,
    coalesce(a.class, '')              AS class,
    coalesce(a.class_guid, '')         AS class_guid,
    coalesce(a.service, '')            AS service,
    coalesce(a.container_id, '')       AS container_id,
    coalesce(a.hardware_id, '')        AS hardware_id,
    coalesce(a.location_information, '') AS location_information,
    e.in_registry,
    coalesce(a.control_sets, 0)        AS control_sets,
    coalesce(p.portable_names, '')     AS portable_names,
    coalesce(l.current_drive_letters, '') AS current_drive_letters,
    a.first_install_date_utc,
    a.install_date_utc,
    a.last_arrival_date_utc,
    a.last_removal_date_utc,
    a.key_last_write_utc,
    coalesce(v.event_count, 0)         AS event_count,
    coalesce(v.connect_events, 0)      AS connect_events,
    coalesce(v.disconnect_events, 0)   AS disconnect_events,
    coalesce(v.install_events, 0)      AS install_events,
    coalesce(v.fault_events, 0)        AS fault_events,
    coalesce(v.event_channels, 0)      AS event_channels,
    v.first_connect_utc,
    v.last_disconnect_utc,
    v.first_event_utc,
    v.last_event_utc,
    coalesce(t.setup_sections, 0)      AS setup_sections,
    coalesce(t.first_setup_local, '')  AS first_setup_local,
    coalesce(t.last_setup_local, '')   AS last_setup_local,
    e.first_seen_utc,
    e.last_seen_utc,
    e.evidence_count,
    e.evidence_kinds,
    n.evidence_sources
FROM evidence e
JOIN evidence_names n USING (device_key)
LEFT JOIN attributes     a USING (device_key)
LEFT JOIN event_activity v USING (device_key)
LEFT JOIN setup_activity t USING (device_key)
LEFT JOIN letters        l USING (device_key)
LEFT JOIN portable       p USING (device_key)
ORDER BY e.device_key;

-- ---- physical device grouping ---------------------------------------------

-- One physical device appears under several identities: a USB stack node, a
-- USBSTOR disk node, a WPDBUSENUM node, an interface node per function. Counting
-- identities as devices reports one memory stick three times, and an analyst
-- reading "three SanDisks" cannot tell that from three actual sticks.
--
-- Every link below is recorded with the method that made it, because a grouping
-- an analyst cannot interrogate is a grouping they cannot rebut.

CREATE MACRO device_vid_pid(identity) AS
    upper(regexp_extract(identity, 'VID_[0-9A-Fa-f]{4}&PID_[0-9A-Fa-f]{4}', 0));

-- Windows writes a placeholder ContainerID for devices it puts in no container.
-- Both placeholders are shared by dozens of unrelated devices, so treating them
-- as a container match would collapse most of the machine into one device.
CREATE MACRO is_real_container(container_id) AS
    container_id <> ''
    AND lower(container_id) NOT IN (
        '{00000000-0000-0000-0000-000000000000}',
        '{00000000-0000-0000-ffff-ffffffffffff}');

-- Which identity speaks for a group. A USBSTOR node carries the vendor and
-- product a reader recognises; an SWD node usually carries a GUID.
CREATE MACRO identity_rank(enumerator) AS
    CASE upper(enumerator)
        WHEN 'USBSTOR' THEN 1
        WHEN 'SCSI'    THEN 2
        WHEN 'USB'     THEN 3
        WHEN 'HID'     THEN 4
        WHEN 'SWD'     THEN 6
        ELSE 5
    END;

-- Every link between two identities, with the method, whether it asserts they
-- are the same device, and why. Candidate links are carried here too: they are
-- reported and never grouped on.
CREATE VIEW v_device_link AS
WITH identity AS (
    SELECT
        device_key,
        upper(enumerator)             AS enumerator,
        upper(serial)                 AS serial,
        serial_is_generated,
        lower(container_id)           AS container_id,
        device_vid_pid(device_key)    AS vid_pid,
        has_instance_id(device_key)   AS names_an_instance,
        -- The product segment of the key: VID_0781&PID_5581 under USB,
        -- Disk&Ven__USB&Prod__SanDisk_3.2Gen1 under USBSTOR. It is what the
        -- serial check below compares two identities on, because a serial
        -- alone does not say the two are one device.
        upper(split_part(device_key, '\', 2)) AS product
    FROM v_device
),
-- A devnode appears once per control set; the parentage and hardware id facts
-- are the same in each, so aggregating avoids emitting the link twice.
node AS (
    SELECT
        device_key,
        upper(max(nullif(parent_id_prefix, ''))) AS parent_id_prefix,
        upper(max(nullif(instance_id, '')))      AS instance_id,
        lower(max(nullif(service, '')))          AS service,
        upper(max(nullif(device_id, '')))        AS device_id,
        -- Ordered so the joined value is a function of the rows and not of the
        -- order they came back in. Only ever membership-tested with
        -- list_contains below, so the order carries no meaning — but it
        -- reaches devices.csv, where an unstable value means an unstable
        -- file hash in the manifest.
        upper(string_agg(hardware_id, '|' ORDER BY hardware_id))
                                                 AS hardware_ids,
        upper(max(enumerator))                   AS enumerator
    FROM v_devnode
    WHERE device_key <> ''
    GROUP BY device_key
),
-- 1. Exact ContainerID. Windows' own statement that these devnodes are one
--    physical device, and the only route that carries a mass storage device
--    whose USB serial its USBSTOR node truncated.
container AS (
    SELECT a.device_key AS left_key, b.device_key AS right_key,
           'container_id' AS method, 1 AS precedence, true AS asserts_same_device,
           'both identities carry ContainerID ' || a.container_id AS reason
    FROM identity a
    JOIN identity b ON a.container_id = b.container_id AND a.device_key < b.device_key
    WHERE is_real_container(a.container_id)
),
-- 2. The device reported the same serial under two enumerators. Restricted to
--    the storage stack enumerators: a serial is only unique within a vendor,
--    and this host holds three different Intel devices all reporting 05022016.
--
--    That comment had been true and unenforced. The join asked for a matching
--    serial and nothing else, so a generic, cloned, controller-supplied or
--    firmware-default serial merged two vendors' devices into one — and because
--    grouping is transitive, the merge was then authoritative everywhere
--    downstream. A serial is evidence about a device within a vendor's range;
--    on its own it is not an identity.
--
--    So the host's own evidence is asked whether the serial is being used by
--    more than one product. Two disagreements count, and both are affirmative
--    rather than assumed: two identities under one enumerator reporting one
--    serial from different product keys, or two different VID/PIDs on it. One
--    physical device has one product key per enumerator, so either says the
--    serial is shared rather than owned.
serial_conflict AS (
    SELECT serial,
           max(products) > 1 OR count(DISTINCT nullif(vid_pid, '')) > 1 AS shared
    FROM (
        SELECT serial, vid_pid,
               count(DISTINCT product) OVER (PARTITION BY serial, enumerator)
                   AS products
        FROM identity
        WHERE serial <> '' AND NOT serial_is_generated
    )
    GROUP BY serial
),
serial_across AS (
    SELECT a.device_key, b.device_key,
           CASE WHEN c.shared THEN 'serial_across_enumerators_shared'
                ELSE 'serial_across_enumerators' END,
           -- A candidate sorts with the other candidates rather than second,
           -- because precedence is what a reader takes as the strength of the
           -- route and this one is no longer near the top when it fires.
           CASE WHEN c.shared THEN 6 ELSE 2 END,
           NOT c.shared,
           CASE WHEN c.shared
                THEN 'both report serial ' || a.serial || ' (' || a.enumerator ||
                     ' and ' || b.enumerator || '), and this host uses that ' ||
                     'serial on more than one product — a candidate, not an ' ||
                     'assertion that they are the same device'
                ELSE 'both report serial ' || a.serial ||
                     ' (' || a.enumerator || ' and ' || b.enumerator || '), ' ||
                     'and no other product on this host reports it'
           END
    FROM identity a
    JOIN identity b ON a.serial = b.serial AND a.device_key < b.device_key
    JOIN serial_conflict c ON c.serial = a.serial
    WHERE a.serial <> ''
      AND NOT a.serial_is_generated AND NOT b.serial_is_generated
      AND length(a.serial) >= 5
      AND a.enumerator <> b.enumerator
      AND a.enumerator IN ('USB', 'USBSTOR', 'SCSI', 'WPDBUSENUM')
      AND b.enumerator IN ('USB', 'USBSTOR', 'SCSI', 'WPDBUSENUM')
),
-- 3. Same serial and the same VID/PID. The vendor and product agreeing is what
--    makes a short or unremarkable serial safe to join on.
vid_pid_serial AS (
    SELECT a.device_key, b.device_key,
           'vid_pid_and_serial', 3, true,
           'both are ' || a.vid_pid || ' reporting serial ' || a.serial
    FROM identity a
    JOIN identity b ON a.serial = b.serial AND a.vid_pid = b.vid_pid
                   AND a.device_key < b.device_key
    WHERE a.serial <> '' AND a.vid_pid <> ''
      AND NOT a.serial_is_generated AND NOT b.serial_is_generated
),
-- 4. A node's ParentIdPrefix is the leading part of its child's instance id.
--    Excluding hubs and the machine node is not tidying: a root hub publishes a
--    prefix every device plugged into it carries, so without that guard one
--    "physical device" would be the hub and everything ever attached to it.
parentage AS (
    SELECT least(p.device_key, c.device_key), greatest(p.device_key, c.device_key),
           'parent_id_prefix', 4, true,
           'ParentIdPrefix ' || p.parent_id_prefix || ' of ' || p.device_key ||
           ' leads the instance id of ' || c.device_key
    FROM node p
    JOIN node c ON c.device_key <> p.device_key
               AND (c.instance_id = p.parent_id_prefix
                    OR starts_with(c.instance_id, p.parent_id_prefix || '&'))
    WHERE p.parent_id_prefix <> '' AND p.parent_id_prefix IS NOT NULL
      AND c.instance_id IS NOT NULL
      AND p.enumerator IN ('USB', 'HID')
      AND NOT starts_with(p.device_id, 'ROOT_HUB')
      AND coalesce(p.service, '') NOT LIKE 'usbhub%'
),
-- 5. An identity that names no instance is a hardware id, and matching it to
--    the devnode declaring it is the only way a SetupAPI install section reaches
--    the device it installed. Ambiguous when two identical devices declare it.
hardware AS (
    SELECT i.device_key AS partial_key, n.device_key AS full_key
    FROM identity i
    JOIN node n ON list_contains(str_split(n.hardware_ids, '|'), i.device_key)
    WHERE NOT i.names_an_instance
),
hardware_ranked AS (
    SELECT partial_key, full_key,
           count(*) OVER (PARTITION BY partial_key) AS matches
    FROM hardware
),
hardware_link AS (
    SELECT least(partial_key, full_key), greatest(partial_key, full_key),
           CASE WHEN matches = 1 THEN 'hardware_id_unique'
                ELSE 'hardware_id_ambiguous' END,
           5, matches = 1,
           CASE WHEN matches = 1
                THEN partial_key || ' is a hardware id declared by exactly one devnode'
                ELSE partial_key || ' is a hardware id declared by ' ||
                     matches || ' devnodes, so it does not identify one of them'
           END
    FROM hardware_ranked
),
-- A candidate, never a grouping. The USB enumerator holds a 120 character
-- SanDisk serial that USBSTOR stores as its first 63 characters, so one is a
-- prefix of the other and equality never fires. A prefix is not equality: a
-- vendor issuing sequential serials produces prefixes between different devices.
serial_prefix AS (
    SELECT a.device_key, b.device_key,
           'serial_prefix_candidate', 6, false,
           'serial ' || (CASE WHEN length(a.serial) < length(b.serial)
                              THEN a.serial ELSE b.serial END) ||
           ' is a prefix of the other identity''s longer serial — a candidate, ' ||
           'not an assertion that they are the same device'
    FROM identity a
    JOIN identity b ON a.device_key < b.device_key
    WHERE a.serial <> '' AND b.serial <> ''
      AND NOT a.serial_is_generated AND NOT b.serial_is_generated
      AND length(a.serial) <> length(b.serial)
      AND (starts_with(a.serial, b.serial) OR starts_with(b.serial, a.serial))
      AND least(length(a.serial), length(b.serial)) >= 20
      AND a.enumerator <> b.enumerator
),
-- One row per link, not per pair: two identities linked by ContainerID and by a
-- matching serial are corroborated twice, and collapsing that to the stronger
-- route alone would throw away the corroboration.
all_links AS (
    SELECT * FROM container
    UNION ALL SELECT * FROM serial_across
    UNION ALL SELECT * FROM vid_pid_serial
    UNION ALL SELECT * FROM parentage
    UNION ALL SELECT * FROM hardware_link
    UNION ALL SELECT * FROM serial_prefix
)
SELECT DISTINCT
    left_key  AS device_key,
    right_key AS other_device_key,
    method,
    precedence,
    asserts_same_device,
    reason
FROM all_links
ORDER BY precedence, device_key, other_device_key, method, reason;

-- The grouping links in both directions, so the closure below can walk them.
CREATE VIEW v_device_grouping_edge AS
SELECT device_key AS from_key, other_device_key AS to_key
FROM v_device_link WHERE asserts_same_device
UNION
SELECT other_device_key, device_key
FROM v_device_link WHERE asserts_same_device;

-- Which physical device each identity belongs to. Grouping is transitive: a USB
-- node linked to a USBSTOR node by ContainerID and to an interface node by
-- parentage puts all three on one device, so the closure is taken rather than
-- the links read pairwise.
-- The closure is computed here and consolidated into the device_group table
-- once, because everything downstream reads it and a recursive CTE evaluated
-- afresh for each of thirty-odd fact branches costs a minute a run.
CREATE VIEW v_device_grouping AS
WITH RECURSIVE reach(device_key, reached_key) AS (
    SELECT device_key, device_key FROM v_device
    UNION
    SELECT r.device_key, e.to_key
    FROM reach r
    JOIN v_device_grouping_edge e ON e.from_key = r.reached_key
),
component AS (
    SELECT device_key, min(reached_key) AS component_key
    FROM reach
    GROUP BY device_key
),
-- The identity that speaks for the group: one that reported a serial, from the
-- enumerator that names a vendor and product. The ordering is total, so the
-- device id is the same on every run over the same evidence — an identifier
-- that moved between runs could not be cited in a report.
ranked AS (
    SELECT
        c.device_key,
        c.component_key,
        row_number() OVER (
            PARTITION BY c.component_key
            ORDER BY CASE WHEN d.serial <> '' AND NOT d.serial_is_generated
                          THEN 0 ELSE 1 END,
                     -- A hardware id from a SetupAPI section names a model, not
                     -- a device; an instance id names the device itself.
                     CASE WHEN has_instance_id(d.device_key) THEN 0 ELSE 1 END,
                     identity_rank(d.enumerator),
                     d.device_key) AS preference
    FROM component c
    JOIN v_device d USING (device_key)
)
SELECT
    device_key,
    first_value(device_key) OVER (
        PARTITION BY component_key ORDER BY preference) AS physical_device_id,
    count(*) OVER (PARTITION BY component_key)          AS identity_count,
    preference
FROM ranked;

-- What everything downstream reads. Filled by the consolidation step from
-- v_device_grouping, which is where the reasoning lives.
CREATE VIEW v_device_group AS
SELECT device_key, physical_device_id, identity_count, preference
FROM device_group;

-- Every identity with the physical device it belongs to, so a row in
-- device-identities.csv can be followed to its device and back.
CREATE VIEW v_device_identity AS
SELECT g.physical_device_id, g.preference AS identity_preference, d.*
FROM v_device d
JOIN v_device_group g USING (device_key)
ORDER BY g.physical_device_id, g.preference, g.device_key;

-- The links that were not acted on. A candidate joining two identities the
-- grouping already put together corroborates it; one reaching across two groups
-- is an open question, and an analyst should be told which it is rather than
-- left to notice that a link was dropped.
CREATE VIEW v_device_candidate_link AS
SELECT
    l.device_key,
    l.other_device_key,
    l.method,
    ga.physical_device_id = gb.physical_device_id AS already_grouped,
    ga.physical_device_id AS physical_device_id,
    gb.physical_device_id AS other_physical_device_id,
    l.reason
FROM v_device_link l
JOIN v_device_group ga ON ga.device_key = l.device_key
JOIN v_device_group gb ON gb.device_key = l.other_device_key
WHERE NOT l.asserts_same_device
ORDER BY already_grouped, l.method, l.device_key;

CREATE VIEW v_physical_device AS
WITH member AS (
    SELECT g.physical_device_id, g.preference, d.*
    FROM v_device d
    JOIN v_device_group g USING (device_key)
),
enumerators AS (
    SELECT physical_device_id, string_agg(enumerator, ', ' ORDER BY enumerator) AS enumerators
    FROM (SELECT DISTINCT physical_device_id, enumerator FROM member)
    GROUP BY physical_device_id
),
methods AS (
    SELECT physical_device_id, string_agg(method, '; ' ORDER BY precedence) AS grouping_methods
    FROM (SELECT DISTINCT g.physical_device_id, l.method, l.precedence
          FROM v_device_link l
          JOIN v_device_group g ON g.device_key = l.device_key
          WHERE l.asserts_same_device)
    GROUP BY physical_device_id
),
letters AS (
    SELECT physical_device_id, string_agg(drive_letter, ',' ORDER BY drive_letter) AS current_drive_letters
    FROM (SELECT DISTINCT g.physical_device_id, m.drive_letter
          FROM mount_entry m
          JOIN v_device_group g ON g.device_key = m.device_key
          WHERE m.drive_letter <> '')
    GROUP BY physical_device_id
),
portable AS (
    SELECT physical_device_id, string_agg(friendly_name, '; ' ORDER BY friendly_name) AS portable_names
    FROM (SELECT DISTINCT g.physical_device_id, p.friendly_name
          FROM portable_device p
          JOIN v_device_group g ON g.device_key = p.device_key
          WHERE p.friendly_name <> '')
    GROUP BY physical_device_id
),
identities AS (
    SELECT physical_device_id,
           string_agg(device_key, '; ' ORDER BY preference) AS identities
    FROM member
    GROUP BY physical_device_id
),
evidence AS (
    SELECT physical_device_id, string_agg(evidence, '; ' ORDER BY evidence) AS evidence_sources
    FROM (SELECT DISTINCT g.physical_device_id, e.evidence
          FROM v_device_evidence e
          JOIN v_device_group g ON g.device_key = e.device_key)
    GROUP BY physical_device_id
)
SELECT
    m.physical_device_id,
    count(*)                                    AS identity_count,
    i.identities,
    e.enumerators,
    coalesce(d.grouping_methods, 'single_identity') AS grouping_methods,
    arg_min(m.device_instance_id, m.preference) AS device_instance_id,
    coalesce(arg_min(m.serial, m.preference) FILTER (WHERE m.serial <> ''), '') AS serial,
    -- No identity in the group reported a serial, so nothing here distinguishes
    -- this device from another of the same model.
    NOT bool_or(m.serial <> '' AND NOT m.serial_is_generated) AS identity_not_unique,
    coalesce(arg_min(m.friendly_name, m.preference) FILTER (WHERE m.friendly_name <> ''), '') AS friendly_name,
    coalesce(arg_min(m.device_desc, m.preference) FILTER (WHERE m.device_desc <> ''), '') AS device_desc,
    coalesce(arg_min(m.bus_reported_desc, m.preference) FILTER (WHERE m.bus_reported_desc <> ''), '') AS bus_reported_desc,
    coalesce(arg_min(m.mfg, m.preference) FILTER (WHERE m.mfg <> ''), '') AS mfg,
    coalesce(arg_min(m.class, m.preference) FILTER (WHERE m.class <> ''), '') AS class,
    coalesce(arg_min(m.class_guid, m.preference) FILTER (WHERE m.class_guid <> ''), '') AS class_guid,
    coalesce(arg_min(m.service, m.preference) FILTER (WHERE m.service <> ''), '') AS service,
    coalesce(arg_min(m.container_id, m.preference) FILTER (WHERE is_real_container(m.container_id)), '') AS container_id,
    coalesce(arg_min(m.hardware_id, m.preference) FILTER (WHERE m.hardware_id <> ''), '') AS hardware_id,
    bool_or(m.in_registry)                      AS in_registry,
    coalesce(p.portable_names, '')              AS portable_names,
    coalesce(l.current_drive_letters, '')       AS current_drive_letters,
    min(m.first_install_date_utc)               AS first_install_date_utc,
    max(m.install_date_utc)                     AS install_date_utc,
    max(m.last_arrival_date_utc)                AS last_arrival_date_utc,
    max(m.last_removal_date_utc)                AS last_removal_date_utc,
    sum(m.event_count)                          AS event_count,
    sum(m.connect_events)                       AS connect_events,
    sum(m.disconnect_events)                    AS disconnect_events,
    sum(m.install_events)                       AS install_events,
    sum(m.fault_events)                         AS fault_events,
    min(m.first_connect_utc)                    AS first_connect_utc,
    max(m.last_disconnect_utc)                  AS last_disconnect_utc,
    sum(m.setup_sections)                       AS setup_sections,
    min(m.first_seen_utc)                       AS first_seen_utc,
    max(m.last_seen_utc)                        AS last_seen_utc,
    sum(m.evidence_count)                       AS evidence_count,
    v.evidence_sources
FROM member m
JOIN identities   i USING (physical_device_id)
JOIN enumerators  e USING (physical_device_id)
JOIN evidence     v USING (physical_device_id)
LEFT JOIN methods  d USING (physical_device_id)
LEFT JOIN letters  l USING (physical_device_id)
LEFT JOIN portable p USING (physical_device_id)
GROUP BY m.physical_device_id, i.identities, e.enumerators, v.evidence_sources,
         d.grouping_methods, l.current_drive_letters, p.portable_names
ORDER BY m.physical_device_id;

-- ---- disks ----------------------------------------------------------------

CREATE VIEW v_disk AS
SELECT
    d.device_key,
    d.device_instance_id,
    d.disk_number,
    d.manufacturer,
    d.model,
    d.serial_number,
    d.bus_type,
    d.capacity,
    d.style,
    d.disk_guid,
    d.disk_signature,
    d.boot_record_signature,
    d.partition_count,
    count(p.partition_number)   AS partitions_decoded,
    -- A GPT partition is named by its own identifier; an MBR one has only a
    -- type byte and its offset, and printing an empty identifier for it would
    -- suggest the disk failed to yield something it never carried.
    string_agg(
        CASE WHEN p.partition_guid <> ''
             THEN coalesce(nullif(p.partition_name, '') || ' ', '') || p.partition_guid
             ELSE 'type ' || printf('%02x', p.mbr_type) ||
                  ' at offset ' || p.starting_offset
        END, '; ' ORDER BY p.partition_number) AS partitions,
    d.time_utc,
    d.record_id,
    d.warnings,
    d.source_id,
    s.path AS source_path
FROM disk_layout d
LEFT JOIN disk_partition p
  ON p.record_id = d.record_id AND p.source_id = d.source_id
LEFT JOIN source s ON s.id = d.source_id
GROUP BY ALL
ORDER BY d.disk_number, d.time_utc, d.record_id, d.source_id;

-- ---- connection windows ---------------------------------------------------

-- Every record that says a device arrived or went away.
--
-- Two exclusions matter here. A Kernel-PnP 420 is a removal only when the
-- problem code is 45, CM_PROB_DEVICE_DISCONNECTED; with any other code it is a
-- fault on a device that is still present, and counting it as a removal would
-- end a connection that never ended. And the Ntfs volume mount records are left
-- out because they name \Device\HarddiskVolumeN rather than a device: they say
-- a volume mounted, not which device it was on.
CREATE VIEW v_device_state_change AS
SELECT
    e.device_key,
    e.device_instance_id,
    e.time_utc,
    CASE WHEN e.kind = 'connect' THEN 'arrival' ELSE 'departure' END AS state,
    e.channel,
    e.event_id,
    e.rule_id,
    e.meaning,
    e.record_id,
    e.source_id,
    coalesce((SELECT f.value FROM event_field f
              WHERE f.source_id = e.source_id AND f.record_id = e.record_id
                AND f.role = 'problem_code' LIMIT 1), '') AS problem_code
FROM v_event e
WHERE e.kind IN ('connect', 'disconnect')
  AND e.device_key <> ''
  AND NOT (e.event_id = 420
           AND coalesce((SELECT f.value FROM event_field f
                         WHERE f.source_id = e.source_id
                           AND f.record_id = e.record_id
                           AND f.role = 'problem_code' LIMIT 1), '') <> '45');

-- A Partition/Diagnostic 1006 record whose disk has no capacity.
--
-- The partition driver describes a disk it can see. On USB-LENOVO-Multi-USBs
-- each of the four test sticks has a positive-capacity record at its known
-- arrival and a capacity-zero record at its known removal — 02:12:10 for
-- GEN32GBF32, 02:20:11 for KING64NTFS, 02:19:15 for Sam64ExFAT and 02:24:10 for
-- SAN64FAT32 — every one of them agreeing to the second with StorageVolume
-- 1001/1002, which is the channel the connection windows are actually built
-- from. It is a real removal signal and the collection shows it working.
--
-- It is a *candidate* and not a departure, and the reason is a device this tool
-- exists to examine. A multi-slot card reader reports zero capacity for an
-- empty slot, continuously, while the reader itself never leaves the port. Read
-- as a removal that would close a window at every one of them and then reopen
-- nothing, because no arrival follows an empty slot either. Nothing in the five
-- collections has a card reader with an empty slot, so nothing here can say how
-- often that shape occurs or how to tell it from a stick being pulled.
--
-- So the record is surfaced with what corroborates it and closes no window.
-- Promoting it needs calibration across more Windows versions and at least one
-- collection with a card reader in it; see docs/OPEN-WORK.md. What it
-- is worth today is a collection where the storage channels are absent, where
-- this is the only thing that says a device went away at all — and an analyst
-- can only use it if it is in front of them.
-- Read from the event and its fields rather than from disk_layout, which is
-- where the first attempt went and where these records are not. A row reaches
-- disk_layout only when it carried a drive layout or a boot record to decode,
-- and a disk with no capacity carries neither — so the whole population this
-- view is about was filtered out one step upstream and it returned nothing on
-- every collection. Worth remembering: "the table named after the artefact"
-- and "the records of that artefact" are not the same set.
CREATE VIEW v_disk_departure_candidate AS
WITH capacity AS (
    SELECT e.record_id, e.source_id, e.device_key, e.device_instance_id,
           e.time_utc, e.channel, e.source_path,
           (SELECT f.value FROM event_field f
            WHERE f.source_id = e.source_id AND f.record_id = e.record_id
              AND f.role = 'capacity' LIMIT 1) AS capacity
    FROM v_event e
    WHERE e.event_id = 1006 AND e.time_utc IS NOT NULL AND e.device_key <> ''
)
SELECT
    c.device_key,
    c.device_instance_id,
    c.time_utc,
    -- Whether a channel that does close a window recorded a departure for this
    -- device near the same moment. Two minutes either side: the reference
    -- pairs agree to the second, and the margin is for a host reporting the
    -- two through different subsystems rather than for a doubtful match.
    --
    -- Matched on the physical device and not on the devnode, which is the
    -- standing rule and is load-bearing here rather than tidy. The partition
    -- driver names the USB node — USB\VID_1F75&PID_0918\19786581 — while
    -- StorageVolume names the volume's own, so on device_key alone every one
    -- of the ten candidates on USB-LENOVO-Multi-USBs read as uncorroborated
    -- while the storage channel had recorded the same removal to the second.
    -- An uncorroborated candidate is the weaker finding, so the wrong answer
    -- was the quiet one.
    EXISTS (
        SELECT 1
        FROM v_device_state_change d
        JOIN v_device_group gd ON gd.device_key = d.device_key
        JOIN v_device_group gc ON gc.device_key = c.device_key
        WHERE gd.physical_device_id = gc.physical_device_id
          AND d.state = 'departure'
          AND abs(date_diff('second', d.time_utc, c.time_utc)) <= 120
    ) AS corroborated_by_a_recorded_departure,
    c.channel,
    c.record_id,
    c.source_id,
    c.source_path
FROM capacity c
-- The value is the string the record carried, so a field that was absent and a
-- capacity reported as zero are different things and only the second is this.
WHERE trim(coalesce(c.capacity, '')) IN ('0', '0x0')
ORDER BY c.time_utc, c.device_key, c.record_id, c.source_id;

-- Arrivals and departures paired into the intervals a device was connected.
--
-- Several channels report the same arrival at once, so a cluster of records of
-- the same state is one transition and not several connections. The first
-- record of the cluster opens the window, because that is the earliest moment
-- the evidence places the device on the machine.
--
-- A cluster is bounded in time, and that bound is the whole point. This was
-- once written as an unbounded run of the same state, which meant a second
-- arrival with no removal logged between the two was not a new window but part
-- of the first — so the record was discarded and the window ran on to whatever
-- came next. On USB-LENOVO-Multi-USBs a SanDisk connected at 2026-08-04
-- 02:21:17 was swallowed by an arrival from 2025-08-17, and the run reported
-- one connection spanning 8438 hours, dated the device's arrival eleven months
-- early, and lifted every drive-letter attribution in that span to probable.
--
-- Fifteen seconds is the tolerance, and it is bounded from both sides.
--
-- Below it: a cluster can span several channels. The reference collections all
-- carry StorageVolume 1001 alone, where the duplicates are one record per
-- volume and fall within 2 ms — so they say nothing about the cross-channel
-- case. TestRepeatedArrivalsAreOneConnection is what does: a Kernel-PnP
-- arrival, a StorageVolume mount two seconds later and a DeviceSetupManager
-- record four seconds after that are one connection seen three times, and a
-- tolerance under six seconds splits them. Setting this from the collections
-- alone gave two seconds and broke that test, which is the test doing its job.
--
-- Above it: the narrowest same-state gap in the reference evidence that is a
-- genuine second connection is 80.5 seconds. Fifteen sits between the two with
-- room either way.
--
-- The error is not symmetric and the margin is deliberately larger on the low
-- side. Too tight splits one arrival into two windows, which understates and
-- adds a row. Too loose swallows a connection and states a device was attached
-- when nothing says it was. Note that the tolerance only ever applies to two
-- arrivals with no departure logged between them: a real unplug and replug
-- writes a departure, which ends the cluster whatever the gap.
--
-- Three shapes are deliberately not tidied away. An arrival with no departure
-- after it is an open window: the evidence does not say the device was removed,
-- and closing it at the end of the log would manufacture a removal. An arrival
-- superseded by another arrival is a different open window — the device must
-- have gone away in between, but nothing recorded when, so the interval has a
-- bound (ended_before_utc) rather than an end. And a departure with no arrival
-- before it means the device was already connected when the evidence begins,
-- and its start is unknown rather than equal to the first record.
-- The host starting, stopping, sleeping and waking.
--
-- These name no device and are not device evidence. They are here because they
-- are the only thing that says what a silence means. A connection with no
-- removal recorded reads one way if the machine was shut down with the stick
-- still in it and another way if it ran on for a week afterwards, and an hour
-- with no records is a quiet hour or an hour switched off.
--
-- Keyed on rule_id and not on the event id, because an event id belongs to its
-- provider rather than to the channel: 12 on the System channel is
-- Kernel-General's operating-system start and is also written by three other
-- publishers about other things. The catalogue already drew that line and this
-- reads the line it drew.
CREATE VIEW v_session_event AS
SELECT
    e.time_utc,
    CASE e.rule_id
        WHEN 'System:EventLog:6005'                       THEN 'started'
        WHEN 'System:Microsoft-Windows-Kernel-General:12'  THEN 'started'
        WHEN 'System:Microsoft-Windows-Kernel-Power:107'   THEN 'woke'
        WHEN 'System:EventLog:6006'                       THEN 'stopped'
        WHEN 'System:Microsoft-Windows-Kernel-General:13'  THEN 'stopped'
        WHEN 'System:EventLog:6008'                       THEN 'stopped_unexpectedly'
        WHEN 'System:Microsoft-Windows-Kernel-Power:41'    THEN 'stopped_unexpectedly'
        WHEN 'System:Microsoft-Windows-Kernel-Power:42'    THEN 'slept'
        -- A shutdown was asked for. It is not the shutdown, and it is the only
        -- session record that names who asked.
        WHEN 'System:User32:1074'                         THEN 'stop_requested'
        -- The daily uptime report. It ends nothing; it places the host as
        -- switched on at a moment, which is what makes a nearby silence
        -- readable.
        WHEN 'System:EventLog:6013'                       THEN 'running'
    END AS state,
    e.channel, e.provider, e.event_id, e.rule_id, e.meaning,
    e.record_id, e.source_id, e.source_path
FROM v_event e
WHERE e.kind = 'session' AND e.time_utc IS NOT NULL;

-- The moments the host went off, which is what can bound an open window.
--
-- Only the recorded, clean stops. An unclean stop is not one of these and is
-- the view below: 6008 and Kernel-Power 41 are written by the *next* boot,
-- having discovered that the last shutdown was not clean, so their record time
-- dates the discovery and not the loss of power. Read as a stop instant they
-- extended every open window across the whole outage — a host off for a week
-- went on placing a device on itself for that week — and the direction of the
-- error is the dangerous one, because it manufactures attachment.
CREATE VIEW v_host_stopped AS
SELECT time_utc, state, rule_id, record_id, source_id, source_path
FROM v_session_event
WHERE state = 'stopped';

-- An unclean stop, bounded rather than dated.
--
-- What the record establishes is an interval: the host went off after the last
-- thing it recorded and before the boot that noticed. Neither end is the stop
-- and the evidence does not contain it. 6008 renders a previous-shutdown time
-- in its message, and it is deliberately not read here — the value is a
-- locale-rendered string, no reference collection carries a record to check a
-- decoder against, and inventing a template is the mistake already recorded
-- against the UMDF request codes. When one real record turns up, that becomes
-- a better stopped_before_utc than the boot.
--
-- boot_utc is the start that reported it: 41 and 6008 are written during
-- startup, so the nearest preceding start or resume is the session doing the
-- reporting. stopped_after_utc is the last thing the host recorded before that
-- start, which is the last moment anything says it was running.
--
-- **The nearest preceding start is a candidate, not the reporting boot**, and
-- reading it as one is how the record-time defect grew back in a quieter form.
-- Two shapes produce a wrong answer. Where the reporting session's own start
-- was never logged — a truncated System channel, a collection that begins
-- mid-history — the nearest preceding start is the boot *before* the outage,
-- so the interval is drawn across a session that ended normally. And where no
-- start was recorded at all, the old coalesce fell back to the report's own
-- time, and the last event before *that* is a boot-time record from the
-- restarted session: the interval then reaches forwards past the very outage
-- it exists to bound, and a device goes on being placed on the machine after
-- it came back.
--
-- So the association is tested rather than assumed. A candidate start is the
-- reporting boot only if the session it began is still running when the record
-- is written, which is to say no clean stop lies between the two. Where it
-- fails, the record stays in the evidence and stays on the timeline — the host
-- did stop uncleanly, and that is worth knowing — and stopped_after_utc is
-- NULL, so no window may reach through it. A bound nobody can establish is
-- withheld rather than guessed, which is the same discipline as an MRU entry
-- below position 0.
--
-- Only clean stops are tested for. An unclean stop between the two would be
-- one reported by the same startup — 41 and 6008 are routinely written seconds
-- apart by one boot — so counting those would make every host that logs both
-- abstain. A previous session that also died uncleanly leaves no record at all
-- until a boot discovers it, and that boot is the one already established as
-- missing, so there is nothing there to test against.
CREATE VIEW v_host_unclean_stop AS
WITH reported AS (
    SELECT time_utc AS reported_utc, rule_id, record_id, source_id, source_path
    FROM v_session_event
    WHERE state = 'stopped_unexpectedly'
),
booted AS (
    SELECT r.*,
           (SELECT max(s.time_utc) FROM v_session_event s
             WHERE s.state IN ('started', 'woke')
               AND s.time_utc <= r.reported_utc) AS candidate_boot_utc
    FROM reported r
),
associated AS (
    SELECT b.*,
           b.candidate_boot_utc IS NOT NULL
             AND NOT EXISTS (
                 SELECT 1 FROM v_session_event s
                  WHERE s.state = 'stopped'
                    AND s.time_utc > b.candidate_boot_utc
                    AND s.time_utc < b.reported_utc) AS boot_associated
    FROM booted b
)
SELECT
    a.reported_utc,
    a.boot_associated,
    CASE WHEN a.boot_associated THEN a.candidate_boot_utc END AS boot_utc,
    -- The stop is no later than the boot that found it. Where the reporting
    -- boot is not established the report's own time is still a true upper
    -- bound — the host cannot have gone off after the record saying it did —
    -- so it is kept, and it is only the lower bound that is withheld.
    CASE WHEN a.boot_associated THEN a.candidate_boot_utc
         ELSE a.reported_utc END AS stopped_before_utc,
    -- And no earlier than the last evidence of the session that died. This is
    -- the end an open window is allowed to reach, because it is the last moment
    -- the host is known to have been on. It rests entirely on having identified
    -- the reporting boot, so it is offered only where that was established.
    CASE WHEN a.boot_associated THEN
        (SELECT max(e.time_utc) FROM v_event e
          WHERE e.time_utc < a.candidate_boot_utc) END AS stopped_after_utc,
    a.rule_id, a.record_id, a.source_id, a.source_path
FROM associated a;

CREATE VIEW v_connection AS
WITH ordered AS (
    SELECT *,
           lag(state)    OVER w AS previous_state,
           lag(time_utc) OVER w AS previous_time
    FROM v_device_state_change
    WINDOW w AS (PARTITION BY device_key ORDER BY time_utc, record_id)
),
transitions AS (
    SELECT * FROM ordered
    WHERE previous_state IS NULL
       OR previous_state <> state
       OR date_diff('millisecond', previous_time, time_utc) > 15000
),
paired AS (
    SELECT *,
           lead(state)     OVER w AS next_state,
           lead(time_utc)  OVER w AS next_time,
           lead(rule_id)   OVER w AS next_rule,
           lead(record_id) OVER w AS next_record
    FROM transitions
    WINDOW w AS (PARTITION BY device_key ORDER BY time_utc, record_id)
),
windows AS (
    SELECT
        device_key, device_instance_id,
        time_utc AS started_utc,
        CASE WHEN next_state = 'departure' THEN next_time END AS ended_utc,
        CASE WHEN next_state = 'arrival'   THEN next_time END AS ended_before_utc,
        true  AS start_known,
        rule_id AS opened_by,
        record_id AS opened_by_record,
        CASE WHEN next_state = 'departure' THEN next_rule END   AS closed_by,
        CASE WHEN next_state = 'departure' THEN next_record END AS closed_by_record,
        source_id
    FROM paired
    WHERE state = 'arrival'

    UNION ALL

    SELECT
        device_key, device_instance_id,
        NULL AS started_utc,
        time_utc AS ended_utc,
        NULL AS ended_before_utc,
        false AS start_known,
        '' AS opened_by,
        NULL AS opened_by_record,
        rule_id AS closed_by,
        record_id AS closed_by_record,
        source_id
    FROM paired
    WHERE state = 'departure' AND previous_state IS NULL
)
SELECT
    w.device_key,
    w.device_instance_id,
    w.started_utc,
    w.ended_utc,
    -- When the device arrived again with no removal logged in between. It left
    -- at some point before this and nothing says when, so this is the latest
    -- the window can have ended, not the moment it did.
    w.ended_before_utc,
    w.start_known,
    (w.ended_utc IS NULL) AS open_ended,
    -- The span between the two records, which is not the same as the time the
    -- device was connected. The evidence says a device arrived and that the
    -- next removal recorded for it came later; whether it stayed connected
    -- throughout is not recorded anywhere, and a log that rolled in between
    -- leaves exactly this shape. Naming the column a duration would state a
    -- continuity nothing evidenced.
    CASE WHEN w.started_utc IS NOT NULL AND w.ended_utc IS NOT NULL
         THEN date_diff('second', w.started_utc, w.ended_utc) END AS span_seconds,
    -- Where an open window is followed by the host going off. Only for a window
    -- that no removal and no second arrival closed: those already have an end
    -- and a shutdown after them says nothing.
    --
    -- This explains the missing removal rather than supplying one. A shutdown
    -- with a device still attached writes no departure record — that is the
    -- normal way for a window to end with nothing recorded — so the shutdown is
    -- both why the window is open and the point past which it cannot go on
    -- meaning the device was there.
    CASE WHEN w.ended_utc IS NULL AND w.ended_before_utc IS NULL THEN (
        SELECT min(h.time_utc) FROM v_host_stopped h
        WHERE h.time_utc > w.started_utc) END      AS host_stopped_utc,
    -- The same explanation from an unclean stop, which supplies a bound rather
    -- than a moment. host_stopped_after_utc is the last evidence the host was
    -- running, and is as far as the window can reach; host_stopped_before_utc
    -- is the boot that reported the stop, and is where the outage certainly
    -- ended. The gap between them is the outage, and the stop is somewhere in
    -- it. They are separate columns from host_stopped_utc because a recorded
    -- shutdown and an inferred one are different claims and merging them would
    -- lose which was which.
    CASE WHEN w.ended_utc IS NULL AND w.ended_before_utc IS NULL THEN (
        SELECT u.stopped_after_utc FROM v_host_unclean_stop u
        WHERE u.stopped_after_utc > w.started_utc
        ORDER BY u.stopped_after_utc, u.reported_utc, u.record_id
        LIMIT 1) END                               AS host_stopped_after_utc,
    CASE WHEN w.ended_utc IS NULL AND w.ended_before_utc IS NULL THEN (
        SELECT u.stopped_before_utc FROM v_host_unclean_stop u
        WHERE u.stopped_after_utc > w.started_utc
        ORDER BY u.stopped_after_utc, u.reported_utc, u.record_id
        LIMIT 1) END                               AS host_stopped_before_utc,
    -- An unclean stop that could not be dated at all, because the boot that
    -- reported it was not established. It bounds nothing — that is the whole
    -- point of withholding stopped_after_utc — and the window must not be
    -- described as one the host was never recorded going off during, which is
    -- what the open-ended wording would otherwise say on such a host. Absence
    -- is reported as absence, and this is not an absence.
    CASE WHEN w.ended_utc IS NULL AND w.ended_before_utc IS NULL THEN EXISTS (
        SELECT 1 FROM v_host_unclean_stop u
        WHERE NOT u.boot_associated
          AND u.reported_utc > w.started_utc) END  AS host_stopped_undated,
    w.opened_by,
    w.closed_by,
    -- How many records the window rests on. One is a claim resting on a single
    -- record; several channels agreeing is a stronger thing to report.
    (SELECT count(*) FROM v_device_state_change c
      WHERE c.device_key = w.device_key
        AND (w.started_utc IS NULL OR c.time_utc >= w.started_utc)
        AND (coalesce(w.ended_utc, w.ended_before_utc) IS NULL
             OR c.time_utc <= coalesce(w.ended_utc, w.ended_before_utc)))
        AS supporting_records,
    w.opened_by_record,
    w.closed_by_record,
    w.source_id
FROM windows w
ORDER BY w.device_key, w.started_utc NULLS FIRST, w.ended_utc NULLS LAST, w.opened_by_record NULLS LAST,
         w.closed_by_record NULLS LAST;

-- The connection windows that can place a device on the machine at a moment.
--
-- Not every window can. A window superseded by a later arrival is an interval
-- the device left during and nothing recorded when, so a record falling inside
-- it is no more placed on that device than a record falling outside. Treating
-- it as coverage is how a shell bag written at 02:09 came to be attributed,
-- probable and unopposed, to a device that arrived at 02:21.
--
-- A window that is open because nothing follows it is different and does place
-- the device: the evidence simply ends while the device is attached, which is
-- what a collection taken with the stick still in the port looks like. The
-- Velociraptor run on PATRIOT is exactly that shape.
--
-- A window whose start is unknown is excluded because there is no lower bound
-- to test a record against.
-- An open window stops placing the device once the host goes off. Until this
-- was read, an open window placed records for ever after the arrival: a stick
-- that arrived, was left in, and was still recorded as attached when the
-- machine shut down went on covering every record made after the next boot and
-- for the rest of the evidence. That is the same unbounded-window error that
-- the twenty-four-hour rule on sole_connected_device was written for, reached
-- from the other side, and here the evidence supplies the bound outright rather
-- than a calibrated guess standing in for it.
--
-- places_until_utc is not an end. ended_utc means a removal was recorded;
-- host_stopped_utc means the machine went off and the device stopped being
-- attached to a running host, whatever happened to it afterwards. The two are
-- kept apart in the columns and only joined here, where the question is how far
-- the window reaches.
--
-- An unclean stop reaches it through host_stopped_after_utc — the last moment
-- the host is known to have been running — and never through the record time
-- of the 41 or 6008 that reported it, which is written after the machine came
-- back. Taking the earlier of the two candidates is the conservative reading in
-- both directions: a window that a clean shutdown already closed cannot be
-- extended by an unclean one, and a window whose evidence simply runs out
-- stops at the last thing the host recorded rather than at the far side of an
-- outage. The coalesce pair is least() over two nullable values without
-- depending on how least() treats a NULL.
CREATE VIEW v_connection_placing AS
SELECT *,
       coalesce(ended_utc,
                least(coalesce(host_stopped_utc, host_stopped_after_utc),
                      coalesce(host_stopped_after_utc, host_stopped_utc)))
           AS places_until_utc
FROM v_connection
WHERE start_known AND started_utc IS NOT NULL AND ended_before_utc IS NULL;

-- The PnP lifecycle dates a devnode stores.
--
-- These are states, not a history: a device connected fifty times has one
-- LastArrivalDate. They are kept apart from v_connection for that reason —
-- reading them as a connection would report one visit for fifty.
CREATE VIEW v_device_lifecycle AS
SELECT
    device_key,
    normalised_instance_id AS device_instance_id,
    control_set,
    first_install_date_utc,
    install_date_utc,
    last_arrival_date_utc,
    last_removal_date_utc,
    key_last_write_utc,
    'most recent event of each kind only; not a connection history' AS caveat,
    source_id,
    -- The hive these dates were read out of. It was missing here until a real
    -- report showed four device_state rows on the timeline naming their control
    -- set and no file at all, beside a fifth from v_devnode that named one.
    source_path
FROM v_devnode
WHERE device_key <> ''
  AND (first_install_date_utc IS NOT NULL OR install_date_utc IS NOT NULL
       OR last_arrival_date_utc IS NOT NULL OR last_removal_date_utc IS NOT NULL)
ORDER BY device_key, control_set, source_id;

-- ---- volumes and the device links -----------------------------------------

-- A volume as MountedDevices recorded it: the mount point on one side and
-- whatever identifies the volume on the other.
--
-- Nothing here is time-bound. MountedDevices holds the mapping as it stands
-- now, and a drive letter is reused, so this says which volume holds a letter
-- today and never which one held it when a file was opened.
CREATE VIEW v_volume AS
SELECT
    m.value_name,
    m.kind                                   AS mount_kind,
    m.drive_letter,
    m.volume_guid,
    m.target_kind,
    m.device_instance_id,
    m.device_key,
    m.partition_guid,
    m.disk_signature,
    m.partition_offset,
    m.target_volume_guid,
    m.source_id,
    s.path AS source_path
FROM mount_entry m
LEFT JOIN source s ON s.id = m.source_id;

-- Every route from a volume to a device, one row per route, each carrying the
-- confidence the route earns rather than the confidence the answer needs.
--
-- A volume reached by several routes gets several rows. Agreement between two
-- independent routes is worth more than either alone, and collapsing them to a
-- single answer would throw away the corroboration along with the disagreement.
CREATE VIEW v_device_volume_link AS

-- The strongest link there is: the stored value names the device outright.
SELECT
    v.device_key,
    v.device_instance_id,
    'mount_point'        AS volume_kind,
    v.value_name         AS volume_id,
    v.drive_letter,
    ''                   AS volume_label,
    'mounted_devices_device_path' AS route,
    'confirmed'          AS confidence,
    'the MountedDevices value holds the device instance path' AS detail,
    v.source_id
FROM v_volume v
WHERE v.target_kind = 'device_path' AND v.device_key <> ''

UNION ALL

-- The GPT route. MountedDevices stores a partition identifier that names no
-- disk; the Partition/Diagnostic record names both the identifier and the
-- device the disk sits on. Strong rather than confirmed because the two facts
-- come from artefacts written at different times: the record describes the disk
-- as it was then, and the mapping is as it stands now.
SELECT
    d.device_key,
    d.device_instance_id,
    'mount_point',
    v.value_name,
    v.drive_letter,
    '',
    'gpt_partition_guid',
    'strong',
    'partition ' || p.partition_name || ' on disk ' || d.disk_number ||
        ' carries the identifier MountedDevices stores for this volume',
    v.source_id
FROM v_volume v
JOIN disk_partition p ON lower(p.partition_guid) = lower(v.partition_guid)
JOIN disk_layout d ON d.record_id = p.record_id AND d.source_id = p.source_id
WHERE v.target_kind = 'gpt_partition_guid' AND v.partition_guid <> ''
  AND d.device_key <> ''

UNION ALL

-- The MBR route. The signature identifies the disk and the offset the partition
-- on it, so both must agree: a signature match with a different offset is a
-- different volume on the same disk.
SELECT
    d.device_key,
    d.device_instance_id,
    'mount_point',
    v.value_name,
    v.drive_letter,
    '',
    'mbr_disk_signature',
    'strong',
    'disk signature and partition offset both match disk ' || d.disk_number,
    v.source_id
FROM v_volume v
JOIN disk_layout d
  ON (d.disk_signature = v.disk_signature
      OR d.boot_record_signature = v.disk_signature)
JOIN disk_partition p
  ON p.record_id = d.record_id AND p.source_id = d.source_id
 AND p.starting_offset = v.partition_offset
WHERE v.target_kind = 'mbr_disk_signature' AND v.disk_signature <> 0
  AND d.device_key <> ''

UNION ALL

-- The label route, which is what remains when EMDMgmt is not written — and it
-- is not written on any current Windows. A label is set by whoever formatted
-- the volume and can be reused, so this is offered only where the label is
-- unique among the portable devices on this host, and rated no higher than
-- possible on its own.
--
-- And only where the key names a mass-storage identity. Windows Portable
-- Devices is not a storage list: it holds phones, cameras and media players
-- whose FriendlyName is a user-facing device name — "Pixel 8", "Jane's iPad" —
-- rather than a filesystem label, and a name like that coincidentally matching
-- a label a shell link recorded would build a device candidate on nothing. The
-- key embeds the enumerated identity behind it, so the test is that identity's
-- enumerator; every one of the nine label links across the five reference
-- collections is USBSTOR, so this is latent there and it is not latent on a
-- host with a phone plugged into it.
--
-- The uniqueness check below is deliberately *not* narrowed the same way. A
-- phone sharing a name with a stick should suppress the route rather than be
-- ignored by it, which is the direction that fails safely.
SELECT
    p.device_key,
    p.device_instance_id,
    'volume_label',
    p.friendly_name,
    '',
    p.friendly_name,
    'portable_device_label',
    'possible',
    'the label is unique among the portable devices recorded on this host',
    p.source_id
FROM portable_device p
JOIN (
    SELECT friendly_name
    FROM (SELECT DISTINCT friendly_name, device_key FROM portable_device
          WHERE device_key <> '' AND friendly_name <> '')
    GROUP BY friendly_name
    HAVING count(*) = 1
) unique_labels USING (friendly_name)
WHERE p.device_key <> '' AND p.friendly_name <> ''
  AND identity_enumerator(p.device_instance_id)
      IN ('USBSTOR', 'SCSI', 'STORAGE')
-- After the union, so it orders the whole of it. Every column is in the key:
-- a device can reach one volume by several routes and the rows are otherwise
-- indistinguishable to a sort.
ORDER BY device_key, volume_kind, volume_id, drive_letter, volume_label,
         route, confidence, detail, source_id;

-- A label recorded for more than one device resolves nothing, and saying so is
-- a finding: it is the reason a volume that looks identifiable is not.
CREATE VIEW v_ambiguous_label AS
SELECT friendly_name AS volume_label,
       count(*)      AS device_count,
       string_agg(device_instance_id, '; ' ORDER BY device_instance_id) AS devices
FROM (SELECT DISTINCT friendly_name, device_key, device_instance_id
      FROM portable_device WHERE device_key <> '' AND friendly_name <> '')
GROUP BY friendly_name
HAVING count(*) > 1;

-- ---- file activity --------------------------------------------------------

-- v_removable_volume is defined below, after v_file_activity, because it is
-- one of the two views that used to reach past it for a timestamp.

-- Folders Explorer displayed, and the files opened or saved through it.
--
-- Both are keyed by drive letter and nothing else, which is exactly the join
-- §7 says is unsafe on its own. They are reported as what they are — a place
-- and a letter — and the device behind that letter is the correlation phase's
-- question, not this view's answer.
CREATE VIEW v_shell_bag AS
SELECT
    b.drive_letter,
    b.path,
    b.path_has_gap,
    b.name,
    b.kind,
    b.hive,
    b.profile,
    b.depth,
    b.mru_position,
    b.node_slot,
    b.modified_local,
    b.created_local,
    b.accessed_local,
    b.key_last_write_utc,
    b.mft_entry,
    b.mft_sequence,
    b.raw_modified,
    b.registry_path,
    b.warnings,
    b.source_id,
    s.path   AS source_path,
    s.sha256 AS source_sha256
FROM shell_bag b
LEFT JOIN source s ON s.id = b.source_id
ORDER BY b.hive, b.profile, b.path, b.registry_path, b.node_slot, b.source_id;

CREATE VIEW v_mru_entry AS
SELECT
    m.drive_letter,
    m.letter_from_name,
    m.volume_label,
    m.path,
    m.path_has_gap,
    m.name,
    m.kind,
    m.source_list,
    m.profile,
    m.position,
    m.modified_local,
    m.key_last_write_utc,
    m.value_name,
    m.raw_modified,
    m.registry_path,
    m.warnings,
    m.source_id,
    s.path   AS source_path,
    s.sha256 AS source_sha256
FROM mru_entry m
LEFT JOIN source s ON s.id = m.source_id
ORDER BY m.kind, m.source_list, m.position, m.value_name, m.profile, m.registry_path, m.source_id;

-- What the shell recorded a user launching.
--
-- The other half of the execution picture, and a different half from prefetch:
-- prefetch is per machine and covers anything the loader touched, so a service
-- starting looks the same as a person double-clicking, while this is per user
-- and records what Explorer launched. It also counts focus, which prefetch
-- cannot — on USB-CTF `F:\KAPE\gkape.exe` was in the foreground for 83
-- seconds, and no other artefact Boobook reads mentions it at all.
CREATE VIEW v_user_assist AS
SELECT
    u.name,
    u.drive_letter,
    u.run_count,
    u.focus_count,
    u.focus_seconds,
    u.last_executed_utc,
    u.category,
    -- Named only for the two GUIDs that are settled; the rest are carried as
    -- the GUID they are, because the published lists are incomplete and a wrong
    -- category is worse than none.
    u.category_name,
    u.bookkeeping,
    u.profile,
    u.registry_path,
    u.warnings,
    u.source_id,
    s.path   AS source_path,
    s.sha256 AS source_sha256
FROM user_assist u
LEFT JOIN source s ON s.id = u.source_id
ORDER BY u.last_executed_utc DESC NULLS LAST, u.name, u.profile,
         u.category, u.source_id;

-- Every file and folder record in one shape, whichever artefact holds it.
--
-- recorded_utc is the best UTC instant the record carries and recorded_meaning
-- says what that instant actually is, because they are not the same thing. A
-- jump list access time is when the file was opened. A registry key write is
-- when the key was last written, which is close to the access and is not it. A
-- link's target-written time describes the file, not the opening of it. Sorting
-- them into one column without saying which is which is how a timeline acquires
-- events that never happened.
--
-- The FAT timestamps shell items carry are not here at all: they are local wall
-- clock with no zone, so they cannot be compared with a UTC connection window.
-- ---- prefetch --------------------------------------------------------------

-- Whether the host was recording programme launches, as one sentence.
CREATE VIEW v_host_prefetch_setting AS
SELECT registry_key, control_set, value_found, raw_value, description, source_id
FROM host_prefetch_setting;

-- Which volume a prefetch file's own executable ran from.
--
-- Not from executable_path, which is the obvious route and does not work. On
-- the reference evidence Windows 11 records that path as
-- \DEVICE\HARDDISKVOLUME4\WINDOWS\SYSTEM32\SVCHOST.EXE while the volume block
-- for the same file names \VOLUME{01dc0f73...}, so the two never share a
-- prefix; and for a packaged application it is not a path at all but an
-- identifier such as MicrosoftWindows.Client.CBS_1000.26100.334.0_x64. Matched
-- that way every run on the reference host resolved to no volume.
--
-- What does work is that a prefetch file lists its own executable among the
-- files the loader touched, and those paths do carry the volume's device path.
--
-- The fallback is deliberately narrow: one volume and no file list at all. A
-- file list that does not contain the executable is not silence, it is evidence
-- that the programme lived somewhere this record does not name, and treating
-- "the only volume here" as "the volume it ran from" would report a programme
-- on the system disk that opened one file on a stick as having run off the
-- stick. That is the difference the whole finding turns on.
--
-- Where two volumes are equally good this view says nothing. It used to take
-- the lexicographically first device path, which is a decision made by sorting
-- rather than by evidence: two listed files sharing the 29-character truncated
-- prefix on different volumes is exactly the case the prefix match exists to
-- handle, and it is exactly the case where the record does not say which of
-- them ran. An arbitrary pick there does not produce a doubtful answer, it
-- produces a confident one — the route reaches a device, ran_from is set, and
-- executable_run_from_removable carries score weight. So a tie abstains, and
-- every candidate is exported through v_prefetch_run_volume_candidate, because
-- an abstention nobody can see is indistinguishable from a record that named
-- no volume at all.
CREATE VIEW v_prefetch_run_volume AS
WITH self_load AS (
    SELECT
        f.source_file,
        v.device_path,
        v.volume_serial_hex,
        v.created_utc,
        -- An exact name outranks a prefix. The header truncates the executable
        -- name at 29 characters — COLLECTOR_VELOCIRAPTOR-V0.77. on the
        -- reference evidence, for an executable ending -WINDOWS-AMD64.EXE — so
        -- the prefix is how a truncated name is recovered, and the exact match
        -- is how an untruncated one is confirmed rather than guessed.
        CASE WHEN upper(regexp_extract(f.path, '[^\\]+$')) = upper(r.executable)
             THEN 1 ELSE 2 END AS precision
    FROM prefetch_file f
    JOIN prefetch_run r ON r.source_file = f.source_file
    JOIN prefetch_volume v
      ON v.source_file = f.source_file
     AND starts_with(upper(f.path), upper(v.device_path))
    WHERE r.executable <> ''
      AND starts_with(upper(regexp_extract(f.path, '[^\\]+$')),
                      upper(r.executable))
),
ranked AS (
    SELECT DISTINCT source_file, device_path, volume_serial_hex, created_utc,
           min(precision) OVER (PARTITION BY source_file) AS best_precision,
           precision
    FROM self_load
),
best AS (
    SELECT source_file, device_path, volume_serial_hex, created_utc, precision,
           -- Distinct volumes holding the best precision. Counted over the
           -- volume rather than over the row because one volume can hold
           -- several listed files that match, and that is agreement rather
           -- than ambiguity.
           count(DISTINCT device_path) OVER (PARTITION BY source_file)
               AS best_candidates
    FROM ranked
    WHERE precision = best_precision
),
picked AS (
    SELECT * FROM best WHERE best_candidates = 1
)
SELECT source_file, device_path, volume_serial_hex, created_utc,
       'the prefetch file lists its own executable on this volume' AS basis
FROM picked

UNION ALL

SELECT r.source_file, v.device_path, v.volume_serial_hex, v.created_utc,
       'the prefetch file named exactly one volume and listed no files'
FROM prefetch_run r
JOIN prefetch_volume v ON v.source_file = r.source_file
WHERE r.volume_count = 1 AND r.file_count = 0
  AND r.source_file NOT IN (SELECT source_file FROM picked);

-- Every volume that could have held a prefetch record's own executable, with
-- the precision of the match and whether it was the one this run concluded on.
--
-- This exists because v_prefetch_run_volume abstains on a tie, and an
-- abstention that leaves no trace reads exactly like a record that named no
-- volume — which is a different and much weaker fact about the evidence. Here
-- an analyst can see that two volumes matched, at what precision, and that
-- Boobook declined to choose between them rather than failing to find either.
CREATE VIEW v_prefetch_run_volume_candidate AS
WITH candidate AS (
    SELECT DISTINCT
        f.source_file,
        r.executable,
        v.device_path,
        v.volume_serial_hex,
        CASE WHEN upper(regexp_extract(f.path, '[^\\]+$')) = upper(r.executable)
             THEN 'exact name' ELSE 'truncated header prefix' END AS match_precision,
        CASE WHEN upper(regexp_extract(f.path, '[^\\]+$')) = upper(r.executable)
             THEN 1 ELSE 2 END AS rank_
    FROM prefetch_file f
    JOIN prefetch_run r ON r.source_file = f.source_file
    JOIN prefetch_volume v
      ON v.source_file = f.source_file
     AND starts_with(upper(f.path), upper(v.device_path))
    WHERE r.executable <> ''
      AND starts_with(upper(regexp_extract(f.path, '[^\\]+$')),
                      upper(r.executable))
),
best_rank AS (
    SELECT source_file, min(rank_) AS best FROM candidate GROUP BY source_file
),
summary AS (
    SELECT c.source_file, b.best,
           count(DISTINCT c.device_path) AS best_candidates
    FROM candidate c
    JOIN best_rank b ON b.source_file = c.source_file
    WHERE c.rank_ = b.best
    GROUP BY c.source_file, b.best
)
SELECT
    c.source_file,
    c.executable,
    c.device_path,
    c.volume_serial_hex,
    c.match_precision,
    c.rank_ = s.best                                         AS is_best_match,
    s.best_candidates,
    rv.device_path IS NOT NULL AND rv.device_path = c.device_path AS chosen,
    -- Stated rather than left to be worked out from the two columns above,
    -- because the reason a candidate was not chosen is the finding.
    CASE
        WHEN rv.device_path = c.device_path
            THEN 'this is the volume the record was resolved to'
        WHEN rv.device_path IS NOT NULL
            THEN 'a weaker match than the volume this record was resolved to'
        ELSE 'the record was not resolved to any volume: '
             || 'more than one volume matched equally well'
    END                                                      AS outcome
FROM candidate c
JOIN summary s ON s.source_file = c.source_file
LEFT JOIN v_prefetch_run_volume rv ON rv.source_file = c.source_file
ORDER BY c.source_file, c.rank_, c.device_path;

-- Removable volumes as the file records name them, one row per serial and
-- letter. This is the bridge prefetch needs: a prefetch file records a volume
-- serial and no drive letter, and everything downstream of a volume is keyed by
-- letter.
--
-- The equality this bridge rests on is exact — the same 32-bit number in the
-- same spelling, with no conversion — and being exact is not the same as being
-- unique. A FAT or NTFS volume serial is 32 bits, generated from the clock at
-- format time; it can be duplicated by cloning a stick, by imaging one volume
-- onto another, and by chance. So the route reports "the same volume serial was
-- recorded" and not "this is that volume", and where the case itself contains a
-- collision it says so instead of leaving a reader to notice.
--
-- serials_letters is that check, made from the case rather than assumed: the
-- number of distinct letters this one serial was recorded against by the file
-- records. More than one is either the same volume seen on two letters across
-- time — the ordinary reason — or two volumes sharing a serial, and neither can
-- be told from the other here. Either way the letter hop is not the single
-- answer it looks like, and the column is what lets the routes downstream say
-- so.
CREATE VIEW v_serial_letter AS
SELECT
    volume_serial_hex, drive_letter, volume_label,
    count(*) OVER (PARTITION BY volume_serial_hex) AS serial_letters
FROM (SELECT DISTINCT volume_serial_hex, drive_letter, volume_label
      FROM file_target
      WHERE removable AND volume_serial_hex <> '' AND drive_letter <> '');

-- From a prefetch file to a device, in one place.
--
-- The chain is: the prefetch file recorded this volume serial; a shell link
-- recorded the same serial for a removable volume on a letter; that letter
-- links to this device. The first hop is exact — it is the same number in the
-- same spelling, with no conversion and no inference — and the last hop carries
-- whatever confidence v_device_volume_link earned. Both the attribution route
-- and the device fact read this view, so the chain is decided once.
--
-- ran_from is the distinction that matters and it is not decoration. A prefetch
-- file names every volume the loader touched, so a programme on the system disk
-- that opened one file on a stick appears here beside a programme that was
-- itself executed off it. On the reference host four executables reached the
-- PATRIOT volume and one ran from it; reported without this column the report
-- said four programmes ran from the device, which is not what the evidence
-- says.
--
-- letter_contradicted is the check on the last hop. MountedDevices holds the
-- letter as it stands at collection, and that mapping can be behind the
-- evidence being explained: on USB-LENOVO-Multi-USBs the collector ran from
-- PATRIOT one minute after it was plugged in as E:, and the SYSTEM hive still
-- had E: pointing at the SanDisk unplugged three minutes earlier, because the
-- mount had not been flushed when the hive was read. Nothing was misparsed —
-- the artefact is simply a minute stale, and a minute is all it takes.
--
-- The contradiction is checkable from what is already in the row. The shell
-- link recorded the volume's own label beside its serial, and where that label
-- belongs to a different device than the letter reaches, the two disagree and
-- the letter is the one that carries a timestamp it cannot vouch for. The row
-- is kept and demoted rather than dropped or swapped: the mapping is real
-- evidence, and choosing between two disagreeing routes is the analyst's call.
CREATE VIEW v_prefetch_device_link AS
SELECT DISTINCT
    l.device_key,
    l.device_instance_id,
    v.volume_serial_hex,
    s.drive_letter,
    s.volume_label,
    l.route          AS volume_route,
    CASE WHEN n.device_key IS NOT NULL THEN 'possible'
         ELSE l.confidence END       AS volume_confidence,
    (n.device_key IS NOT NULL)       AS letter_contradicted,
    -- The serial reached more than one letter in this case, so the first hop
    -- is not the single answer an exact match reads as. Reported rather than
    -- resolved: the same volume on two letters across time and two volumes
    -- sharing a serial produce the same rows, and nothing here tells them
    -- apart.
    (s.serial_letters > 1)           AS serial_reaches_several_letters,
    coalesce(n.device_key, '')       AS label_device_key,
    (rv.source_file IS NOT NULL) AS ran_from,
    v.source_file,
    v.executable,
    v.source_id
FROM prefetch_volume v
JOIN v_serial_letter s ON s.volume_serial_hex = v.volume_serial_hex
JOIN v_device_volume_link l
  ON l.drive_letter = s.drive_letter AND l.drive_letter <> ''
LEFT JOIN v_prefetch_run_volume rv
  ON rv.source_file = v.source_file
 AND rv.volume_serial_hex = v.volume_serial_hex
-- The device the volume's own label reaches, where that is not the device the
-- letter reaches. A match here is the contradiction, so this join must stay a
-- LEFT one: the ordinary case is no row.
LEFT JOIN v_device_volume_link n
  ON n.route = 'portable_device_label'
 AND s.volume_label <> ''
 AND upper(n.volume_label) = upper(s.volume_label)
 AND n.device_key <> l.device_key
WHERE v.volume_serial_hex <> '';

-- One row per prefetch file.
--
-- run_count and times_recorded are both here and are different numbers. The
-- first is what Windows counted; the second is how many of those executions the
-- file still holds. Reporting only the first invites "it ran 400 times" with no
-- times to place them, and only the second invites "it ran twice".
CREATE VIEW v_prefetch_run AS
SELECT
    r.executable,
    r.executable_path,
    r.path_hash,
    r.format_version,
    r.run_count,
    r.times_recorded,
    x.first_run_utc,
    x.last_run_utc,
    coalesce(rv.volume_serial_hex, '') AS ran_from_serial,
    coalesce(rv.device_path, '')       AS ran_from_volume,
    r.volume_count,
    r.file_count,
    -- Whether the volume the executable ran from is one the file records
    -- independently place on a drive letter as removable media. This is the
    -- column an analyst filters prefetch-runs.csv on.
    (p.volume_serial_hex IS NOT NULL)  AS ran_from_removable,
    coalesce(p.drive_letter, '')       AS removable_letter,
    coalesce(p.volume_label, '')       AS removable_label,
    r.parse_warnings,
    r.source_id,
    r.source_file
FROM prefetch_run r
LEFT JOIN (SELECT source_file,
                  min(time_utc) AS first_run_utc,
                  max(time_utc) AS last_run_utc
           FROM prefetch_execution GROUP BY source_file) x
       ON x.source_file = r.source_file
LEFT JOIN v_prefetch_run_volume rv ON rv.source_file = r.source_file
LEFT JOIN (SELECT DISTINCT volume_serial_hex, drive_letter, volume_label
           FROM v_serial_letter) p
       ON p.volume_serial_hex = rv.volume_serial_hex
ORDER BY ran_from_removable DESC, x.last_run_utc DESC NULLS LAST, r.executable, r.executable_path, r.source_file;

CREATE VIEW v_prefetch_execution AS
SELECT x.executable, x.slot, x.time_utc,
       r.run_count, r.times_recorded,
       x.source_id, x.source_file
FROM prefetch_execution x
JOIN prefetch_run r ON r.source_file = x.source_file
ORDER BY x.time_utc DESC NULLS LAST, x.executable, x.slot, x.source_file;

-- Every volume any prefetch file named, one row each.
--
-- The great majority is the system volume, and that is not a defect to filter
-- out: the row that matters is the one an analyst can see is not it, and it can
-- only be seen against the others.
CREATE VIEW v_prefetch_volume AS
SELECT
    v.volume_serial_hex,
    v.device_path,
    v.created_utc,
    (s.volume_serial_hex IS NOT NULL) AS matches_removable_volume,
    coalesce(s.drive_letter, '')      AS drive_letter,
    coalesce(s.volume_label, '')      AS volume_label,
    count(DISTINCT v.source_file)     AS executables
FROM prefetch_volume v
LEFT JOIN v_serial_letter s ON s.volume_serial_hex = v.volume_serial_hex
GROUP BY ALL
ORDER BY matches_removable_volume DESC, executables DESC, device_path,
         volume_serial_hex, created_utc NULLS LAST;

-- Every file a prefetch record says the loader touched, resolved to the volume
-- whose device path it begins with.
--
-- The resolution is a prefix match and nothing more, which is why it is here
-- and not done at load time: the file stores a path, and the volume it belongs
-- to is a derivation like every other one in this file.
CREATE VIEW v_prefetch_file AS
SELECT
    f.executable,
    f.path,
    coalesce(v.device_path, '')       AS device_path,
    coalesce(v.volume_serial_hex, '') AS volume_serial_hex,
    f.source_id,
    f.source_file
FROM prefetch_file f
LEFT JOIN prefetch_volume v
       ON v.source_file = f.source_file
      AND starts_with(upper(f.path), upper(v.device_path));

-- The loaded files that sat on removable media.
--
-- This is a filter, not a selection: v_prefetch_file holds every path and the
-- case database is exported beside the CSVs, so narrowing here never loses the
-- wider answer. It is narrowed because a host's prefetch files name tens of
-- thousands of paths and all but a handful are the system volume's own DLLs —
-- a CSV nobody can read is not coverage.
CREATE VIEW v_prefetch_file_on_removable AS
SELECT f.executable, f.path, f.device_path, f.volume_serial_hex,
       s.drive_letter, s.volume_label,
       f.source_id, f.source_file
FROM v_prefetch_file f
JOIN v_serial_letter s ON s.volume_serial_hex = f.volume_serial_hex
ORDER BY s.drive_letter, f.executable, f.path, f.source_file;

-- Every record of a file being used, from whichever artefact recorded it, with
-- one answer to the question "what does this timestamp date?".
--
-- That question is the contract, and this view is the only place it is
-- answered. It was answered here and then answered again, differently, by
-- v_letter_activity and v_removable_volume, both of which reached past this
-- view for target_written_utc — so one shortcut appeared as a 10:10 opening in
-- timeline.csv and as an 09:38 record in letter-activity.csv, and the volume
-- summary dated a stick's first activity to a document written on another
-- machine before the stick existed in the case. The value was corrected in one
-- consumer and the others were not swept for. Every consumer now reads
-- recorded_basis instead of picking a column.
--
-- The vocabulary, weakest claim last:
--
--   instant          the time an interaction with this record happened. A jump
--                    list's DestList access, a Recent shortcut's own mtime, a
--                    UserAssist launch, a prefetch execution, an MRU key write
--                    against the entry that key write dates.
--   link_written     the shortcut file was written then — but in a directory
--                    the shell does not maintain, so that may be a user making,
--                    editing, pinning or copying it rather than opening
--                    anything. A moment on this host; not an opening.
--   not_after_bound  the record is no later than this and nothing says how much
--                    earlier. One MRU key write dates position 0 and bounds
--                    every position below it.
--   target_metadata  describes the target file, not any use of it. A .lnk
--                    header's three times are the target's own filesystem
--                    times, which can have been set on a different computer
--                    before the file was ever copied to the device.
--   none             no time is recorded.
--
-- recorded_places and recorded_bounds_only are derived from it at the foot of
-- the view so they cannot drift from it.
CREATE VIEW v_file_activity AS
WITH rows_ AS (
    SELECT
        -- The artefact names itself: shell_link or jump_list. It used to read
        -- 'file_record' with the real answer demoted to detail, which made an
        -- analyst filtering timeline.csv for shortcuts read two columns to
        -- find one fact, and made the CSVs disagree with the vocabulary the
        -- rest of the tool uses.
        origin                           AS artefact,
        -- Detail is the sub-source within the artefact, as it is for a bag's
        -- hive and depth or an MRU's list. A jump list has one: the AppID
        -- naming the application that recorded the entry, left as the hash it
        -- is because the published translation tables are incomplete and a
        -- wrong application name is worse than none. A shortcut has no
        -- sub-source — it is a file, and source_file already names it.
        CASE WHEN origin = 'jump_list' AND app_id <> ''
             THEN 'app ' || app_id ELSE '' END AS detail,
        -- A shell link records its target in up to three places and can carry
        -- any one of them alone. LinkInfo is the strongest — an absolute path
        -- the shell resolved — then the shell items, then RelativePath, which
        -- MS-SHLLINK 2.4 defines as the path to use when resolving the target.
        --
        -- Reading LinkInfo alone was losing the record entirely on a link that
        -- carried only the third: an empty path went to file-activity.csv,
        -- letter-activity.csv and the timeline, which then said a file was
        -- opened from E: without naming it, while the shortcut held the name
        -- all along. Found by a review against a synthetic link and latent on
        -- all five collections, every one of which has LinkInfo everywhere.
        --
        -- The value is taken exactly as stored and never joined onto anything
        -- to make it absolute: a relative path is relative to a directory the
        -- link does not record, so completing it would be a guess in the shape
        -- of a path. path_basis says which one this is, because "E:\x\y.docx"
        -- and "..\y.docx" are not the same kind of claim and a reader
        -- filtering on paths has to be able to tell them apart.
        --
        -- A fallback has to look like a location before it is used as one. A
        -- shell link's target items name a shell namespace, which is as often
        -- the Control Panel's folder GUID or a packaged application identity as
        -- it is a file — `{871c5380-42a0-1069-a2ea-08002b30309d}` and
        -- `Microsoft.WindowsStore_8wekyb3d8bbwe!App` are both real values on
        -- USB-LENOVO. Neither is somewhere a device could have held a file, and
        -- putting them in the path column added ten rows to that collection's
        -- file activity that an analyst can only dismiss. This is the decision
        -- prefetch already made about a packaged executable_path, kept the
        -- same way: the value is evidence, it is exported in its own column,
        -- and it is not a path.
        coalesce(nullif(path, ''),
                 CASE WHEN is_location(target_item_path)
                      THEN target_item_path END,
                 CASE WHEN is_location(relative_path)
                      THEN relative_path END)  AS path,
        CASE
            WHEN path <> ''                        THEN 'link_info'
            WHEN is_location(target_item_path)     THEN 'shell_items'
            WHEN is_location(relative_path)        THEN 'relative_path'
            ELSE 'none'
        END                              AS path_basis,
        drive_letter,
        volume_serial_hex,
        volume_label,
        removable,
        profile,
        -- The order is the order of what the times actually evidence.
        --
        -- A jump list records when its application opened the entry, which is
        -- the interaction itself. A shortcut records nothing of the kind: all
        -- three of its header times describe the *target file* as it stood
        -- when the shortcut was written. What says when the target was opened
        -- is the shortcut's own last-written time, because the shell rewrites
        -- the .lnk on each open.
        --
        -- Reading the header write time as an opening was wrong and was
        -- visible on USB-LENOVO-Multi-USBs: three files were reported opened
        -- from a stick at 01:38 UTC, twenty minutes before that stick was
        -- plugged in. They are documents authored on another machine and
        -- copied to the stick, and 01:38 is when they were last written there.
        -- The shortcuts' own mtimes are 02:10 and 02:11, inside the window the
        -- device was actually attached.
        coalesce(last_access_utc, source_modified_utc, target_written_utc)
                                         AS recorded_utc,
        -- What that time dates, in one machine-readable word. See the header
        -- of this view for the vocabulary and why each arm gets the one it
        -- does. Every consumer reads this rather than re-deriving the answer
        -- from the column that happened to win the coalesce above — which is
        -- the mistake that left letter-activity.csv telling a different story
        -- from timeline.csv about the same record.
        CASE
            WHEN last_access_utc IS NOT NULL           THEN 'instant'
            -- The shell rewrites a link in these two directories on every
            -- open, so its mtime is the most recent one.
            WHEN source_modified_utc IS NOT NULL
             AND link_context IN ('recent', 'office_recent')
                                                       THEN 'instant'
            -- Everywhere else the same mtime dates the shortcut being made,
            -- edited, pinned or copied. It is still a moment, and it is not an
            -- opening.
            WHEN source_modified_utc IS NOT NULL       THEN 'link_written'
            WHEN target_written_utc IS NOT NULL        THEN 'target_metadata'
            ELSE 'none'
        END                              AS recorded_basis,
        CASE
            WHEN last_access_utc IS NOT NULL
            THEN 'the recorded time the target was last opened'
            WHEN source_modified_utc IS NOT NULL
             AND link_context IN ('recent', 'office_recent')
            THEN 'the time the shortcut itself was last written, which in the '
                 || nullif(link_context, '')
                 || ' folder is when this target was most recently opened'
            WHEN source_modified_utc IS NOT NULL
            THEN 'the time the shortcut itself was last written. This '
                 || 'shortcut is from '
                 || coalesce(nullif(link_context, ''), 'an unrecorded location')
                 || ', where the shell does not rewrite it on each open, so '
                 || 'that time may be when it was created, edited, pinned or '
                 || 'copied rather than when the target was opened'
            WHEN target_written_utc IS NOT NULL
            THEN 'the time the target file was last written, which describes '
                 || 'the file and not any opening of it: this record carries no '
                 || 'time for when it was opened'
            -- The FAT epoch, 1980-01-01 00:00:00, is what a zeroed DOS date
            -- becomes when Windows widens it into a FILETIME. Explorer writes it
            -- into a shortcut whose target has no timestamps — a shortcut to a
            -- drive root carries it in all three header times at once. Read as a
            -- write time it puts the record in 1980 and drags the reported span
            -- of the whole case back with it, so it is reported as the absence
            -- it is, with the stored value kept in raw_target_written.
            WHEN raw_target_written = 119600064000000000
            THEN 'no time: the record stores the FAT epoch, 1980-01-01 '
                 || '00:00:00, which is what a zeroed DOS date becomes. The '
                 || 'target — usually a drive root — carried no timestamp of '
                 || 'its own'
            ELSE 'no time is recorded on this record'
        END                              AS recorded_meaning,
        -- The wall clock a shell item carried, where the record has one. It is
        -- a local time with no zone and is never merged with recorded_utc: it
        -- travels alongside so a reader can see what the artefact wrote.
        CAST(NULL AS VARCHAR)            AS recorded_local,
        source_id,
        source_file
    FROM file_target
    WHERE path <> '' OR is_location(target_item_path)
       OR is_location(relative_path) OR drive_letter <> ''

    UNION ALL

    -- The key goes in the detail and the hive in source_file, as it does for
    -- every other arm here. It was the other way round, so filtering
    -- file-activity.csv by source_file returned shortcuts by filename and bags
    -- by registry key, and a timeline row for a displayed folder cited
    -- "BagMRU\0\1" as the file it was read from.
    SELECT
        'shell_bag',
        b.hive || ' bag, depth ' || b.depth
            || coalesce(' · ' || nullif(b.registry_path, ''), ''),
        b.path,
        -- A bag, an MRU, a UserAssist entry and a prefetch record each name
        -- their location one way and only one, so there is no choice to
        -- record. The column exists because a shell link has three.
        'recorded',
        b.drive_letter,
        '', '',
        NULL,
        b.profile,
        b.key_last_write_utc,
        -- A bag has a key to itself, so its write time is this record's own
        -- moment — of the key being written. What that key write means is a
        -- separate question the event name has to answer honestly, and the
        -- meaning below is the caveat: Explorer updates a bag for view state
        -- as well as for a folder being displayed.
        'instant',
        'the time the bag key was last written, which is when Explorer last '
            || 'updated the view and not necessarily when the folder was opened',
        b.modified_local,
        b.source_id,
        coalesce(sb.path, '')
    FROM shell_bag b
    LEFT JOIN source sb ON sb.id = b.source_id
    WHERE b.path <> ''

    UNION ALL

    SELECT
        'mru',
        m.source_list || coalesce(' · ' || nullif(m.registry_path, ''), '')
            -- Say where the letter came from. Every other row's letter was
            -- decoded from a shell item or a link header; this one was read out
            -- of the caption the shell displayed, and a reader checking the row
            -- looks in a different place for it.
            || CASE WHEN m.letter_from_name
                    THEN ' · ' || m.drive_letter
                         || ': read from the name the shell displayed'
                    ELSE '' END,
        coalesce(nullif(m.path, ''), m.name),
        'recorded',
        m.drive_letter,
        -- No serial: an MRU never records one. The label is present only for a
        -- drive root, where the shell wrote it into the caption it displayed.
        '', m.volume_label,
        NULL,
        m.profile,
        m.key_last_write_utc,
        -- One key holds the whole list and carries one write time, so that time
        -- belongs to position 0 and merely bounds everything below it. Reading
        -- it as this entry's own moment is what put `PATRIOT (E:)` — an entry
        -- from a session eleven days earlier, sitting at position 21 — inside a
        -- connection window belonging to a different stick, and lifted the
        -- letter route to probable on the strength of it.
        --
        -- A position of -1 means the list recorded no order at all, which is
        -- no better placed than the rest.
        CASE WHEN m.position = 0 THEN 'instant' ELSE 'not_after_bound' END,
        CASE WHEN m.position = 0
             THEN 'the time the MRU key was last written, which dates the most '
                  || 'recent entry in the list, and this is that entry'
             ELSE 'the time the MRU key was last written, which dates the most '
                  || 'recent entry in the list and not this one: this entry is '
                  || 'at position ' || m.position || ', so it is older than '
                  || 'this and by an unrecorded amount' END,
        m.modified_local,
        m.source_id,
        coalesce(sm.path, '')
    FROM mru_entry m
    LEFT JOIN source sm ON sm.id = m.source_id
    WHERE m.path <> '' OR m.name <> ''

    UNION ALL

    -- What the shell recorded a user launching. It belongs here for the same
    -- reason prefetch does: it names something on a volume and says when it was
    -- used, so it should reach a device through the same routes rather than
    -- through a parallel set of its own. Unlike prefetch it carries a drive
    -- letter, which is the only thing that can reach a device from it.
    --
    -- The bookkeeping counters are excluded here and only here: they are the
    -- shell's own tallies rather than a launch, and a row saying UEME_CTLSESSION
    -- was opened on a device would be an invention. They stay in
    -- v_user_assist, where they can be audited.
    SELECT
        'user_assist',
        coalesce(nullif(u.category_name, ''), u.category)
            || CASE WHEN u.run_count > 0
                    THEN '; launched ' || u.run_count || ' time(s)'
                    -- A zero run count with focus is not "never run": the shell
                    -- tracked it in the foreground without recording a launch,
                    -- which is what F:\KAPE\kape.exe looks like on USB-CTF.
                    ELSE '; no launch recorded' END
            || CASE WHEN u.focus_count > 0
                    THEN '; focused ' || u.focus_count || ' time(s) for '
                         || round(u.focus_seconds, 1) || 's'
                    ELSE '' END,
        u.name,
        'recorded',
        u.drive_letter,
        -- No serial and no label: UserAssist records a path and nothing about
        -- the volume it sat on.
        '', '',
        NULL,
        u.profile,
        u.last_executed_utc,
        -- The value is this entry's own, not a shared key write.
        CASE WHEN u.last_executed_utc IS NOT NULL THEN 'instant' ELSE 'none' END,
        CASE WHEN u.last_executed_utc IS NOT NULL
             THEN 'the last time the shell recorded this being launched'
             ELSE 'no launch time is recorded on this entry' END,
        CAST(NULL AS VARCHAR),
        u.source_id,
        coalesce(su.path, '')
    FROM user_assist u
    LEFT JOIN source su ON su.id = u.source_id
    WHERE NOT u.bookkeeping AND u.name <> ''

    UNION ALL

    -- Programme executions. A prefetch file is a file record like the others —
    -- it names something on a volume and says when it was last used — and it
    -- belongs here so it flows through the same attribution routes rather than
    -- getting a parallel set of its own.
    --
    -- One row per prefetch file, carrying the most recent execution. The
    -- earlier slots are not dropped: they reach the timeline directly, which is
    -- where a second execution of the same programme is a separate event rather
    -- than a second record of one thing.
    --
    -- There is no drive letter, because prefetch does not record one. The
    -- serial is what it records, and the serial is the stronger identifier.
    SELECT
        'prefetch',
        'ran ' || r.run_count || ' time(s); '
            || r.times_recorded || ' execution(s) still recorded'
            -- For a packaged application executable_path is not a path at all
            -- but the package identity, e.g.
            -- Microsoft.WindowsStore_22401.1400.6.0_x64__8wekyb3d8bbwe. It is
            -- worth keeping and it is not a location, so it goes here and not
            -- in the path column.
            || CASE WHEN r.executable_path <> ''
                     AND NOT starts_with(r.executable_path, '\')
                    THEN '; package ' || r.executable_path ELSE '' END,
        CASE WHEN starts_with(r.executable_path, '\') THEN r.executable_path
             ELSE r.executable END,
        'recorded',
        '',
        coalesce(rv.volume_serial_hex, ''),
        '',
        NULL,
        '',
        x.last_run_utc,
        -- A prefetch file's last run is that file's own.
        CASE WHEN x.last_run_utc IS NOT NULL THEN 'instant' ELSE 'none' END,
        CASE WHEN x.last_run_utc IS NOT NULL
             THEN 'the most recent execution of this programme that Windows '
                  || 'still records; earlier ones are overwritten after eight'
             ELSE 'no execution time survives on this record' END,
        CAST(NULL AS VARCHAR),
        r.source_id,
        r.source_file
    FROM prefetch_run r
    LEFT JOIN (SELECT source_file, max(time_utc) AS last_run_utc
               FROM prefetch_execution GROUP BY source_file) x
           ON x.source_file = r.source_file
    LEFT JOIN v_prefetch_run_volume rv ON rv.source_file = r.source_file
)
-- The ordering has to be total, and it was not: artefact, path and drive letter
-- alone tie whenever one file was opened twice, and row_number over a tie is
-- free to number those rows either way round. Nothing collapses that id back to
-- the row afterwards — the attribution is consolidated into a table from one
-- evaluation of this view and the timeline joins it against another — so a
-- reshuffle between the two silently swaps two records' attributions. It stayed
-- invisible while both rows reached the same device, and surfaced the moment a
-- route could tell them apart: three jump list entries for one PDF on E:, two
-- from when a SanDisk held the letter and one from when PATRIOT did, and the
-- timeline printed each against the other's device.
--
-- Every column of the view is in the key. Two rows still tied after that are
-- identical in everything this view exposes, so which of them takes which id
-- cannot be observed.
SELECT row_number() OVER (
           ORDER BY artefact, path, drive_letter, recorded_utc,
                    volume_serial_hex, volume_label, removable, profile,
                    detail, recorded_meaning, recorded_basis, recorded_local,
                    source_file, source_id)
           AS activity_id,
       -- Both booleans are derived from the basis here, in one place, rather
       -- than written out per arm. Two columns that must agree and are stated
       -- separately are two columns that will one day disagree, which is the
       -- whole shape of the defect this view is being rebuilt to close.
       --
       -- recorded_places is the gate every window-placement route reads. A
       -- bound does not place: it says the record is no later than this. And
       -- target metadata does not place either, for a stronger reason — a
       -- target's write time can have been set on another computer before the
       -- file was ever copied to the device, so matching it against this
       -- host's connection windows corroborates nothing at all.
       recorded_basis IN ('instant', 'link_written') AS recorded_places,
       recorded_basis = 'not_after_bound'            AS recorded_bounds_only,
       *
FROM rows_;

-- Every record of a file or folder on a drive letter, from whichever artefact
-- named it. An analyst asking "what was on E:" should not have to know which
-- of four keys and two file formats to look in.
--
-- Read from v_file_activity and not rebuilt from the tables. It was rebuilt,
-- and that is how it came to export target_written_utc as the record's time
-- long after the timeline had stopped doing so: the same shortcut read as an
-- opening at 10:10 in one CSV and as 09:38 in this one, with nothing in either
-- file to tell an analyst which they were looking at. A derived view that
-- reaches past the view it derives from is a second implementation of the same
-- judgement, and the two will diverge on the first correction to either.
--
-- Two consequences of reading the canonical view, both wanted. UserAssist
-- launches that name a letter now appear here — `F:\KAPE\gkape.exe` is exactly
-- what somebody asking "what was on F:" wants and it was missing. And every
-- row carries the basis and the meaning of its time, so a target write-time
-- record is legible as one rather than looking like an interaction.
CREATE VIEW v_letter_activity AS
SELECT drive_letter, artefact, detail, path, path_basis, profile,
       recorded_utc, recorded_local, recorded_basis, recorded_meaning
FROM v_file_activity
WHERE drive_letter <> ''
ORDER BY drive_letter, artefact, path, recorded_utc NULLS LAST,
         recorded_local, profile, detail;

-- File records grouped by the volume that recorded them.
--
-- Grouped by volume serial and not by drive letter. Two volumes sharing a
-- letter is the ordinary case: the reference evidence has E: used by both a
-- PATRIOT and a TEST volume, and grouping by letter would attribute one
-- device's files to the other.
--
-- The range columns are named for what they hold, which they were not. They
-- were `first_activity_utc` and `last_activity_utc`, computed from
-- coalesce(last_access_utc, target_written_utc) — so on five of the six
-- reference volumes the "activity" began at a target file's write time. On
-- GEN32GBF32 that read 01:38:34, a document written on another machine before
-- the stick was ever plugged into this host, while the first thing anyone
-- actually did with that volume was at 02:10:31. A volume summary is the first
-- place an analyst looks to date a device's use, and it was answering with a
-- number from somebody else's computer.
--
-- So the range is built only from rows whose time is an instant of use, and
-- what cannot be dated is counted rather than filled in. A volume with eight
-- records and two datable ones is a volume an analyst needs to know that about;
-- reaching for the nearest available number to avoid an empty cell is how the
-- wrong one got there.
--
-- The target write times are not aggregated here at all. Renaming the columns
-- was the obvious repair and it would have kept a statistic worth nothing: the
-- oldest and newest write times of the files on a stick are facts about when
-- somebody authored documents, quite possibly on other computers over several
-- years, and min/max across a volume answers no question anyone asks. They
-- stay per file in file-targets.csv, attached to the file they describe, which
-- is the only place they mean anything.
CREATE VIEW v_removable_volume AS
SELECT
    volume_serial_hex,
    volume_label,
    drive_letter,
    count(*)                AS target_count,
    count(DISTINCT path)    AS distinct_paths,
    count(DISTINCT profile) AS profiles,
    min(recorded_utc) FILTER (WHERE recorded_basis = 'instant')
                            AS first_interaction_utc,
    max(recorded_utc) FILTER (WHERE recorded_basis = 'instant')
                            AS last_interaction_utc,
    -- Records on this volume that carry no time for anybody having used them,
    -- so the range above does not cover them. Shown rather than hidden: a zero
    -- count is a finding and an absent one reads as not looked at.
    count(*) FILTER (WHERE recorded_basis <> 'instant')
                            AS undated_records
FROM v_file_activity
WHERE removable
GROUP BY volume_serial_hex, volume_label, drive_letter
ORDER BY drive_letter, volume_serial_hex, volume_label;

-- Storage that came and went, as against the machine's own disks.
--
-- Read from the consolidated facts rather than recomputed, and it is safe to:
-- Consolidate writes device_fact before file_attribution, so by the time the
-- attribution runs these rows are there.
--
-- The discriminator is the USB attachment itself, stated affirmatively. It was
-- the absence of internal_bus, which is the same set of devices today and the
-- wrong question to ask: a device is eligible to be placed on by a connection
-- window because something recorded it arriving over USB, not because nothing
-- recorded it being a disk. An identity whose bus this collection never reached
-- has no arrival either way, so it is excluded here as it always was.
--
-- The table and not v_device_fact, which is declared further down this file
-- than the attribution that needs this. Same rows either way.
CREATE VIEW v_removable_device AS
SELECT DISTINCT g.device_key, g.physical_device_id
FROM v_device_group g
JOIN device_fact s
  ON s.physical_device_id = g.physical_device_id
 AND s.fact = 'storage_identity'
WHERE EXISTS (
    SELECT 1 FROM device_fact u
    WHERE u.physical_device_id = g.physical_device_id
      AND u.fact = 'usb_attached');

-- The drive letters that named removable media, from either direction.
--
-- A shell link says so outright — it carries the drive type beside the path —
-- but a shell bag and an MRU carry a letter and nothing else, so for those the
-- only evidence that E: was a stick is that the mount table maps E: to a device
-- that is removable storage. That mapping is stale often enough that it must
-- never be trusted to name *which* device; it is trustworthy for the much
-- weaker claim being made here, which is that the letter belongs to removable
-- media at all. Letters the host's own disks hold cannot appear: their devices
-- reach no USB attachment and are excluded above.
CREATE VIEW v_removable_letter AS
SELECT DISTINCT drive_letter
FROM file_target
WHERE removable AND drive_letter <> ''
UNION
SELECT DISTINCT l.drive_letter
FROM v_device_volume_link l
JOIN v_removable_device d ON d.device_key = l.device_key
WHERE l.drive_letter <> '';

-- The removable device that was the only one attached when a record was made.
--
-- MountedDevices answers "what does E: map to now", and a letter is freed the
-- moment its volume goes and handed to the next arrival, so on a host where
-- three sticks held E: in turn the mount table names one of them and the other
-- two records are attributed to a device that was not there. Demoting that
-- mapping where no window places the device — which v_connection_placing does —
-- removes the false confidence without supplying the answer. This route
-- supplies it, from the other side: if the evidence shows exactly one removable
-- device attached at that moment, the record was on that one whatever the
-- letter says today.
--
-- It abstains where two devices were connected at once, which is the case the
-- letter is actually needed for, and it is capped at probable in the route
-- below: a second device could have been attached with nothing recording it,
-- and unlike the other routes there is no independent link to the device here —
-- the window is the whole of the evidence.
--
-- The record also has to be within a day of the arrival, and that bound is not
-- decoration. A window is an arrival and the next removal recorded for the same
-- device, which is not the same as the device having stayed in the port: a
-- channel that stopped recording leaves exactly that shape. Three of the five
-- reference collections carry one window of 262 days, and reading it as
-- continuous attachment attributed two file records from July 2026 to a stick
-- that arrived in November 2025 — while the same file, a minute later, was
-- attributed by its own label to the device that had just arrived. No laptop
-- keeps a stick through 262 days and every reboot in them with no second
-- arrival logged; the absence of records in the middle is the logging failing,
-- not the device staying.
--
-- The bound is on the distance from the arrival rather than on the length of
-- the window, because that is where the doubt lies. An arrival is a recorded
-- fact, and an hour after one is the strongest this route ever gets however
-- badly the far end of the window is evidenced. Every genuine window across the
-- five collections closes within eleven minutes, so a day leaves three orders
-- of magnitude of headroom and still sits five below the case it excludes.
CREATE VIEW v_sole_connected_device AS
SELECT
    a.activity_id,
    min(c.device_key)            AS device_key,
    min(c.device_instance_id)    AS device_instance_id,
    min(c.started_utc)           AS started_utc,
    count(DISTINCT c.device_key) AS connected_devices
FROM v_file_activity a
JOIN v_connection_placing c
  ON a.recorded_utc >= c.started_utc
 AND (c.places_until_utc IS NULL OR a.recorded_utc <= c.places_until_utc)
 AND a.recorded_utc <= c.started_utc + INTERVAL 24 HOUR
JOIN v_removable_device d ON d.device_key = c.device_key
WHERE a.recorded_utc IS NOT NULL
    -- The time has to place the record before a window can be asked to cover
    -- it. This route has no independent link to the device at all — the window
    -- is the whole of the evidence — so it is the one that must not be given a
    -- moment the record does not have.
    --
    -- Two bases fail that. A bound says the record is no later than this and
    -- nothing more. And a target's write time is not a moment on this host at
    -- all: the file may have been written on another computer and copied
    -- across, so asking which stick was attached when some other machine saved
    -- it is not a question about this case.
  AND a.recorded_places
    -- The record has to be on removable media before "which stick" is even the
    -- right question. Three ways of knowing, one per artefact shape: a shell
    -- link states the drive type, a bag or an MRU has only its letter, and
    -- prefetch has only the volume serial and never a letter at all.
  AND (a.removable
       OR (a.drive_letter <> ''
           AND a.drive_letter IN (SELECT drive_letter FROM v_removable_letter))
       OR (a.volume_serial_hex <> ''
           AND a.volume_serial_hex IN
               (SELECT volume_serial_hex FROM v_serial_letter)))
GROUP BY a.activity_id
HAVING count(DISTINCT c.device_key) = 1;

-- The device a record's own volume label names, where it names exactly one.
--
-- Kept apart from the label route below because the contradiction check needs
-- the answer to be single-valued before "the label says X" is a statement at
-- all. Where two devices on a host carry the same label there is no X.
CREATE VIEW v_activity_label_device AS
SELECT
    a.activity_id,
    min(l.device_key)            AS device_key,
    count(DISTINCT l.device_key) AS devices
FROM v_file_activity a
JOIN v_device_volume_link l
  ON l.route = 'portable_device_label'
 AND upper(l.volume_label) = upper(a.volume_label)
WHERE a.volume_label <> ''
GROUP BY a.activity_id;

-- Records whose drive letter names a different device than their own label.
--
-- MountedDevices holds the mapping as it stood when the hive was read and is
-- dated by nothing; a record carrying a label carries what the volume called
-- itself at the moment the record was made. Where the two disagree the record's
-- own testimony is the better evidence, and the letter is reading a table that
-- has moved on.
--
-- This is the check that already exists for prefetch as
-- v_prefetch_device_link.letter_contradicted, generalised to any record that
-- carries both — a shell link states a label beside its letter, and so, since
-- the drive-root captions were read, does a RecentDocs entry. The prefetch arm
-- keeps its own version because it reaches the letter through a volume serial
-- rather than directly, and the shape of that chain is different.
--
-- The contradiction is that no letter link reaches the device the label names.
-- Not "the first letter link disagrees": a letter can map to several devices
-- across control sets and routes, and if any of them is the label's device the
-- two are not in conflict.
CREATE VIEW v_letter_contradicted AS
SELECT d.activity_id, d.device_key AS label_device_key
FROM v_activity_label_device d
JOIN v_file_activity a ON a.activity_id = d.activity_id
WHERE d.devices = 1
  AND a.drive_letter <> ''
  AND EXISTS (SELECT 1 FROM v_device_volume_link l
               WHERE l.drive_letter = a.drive_letter)
  AND NOT EXISTS (SELECT 1 FROM v_device_volume_link l
                   WHERE l.drive_letter = a.drive_letter
                     AND l.device_key = d.device_key);

-- Which device a file record sat on, one row per route that reaches an answer.
--
-- The routes are tried in the order the plan sets out and each keeps the
-- confidence it earns. A record reached by two routes gets two rows, because
-- two independent routes agreeing is a stronger finding than either alone and
-- two disagreeing is a finding in itself.
--
-- Nothing here is collapsed into a single answer per file. Choosing one and
-- discarding the rest is a judgement, and it belongs to the analyst reading
-- the evidence rather than to the query that assembled it.
CREATE VIEW v_file_attribution_computed AS

-- The volume serial. EMDMgmt is the only artefact that records a serial
-- against a device, and it holds both in one key name, so no inference sits
-- between them. It is absent on any current Windows, which is why the routes
-- below exist at all.
SELECT
    a.activity_id, a.artefact, a.path, a.drive_letter,
    a.volume_serial_hex, a.volume_label, a.profile, a.recorded_utc,
    e.device_key, e.device_instance_id,
    'volume_serial_emdmgmt' AS route,
    'confirmed'             AS confidence,
    'EMDMgmt records this volume serial against this device in one key name'
                            AS detail,
    -- A serial names the device outright; there is no letter to contradict.
    FALSE,
    a.source_id
FROM v_file_activity a
JOIN emd_volume e
  ON e.device_key <> ''
 AND e.volume_serial_decimal <> ''
   -- EMDMgmt stores the serial in decimal; a shell link renders the same
   -- value as two hex groups. They are the same number in two spellings.
 AND upper(replace(a.volume_serial_hex, '-', ''))
     = lpad(hex(CAST(e.volume_serial_decimal AS BIGINT)), 8, '0')
WHERE a.volume_serial_hex <> ''

UNION ALL

-- The volume label, matched against the Portable Devices list where the label
-- is unique on the host. A label is set by whoever formatted the volume and can
-- be reused, so this is possible on its own — and probable where a connection
-- window independently places the device on the machine when the file record
-- was made.
SELECT
    a.activity_id, a.artefact, a.path, a.drive_letter,
    a.volume_serial_hex, a.volume_label, a.profile, a.recorded_utc,
    l.device_key, l.device_instance_id,
    'volume_label_unique',
    CASE WHEN a.recorded_places AND EXISTS (
        SELECT 1 FROM v_connection_placing c
        WHERE c.device_key = l.device_key
          AND a.recorded_utc IS NOT NULL
          AND c.started_utc IS NOT NULL AND a.recorded_utc >= c.started_utc
          AND (c.places_until_utc IS NULL OR a.recorded_utc <= c.places_until_utc)
    ) THEN 'probable' ELSE 'possible' END,
    CASE WHEN a.recorded_basis = 'not_after_bound'
         THEN 'the label is unique to this device on this host; the record '
            || 'carries no moment of its own to check a connection window '
            || 'against, only a time it must be older than'
         WHEN a.recorded_basis = 'target_metadata'
         THEN 'the label is unique to this device on this host; the only time '
            || 'this record carries is its target file''s own write time, '
            || 'which may have been set on another computer before the file '
            || 'was copied here, so no connection window on this host is '
            || 'checked against it'
         WHEN EXISTS (
        SELECT 1 FROM v_connection_placing c
        WHERE c.device_key = l.device_key
          AND a.recorded_utc IS NOT NULL
          AND c.started_utc IS NOT NULL AND a.recorded_utc >= c.started_utc
          AND (c.places_until_utc IS NULL OR a.recorded_utc <= c.places_until_utc)
    ) THEN 'the label is unique to this device and a connection window '
         || 'independently places it on the machine at this time'
      ELSE 'the label is unique to this device on this host; nothing places '
         || 'the device on the machine at this time' END,
    -- This route *is* the label, so it cannot disagree with itself.
    FALSE,
    a.source_id
FROM v_file_activity a
JOIN v_device_volume_link l
  ON l.route = 'portable_device_label'
 AND upper(l.volume_label) = upper(a.volume_label)
WHERE a.volume_label <> ''

UNION ALL

-- The drive letter. This route is capped at probable however strong the
-- letter-to-device link is, because MountedDevices is not time-bound: it holds
-- the mapping as it stands now and says nothing about which volume held the
-- letter when the file was opened. A connection window covering the record is
-- what lifts it from a current mapping to a placement in time.
SELECT
    a.activity_id, a.artefact, a.path, a.drive_letter,
    a.volume_serial_hex, a.volume_label, a.profile, a.recorded_utc,
    l.device_key, l.device_instance_id,
    'drive_letter_' || l.route,
    -- A contradicted letter is capped however well the mapping matched. The
    -- record's own label names a device this letter does not reach, and a
    -- connection window covering the record cannot rescue a mapping that names
    -- the wrong device — it would only place a device the record never sat on.
    CASE WHEN x.activity_id IS NOT NULL THEN 'possible'
         WHEN a.recorded_places AND EXISTS (
        SELECT 1 FROM v_connection_placing c
        WHERE c.device_key = l.device_key
          AND a.recorded_utc IS NOT NULL
          AND c.started_utc IS NOT NULL AND a.recorded_utc >= c.started_utc
          AND (c.places_until_utc IS NULL OR a.recorded_utc <= c.places_until_utc)
    ) THEN 'probable' ELSE 'possible' END,
    CASE WHEN x.activity_id IS NOT NULL
         THEN 'the letter maps to this device now, and the record''s own '
            || 'volume label names a different device: the mount table holds '
            || 'the mapping as it stood when the hive was read and is dated by '
            || 'nothing, while the label is what the volume called itself when '
            || 'the record was made. The row is kept and capped rather than '
            || 'dropped, because the mapping is real evidence'
         WHEN a.recorded_basis = 'not_after_bound'
         THEN 'the letter maps to this device now; the record carries no '
            || 'moment of its own to check a connection window against, only '
            || 'a time it must be older than'
         WHEN a.recorded_basis = 'target_metadata'
         THEN 'the letter maps to this device now; the only time this record '
            || 'carries is its target file''s own write time, which describes '
            || 'the file rather than any use of it and may predate the volume '
            || 'reaching this host, so no connection window is checked '
            || 'against it'
         WHEN EXISTS (
        SELECT 1 FROM v_connection_placing c
        WHERE c.device_key = l.device_key
          AND a.recorded_utc IS NOT NULL
          AND c.started_utc IS NOT NULL AND a.recorded_utc >= c.started_utc
          AND (c.places_until_utc IS NULL OR a.recorded_utc <= c.places_until_utc)
    ) THEN 'the letter maps to this device and a connection window covers '
         || 'the time of this record'
      ELSE 'the letter maps to this device now; nothing places the device on '
         || 'the machine when this record was made' END,
    (x.activity_id IS NOT NULL),
    a.source_id
FROM v_file_activity a
JOIN v_device_volume_link l
  ON l.drive_letter = a.drive_letter AND l.drive_letter <> ''
LEFT JOIN v_letter_contradicted x ON x.activity_id = a.activity_id
WHERE a.drive_letter <> ''

UNION ALL

-- The volume serial a prefetch file recorded.
--
-- Prefetch is the only artefact here that names a volume by serial and never by
-- letter, so none of the routes above can reach it. The serial itself is an
-- exact match — the same number in the same spelling a shell link records, with
-- no conversion between them — but the device is still two hops away: the
-- serial identifies the volume, and the volume reaches the device through the
-- letter it was mounted on. That last hop is what caps this at strong.
SELECT
    a.activity_id, a.artefact, a.path, a.drive_letter,
    a.volume_serial_hex, a.volume_label, a.profile, a.recorded_utc,
    p.device_key, p.device_instance_id,
    'volume_serial_prefetch',
    -- A contradicted letter caps this at possible however well the serial
    -- matched. The first hop is still exact; it is the hop to the device that
    -- the volume's own label says is wrong, and a connection window covering
    -- the execution cannot rescue a mapping that names the wrong device.
    CASE WHEN p.letter_contradicted THEN 'possible'
         WHEN EXISTS (
        SELECT 1 FROM v_connection_placing c
        WHERE c.device_key = p.device_key
          AND a.recorded_utc IS NOT NULL
          AND c.started_utc IS NOT NULL AND a.recorded_utc >= c.started_utc
          AND (c.places_until_utc IS NULL OR a.recorded_utc <= c.places_until_utc)
    ) THEN 'strong' ELSE 'probable' END,
    'the prefetch file records this volume serial, a shell link records the '
        || 'same serial for a removable volume on ' || p.drive_letter
        || ', and that letter links to this device ('
        || p.volume_route || ')'
        || CASE WHEN p.letter_contradicted
                THEN '. That last hop is contradicted: the shell link labels '
                  || 'this volume ' || p.volume_label || ', which the portable '
                  || 'device list gives to a different device, so the letter '
                  || 'mapping is out of date and names the wrong one'
                ELSE '' END
        || CASE WHEN EXISTS (
               SELECT 1 FROM v_connection_placing c
               WHERE c.device_key = p.device_key
                 AND a.recorded_utc IS NOT NULL
                 AND c.started_utc IS NOT NULL AND a.recorded_utc >= c.started_utc
                 AND (c.places_until_utc IS NULL OR a.recorded_utc <= c.places_until_utc)
           ) THEN '; a connection window covers the execution'
             ELSE '; nothing places the device on the machine at that time' END
        -- A volume serial is 32 bits and the equality being exact does not make
        -- it unique. Where this case itself recorded the serial against more
        -- than one letter the first hop has more than one answer, which is
        -- worth saying on the row rather than leaving to be noticed.
        || CASE WHEN p.serial_reaches_several_letters
                THEN '. This serial was recorded against more than one drive '
                  || 'letter in this case, so the match to a volume is not '
                  || 'the single answer an exact serial reads as'
                ELSE '' END,
    -- Prefetch reaches the letter through a volume serial, so it computes
    -- its own contradiction one step further along the chain.
    p.letter_contradicted,
    a.source_id
FROM v_file_activity a
JOIN v_prefetch_device_link p ON p.source_file = a.source_file
WHERE a.artefact = 'prefetch' AND a.volume_serial_hex <> ''
  AND p.volume_serial_hex = a.volume_serial_hex

UNION ALL

-- The only removable device attached at the time.
--
-- Every route above reaches the device through something the record itself
-- carries — a serial, a label, a letter — and asks the connection windows only
-- whether that answer is placeable. This one has no such link and reads the
-- windows alone, which is why it exists: a shell bag carries a letter and
-- nothing else, and a letter is reused within one uptime, so where three sticks
-- held E: in turn the letter route names the same device for all three and is
-- wrong about two of them. Asking who was there instead answers all three.
--
-- Capped at probable and never lifted. The window is the whole of the evidence,
-- and a device attached with nothing recording it would make this the wrong
-- answer with no contradiction anywhere in the collection to catch it. The
-- detail names the arrival and how long before the record it was, because that
-- gap is what the reader has to weigh: a minute is close to conclusive and
-- twenty hours is a day in which anything could have been plugged in unlogged.
SELECT
    a.activity_id, a.artefact, a.path, a.drive_letter,
    a.volume_serial_hex, a.volume_label, a.profile, a.recorded_utc,
    s.device_key, s.device_instance_id,
    'sole_connected_device',
    'probable',
    'this record is on removable media and exactly one removable device was '
        || 'connected when it was made: this one, which arrived at '
        || strftime(s.started_utc, '%Y-%m-%d %H:%M:%S') || ' UTC, '
        || date_diff('second', s.started_utc, a.recorded_utc)
        || ' seconds before the record. No drive letter or label was needed to '
        || 'reach it, and none was used',
    -- No letter and no label were used to reach the device, so neither can
    -- be contradicted.
    FALSE,
    a.source_id
FROM v_file_activity a
JOIN v_sole_connected_device s ON s.activity_id = a.activity_id;

-- What everything downstream reads. Filled by the consolidation step, for the
-- reason schema.sql gives beside the table: five readers want this answer and
-- each route asks, per record, whether a connection window covers it.
CREATE VIEW v_file_attribution AS
SELECT * FROM file_attribution
ORDER BY activity_id, route, device_key, source_id;

-- Where the routes disagree, and where a file record reaches no device at all.
--
-- Both are findings. A record with two candidate devices is a question the
-- evidence has not settled, and one with none is a gap that should be visible
-- rather than absent from the output.
CREATE VIEW v_file_attribution_summary AS
SELECT
    a.activity_id,
    a.artefact,
    a.path,
    a.drive_letter,
    a.volume_serial_hex,
    a.volume_label,
    a.recorded_utc,
    count(DISTINCT f.device_key)                       AS candidate_devices,
    count(f.route)                                     AS routes,
    -- Ranked explicitly. Sorting the words themselves puts "probable" above
    -- "strong", which is alphabetical and wrong.
    coalesce(list_extract(
        ['confirmed', 'strong', 'probable', 'possible'],
        min(CASE f.confidence WHEN 'confirmed' THEN 1 WHEN 'strong' THEN 2
                              WHEN 'probable'  THEN 3 ELSE 4 END)),
        'unattributed')                                AS best_confidence,
    string_agg(DISTINCT f.device_instance_id, '; '
               ORDER BY f.device_instance_id)          AS devices,
    string_agg(DISTINCT f.route, '; '
               ORDER BY f.route)                       AS routes_used
FROM v_file_activity a
LEFT JOIN v_file_attribution f USING (activity_id)
GROUP BY ALL
-- activity_id last, because the three columns before it tie whenever one file
-- was opened twice — a shell link and a jump list for the same path — and rows
-- that tie come back in whatever order the group by produced them. The id is
-- unique per row, so it makes the ordering total and the file byte-identical
-- between runs.
ORDER BY candidate_devices DESC, a.drive_letter, a.path, a.activity_id;

CREATE VIEW v_file_target AS
SELECT
    f.drive_letter,
    f.volume_serial_hex,
    f.volume_label,
    f.removable,
    f.drive_type,
    f.volume_present,
    f.path,
    f.origin,
    f.app_id,
    f.profile,
    f.target_written_utc,
    f.target_accessed_utc,
    f.target_created_utc,
    f.target_size_bytes,
    f.last_access_utc,
    -- The shortcut file's own last-written time, and the folder it was found
    -- in. Both were carried and neither was exported, so the value a
    -- `file_opened` row rests on — and the context that decides whether it is
    -- an opening at all — could not be checked from any output. A conclusion
    -- an analyst cannot audit is one they have to take on trust.
    f.source_modified_utc,
    f.link_context,
    f.access_count,
    f.destlist_ranking_value,
    f.mru_position,
    f.destlist_present,
    f.pinned,
    f.machine_id,
    f.target_item_path,
    -- The link's own StringData, beside the two paths it can be checked
    -- against. relative_path is here because a link can carry it alone, and a
    -- reader who sees a row whose path_basis is relative_path needs the raw
    -- value in the same file to see what the shortcut actually stored.
    f.relative_path,
    f.working_dir,
    f.arguments,
    f.icon_location,
    f.target_item_modified_local,
    f.mft_entry,
    f.mft_sequence,
    f.raw_target_written,
    f.raw_last_access,
    f.stream_name,
    f.parse_warnings,
    f.source_id,
    s.path   AS source_path,
    s.sha256 AS source_sha256
FROM file_target f
LEFT JOIN source s ON s.id = f.source_id
ORDER BY f.drive_letter, f.path, f.origin, f.source_file, f.target_written_utc NULLS LAST,
         f.last_access_utc NULLS LAST;

-- ---- classification --------------------------------------------------------
--
-- Rules match on facts, and a fact is something derived from the evidence that
-- can be pointed at. Every fact below carries the value that produced it, so a
-- category can be followed back to a compatible id, a class GUID or a service
-- name rather than being asserted.
--
-- The USB base class is the backbone rather than the setup class, because a
-- physical device appears under several enumerators and classes, and the class
-- Windows filed it under is a statement about the driver rather than about what
-- the device can do.

-- USB\Class_08&SubClass_06 matches; USB\COMPAT_VID_0781&Class_08 deliberately
-- does not — that form states the vendor's own compatible id, and matching it
-- would count the same interface twice.
CREATE MACRO has_usb_class(compatible_ids, code) AS
    contains(upper(compatible_ids), 'USB\CLASS_' || upper(code));

CREATE MACRO has_text(haystack, needle) AS
    contains(upper(coalesce(haystack, '')), upper(needle));

-- The attributes of every identity in a device, which is what makes a dock
-- inferable from its child functions rather than from a class of its own.
CREATE VIEW v_device_attribute AS
SELECT
    g.physical_device_id,
    d.device_key,
    upper(d.enumerator)                   AS enumerator,
    upper(d.device_id)                    AS device_id,
    upper(coalesce(d.compatible_ids, '')) AS compatible_ids,
    lower(coalesce(d.class_guid, ''))     AS class_guid,
    lower(coalesce(d.service, ''))        AS service,
    upper(coalesce(d.hardware_id, ''))    AS hardware_id,
    coalesce(d.device_desc, '')           AS device_desc,
    coalesce(d.bus_reported_desc, '')     AS bus_reported_desc
FROM v_devnode d
JOIN v_device_group g USING (device_key)
WHERE d.device_key <> '';

-- Every fact with the value that produced it. One fact can be reached several
-- ways and all of them are kept: a storage device recognised by its enumerator
-- and by its USB base class is better evidenced than one recognised by either.
CREATE VIEW v_device_fact_evidence AS
SELECT physical_device_id, 'storage_identity' AS fact,
       'enumerator ' || enumerator || ' on ' || device_key AS evidence
FROM v_device_attribute WHERE enumerator IN ('USBSTOR', 'SCSI')
UNION ALL
-- Also from the inventory rather than the devnodes alone: a device known only
-- from event records has no devnode, and a storage device that classified as
-- unknown because its registry key was not collected would be the worst kind
-- of miss.
SELECT g.physical_device_id, 'storage_identity',
       'enumerator ' || upper(d.enumerator) || ' on ' || d.device_key
FROM v_device d JOIN v_device_group g USING (device_key)
WHERE upper(d.enumerator) IN ('USBSTOR', 'SCSI')
UNION ALL
SELECT physical_device_id, 'storage_identity',
       'USB base class 08 (mass storage) in the compatible ids of ' || device_key
FROM v_device_attribute WHERE has_usb_class(compatible_ids, '08')
UNION ALL
SELECT physical_device_id, 'storage_identity', 'service ' || service
FROM v_device_attribute WHERE service IN ('usbstor', 'disk')

UNION ALL
SELECT physical_device_id, 'optical_identity', 'CDROM setup class on ' || device_key
FROM v_device_attribute WHERE class_guid = '{4d36e965-e325-11ce-bfc1-08002be10318}'
UNION ALL
SELECT physical_device_id, 'optical_identity', 'compatible id names a CD-ROM'
FROM v_device_attribute WHERE has_text(compatible_ids, 'CDROM')

-- WPDBUSENUM alone is not MTP: the reference evidence enumerates ordinary USB
-- sticks under it, and reading that as a phone would report a memory stick as
-- a mobile device.
UNION ALL
SELECT physical_device_id, 'mtp_interface', 'MTP compatible id on ' || device_key
FROM v_device_attribute WHERE has_text(compatible_ids, 'MS_COMP_MTP')
UNION ALL
-- WUDFWpdFs is deliberately absent: Windows attaches the portable-device file
-- system driver to ordinary mass storage volumes, so reading it as MTP made
-- every memory stick in the reference evidence claim a second interface.
SELECT physical_device_id, 'mtp_interface', 'service ' || service
FROM v_device_attribute WHERE service IN ('wudfwpdmtp', 'wpdusb')
UNION ALL
SELECT physical_device_id, 'apple_mobile_service', 'service ' || service
FROM v_device_attribute WHERE service IN ('usbaapl', 'usbaapl64', 'applemobiledevice')

UNION ALL
SELECT physical_device_id, 'network_interface', 'Net setup class on ' || device_key
FROM v_device_attribute WHERE class_guid = '{4d36e972-e325-11ce-bfc1-08002be10318}'
UNION ALL
SELECT physical_device_id, 'network_interface',
       'network compatible id on ' || device_key
FROM v_device_attribute
WHERE has_text(compatible_ids, 'MS_COMP_RNDIS')
   OR has_text(compatible_ids, 'MS_COMP_MBIM')
   OR has_text(compatible_ids, 'MS_COMP_NCM')
   OR (has_usb_class(compatible_ids, '02') AND has_text(compatible_ids, 'SUBCLASS_06'))

UNION ALL
SELECT physical_device_id, 'serial_interface', 'Ports setup class on ' || device_key
FROM v_device_attribute WHERE class_guid = '{4d36e978-e325-11ce-bfc1-08002be10318}'
UNION ALL
SELECT physical_device_id, 'serial_interface', 'service ' || service
FROM v_device_attribute WHERE service IN ('usbser', 'ftdibus', 'silabser')
UNION ALL
SELECT physical_device_id, 'serial_interface',
       'USB communications class with the abstract control subclass'
FROM v_device_attribute
WHERE has_usb_class(compatible_ids, '02') AND has_text(compatible_ids, 'SUBCLASS_02')

UNION ALL
SELECT physical_device_id, 'hid_interface', 'USB base class 03 (HID) on ' || device_key
FROM v_device_attribute WHERE has_usb_class(compatible_ids, '03')
UNION ALL
SELECT physical_device_id, 'hid_interface', 'setup class ' || class_guid
FROM v_device_attribute WHERE class_guid IN (
    '{745a17a0-74d3-11d0-b6fe-00a0c90f57da}',
    '{4d36e96b-e325-11ce-bfc1-08002be10318}',
    '{4d36e96f-e325-11ce-bfc1-08002be10318}')

UNION ALL
SELECT physical_device_id, 'printer_interface', 'USB base class 07 (printer)'
FROM v_device_attribute WHERE has_usb_class(compatible_ids, '07')
UNION ALL
SELECT physical_device_id, 'printer_interface', 'setup class ' || class_guid
FROM v_device_attribute WHERE class_guid IN (
    '{4d36e979-e325-11ce-bfc1-08002be10318}',
    '{1ed2bbf9-11f0-4084-b21f-ad83a8e6dcdc}')
UNION ALL
SELECT physical_device_id, 'imaging_interface', 'USB base class 06 (still image)'
FROM v_device_attribute WHERE has_usb_class(compatible_ids, '06')
UNION ALL
SELECT physical_device_id, 'imaging_interface', 'Image setup class on ' || device_key
FROM v_device_attribute WHERE class_guid = '{6bdd1fc6-810f-11d0-bec7-08002be2092f}'

UNION ALL
SELECT physical_device_id, 'audio_interface', 'USB base class 01 (audio)'
FROM v_device_attribute WHERE has_usb_class(compatible_ids, '01')
UNION ALL
SELECT physical_device_id, 'video_interface', 'USB base class 0E (video)'
FROM v_device_attribute WHERE has_usb_class(compatible_ids, '0e')
UNION ALL
SELECT physical_device_id, 'video_interface', 'service ' || service
FROM v_device_attribute WHERE service = 'usbvideo'

UNION ALL
SELECT physical_device_id, 'smartcard_interface', 'USB base class 0B (smart card)'
FROM v_device_attribute WHERE has_usb_class(compatible_ids, '0b')
UNION ALL
SELECT physical_device_id, 'smartcard_interface', 'SmartCardReader setup class'
FROM v_device_attribute WHERE class_guid = '{50dd5230-ba8a-11d1-bf5d-0000f805f530}'
UNION ALL
SELECT physical_device_id, 'biometric_interface', 'Biometric setup class on ' || device_key
FROM v_device_attribute WHERE class_guid = '{53d29ef7-377c-4d14-864b-eb3a85769359}'

UNION ALL
SELECT physical_device_id, 'hub_interface', 'USB base class 09 (hub)'
FROM v_device_attribute WHERE has_usb_class(compatible_ids, '09')
UNION ALL
SELECT physical_device_id, 'hub_interface', 'service ' || service
FROM v_device_attribute WHERE service LIKE 'usbhub%'
UNION ALL
SELECT physical_device_id, 'internal_hub', 'the device id is ' || device_id
FROM v_device_attribute WHERE starts_with(device_id, 'ROOT_HUB')
UNION ALL
SELECT physical_device_id, 'wireless_interface', 'USB base class E0 (wireless)'
FROM v_device_attribute WHERE has_usb_class(compatible_ids, 'e0')
UNION ALL
SELECT physical_device_id, 'wireless_interface', 'Bluetooth setup class on ' || device_key
FROM v_device_attribute WHERE class_guid = '{e0cbf06c-cd8b-4647-bb8a-263b43f0f974}'
UNION ALL
SELECT physical_device_id, 'vendor_specific_interface',
       'USB base class FF (vendor specific) on ' || device_key
FROM v_device_attribute WHERE has_usb_class(compatible_ids, 'ff')
UNION ALL
SELECT physical_device_id, 'display_interface', 'setup class ' || class_guid
FROM v_device_attribute WHERE class_guid IN (
    '{4d36e968-e325-11ce-bfc1-08002be10318}',
    '{4d36e96e-e325-11ce-bfc1-08002be10318}')

-- What the device did, rather than what it declares.
UNION ALL
SELECT DISTINCT g.physical_device_id, 'mounted_volume',
       'volume ' || l.volume_id || ' linked at ' || l.confidence
FROM v_device_volume_link l
JOIN v_device_group g ON g.device_key = l.device_key
UNION ALL
SELECT DISTINCT g.physical_device_id, 'file_activity',
       'file records attributed at ' || a.confidence
FROM v_file_attribution a
JOIN v_device_group g ON g.device_key = a.device_key

-- Identity quality.
UNION ALL
SELECT physical_device_id, 'no_serial',
       'no identity in this device reported a serial'
FROM v_physical_device WHERE identity_not_unique
UNION ALL
SELECT physical_device_id, 'partial_artefacts',
       'no registry key for this device is in this collection'
FROM v_physical_device WHERE NOT in_registry
UNION ALL
SELECT a.physical_device_id, 'duplicate_serial',
       'serial ' || a.serial || ' is also reported by ' || b.physical_device_id
FROM v_physical_device a
JOIN v_physical_device b ON upper(a.serial) = upper(b.serial)
                        AND a.physical_device_id <> b.physical_device_id
WHERE a.serial <> ''
UNION ALL
-- Grouped rather than written as a correlated subquery over the inventory: the
-- grouping is a recursive closure, and asking it once per device turned a four
-- second run into one that did not finish.
SELECT physical_device_id, 'no_vid_pid',
       'no identity in this device carries a vendor and product id'
FROM v_device_group
GROUP BY physical_device_id
HAVING max(CASE WHEN device_vid_pid(device_key) <> '' THEN 1 ELSE 0 END) = 0
UNION ALL
SELECT DISTINCT physical_device_id, 'unresolved_identity_link',
       'a candidate link to ' || other_physical_device_id || ' was not acted on'
FROM v_device_candidate_link WHERE NOT already_grouped

-- The shape of the connections, which is a statement about use rather than
-- about the device.
UNION ALL
SELECT DISTINCT g.physical_device_id, 'short_lived_connection',
       'a connection lasting ' || c.span_seconds || ' second(s)'
FROM v_connection c
JOIN v_device_group g ON g.device_key = c.device_key
WHERE c.start_known AND NOT c.open_ended AND c.span_seconds < 60
UNION ALL
SELECT g.physical_device_id, 'repeated_connection',
       count(*) || ' connection windows'
FROM v_connection c
JOIN v_device_group g ON g.device_key = c.device_key
GROUP BY g.physical_device_id
HAVING count(*) >= 3

-- A node the operating system created rather than something anyone plugged in.
UNION ALL
SELECT physical_device_id, 'software_device',
       'every identity in this device is a software-enumerated node'
FROM v_device_group
GROUP BY physical_device_id
HAVING max(CASE WHEN split_part(device_key, '\', 1) NOT IN
                     ('SWD', 'SWC', 'ROOT', 'STORAGE', 'BTH', 'MBFW', 'COMPUTER')
                THEN 1 ELSE 0 END) = 0
   -- A phone can be known only from its WPDBUSENUM node, and calling that a
   -- software node would drop a portable device out of tier 1 entirely.
   AND max(CASE WHEN contains(device_key, 'WPDBUSENUM') THEN 1 ELSE 0 END) = 0

-- Whether the thing was ever attached over USB. Boobook reports the internal
-- disks because they explain the file records that reach no removable device,
-- but an internal NVMe ranked above a memory stick, and flagged for review
-- because it has no vendor id, is exactly the noise tiering exists to remove.
UNION ALL
SELECT DISTINCT physical_device_id, 'usb_attached',
       'identity ' || device_key || ' is enumerated on the USB bus'
FROM v_device_group
WHERE split_part(device_key, '\', 1) IN ('USB', 'USBSTOR')
UNION ALL
SELECT DISTINCT physical_device_id, 'usb_attached',
       'a USB compatible id on ' || device_key
FROM v_device_attribute WHERE starts_with(compatible_ids, 'USB\')

UNION ALL
SELECT DISTINCT a.physical_device_id, 'known_class', 'setup class ' || c.class_name
FROM v_device_attribute a
JOIN rule_setup_class c ON c.class_guid = a.class_guid;

-- Facts about combinations of the facts above. Kept separate because these are
-- the ones the reference document asks for by name, and a reader should be able
-- to see that they were derived rather than read.
CREATE VIEW v_device_derived_fact AS
WITH interfaces AS (
    SELECT physical_device_id, count(DISTINCT fact) AS interface_count,
           string_agg(DISTINCT fact, ', ' ORDER BY fact) AS interface_facts
    FROM v_device_fact_evidence
    WHERE fact IN ('storage_identity', 'hid_interface', 'printer_interface',
                   'imaging_interface', 'audio_interface', 'video_interface',
                   'network_interface', 'serial_interface', 'smartcard_interface',
                   'hub_interface', 'wireless_interface', 'mtp_interface',
                   'optical_identity', 'vendor_specific_interface',
                   'biometric_interface', 'display_interface')
    GROUP BY physical_device_id
),
present AS (
    SELECT DISTINCT physical_device_id, fact FROM v_device_fact_evidence
)
SELECT physical_device_id, 'multiple_interfaces' AS fact,
       'exposes ' || interface_count || ' interface classes: ' || interface_facts AS evidence
FROM interfaces WHERE interface_count > 1
UNION ALL
SELECT physical_device_id, 'hid_only', 'a human interface and nothing else'
FROM interfaces WHERE interface_count = 1 AND interface_facts = 'hid_interface'
UNION ALL
SELECT physical_device_id, 'audio_only', 'an audio interface and nothing else'
FROM interfaces WHERE interface_count = 1 AND interface_facts = 'audio_interface'
UNION ALL
-- The reference document's own example of a class conflicting with the apparent
-- purpose. It is a review flag and the heaviest suspicion weight.
--
-- Only where no hub sits between the two. A dock is a hub with a keyboard, an
-- ethernet port and a monitor attached through it, and those functions group
-- into one physical device because they share a container. Read without the hub
-- condition the shape is indistinguishable from a keystroke injector, and on the
-- reference host every dock and every hub-and-ethernet adapter was reported as a
-- potentially offensive device. A keystroke injector presents its own interfaces
-- as a composite device; it is not a hub other devices attach through.
SELECT DISTINCT h.physical_device_id, 'hid_with_storage_or_network',
       'a human interface alongside ' || o.fact
FROM present h
JOIN present o USING (physical_device_id)
WHERE h.fact = 'hid_interface'
  AND o.fact IN ('storage_identity', 'network_interface')
  AND NOT EXISTS (SELECT 1 FROM present b
                  WHERE b.physical_device_id = h.physical_device_id
                    AND b.fact = 'hub_interface')
UNION ALL
-- The same pairing where a hub is present. Recorded rather than dropped: the
-- ordinary reading is a dock, but a hub is also where a device would hide this
-- shape, and an analyst who wants the question asked can find it in devices.csv
-- without the tool having answered it for them.
SELECT DISTINCT h.physical_device_id, 'mixed_interfaces_behind_hub',
       'a human interface alongside ' || o.fact || ', behind a hub'
FROM present h
JOIN present o USING (physical_device_id)
WHERE h.fact = 'hid_interface'
  AND o.fact IN ('storage_identity', 'network_interface')
  AND EXISTS (SELECT 1 FROM present b
              WHERE b.physical_device_id = h.physical_device_id
                AND b.fact = 'hub_interface')
UNION ALL
-- The machine's own disk. It is reported as itself rather than ranked among the
-- removable media, and it explains the file records that reach no device.
--
-- The bus enumeration is what says so, not the silence. "No USB attachment was
-- observed" was doing the whole job here, and that is not the same claim: a
-- collection missing a control set, a hive that failed to replay, or a devnode
-- walk that was refused all produce exactly that silence, and the tool would
-- have answered "internal disk" to a question the evidence never reached. The
-- absence is still recorded, one fact along, in its own words.
SELECT s.physical_device_id, 'internal_bus',
       'storage enumerated on ' || (SELECT min(split_part(g.device_key, '\', 1))
                                    FROM v_device_group g
                                    WHERE g.physical_device_id = s.physical_device_id
                                      AND split_part(g.device_key, '\', 1) IN
                                          ('SCSI', 'IDE', 'ATA', 'NVME', 'PCI', 'RAID'))
       || ', a fixed bus, and on no USB bus'
FROM present s
WHERE s.fact = 'storage_identity'
  AND NOT EXISTS (SELECT 1 FROM present u
                  WHERE u.physical_device_id = s.physical_device_id
                    AND u.fact = 'usb_attached')
  AND EXISTS (SELECT 1 FROM v_device_group g
              WHERE g.physical_device_id = s.physical_device_id
                AND split_part(g.device_key, '\', 1) IN
                    ('SCSI', 'IDE', 'ATA', 'NVME', 'PCI', 'RAID'))
UNION ALL
-- And the same silence where nothing affirms a bus either way. Neutral by
-- design: it says what was not seen, and the reader is left to decide whether
-- that is a fixed disk or a collection that did not reach the evidence. It
-- carries the same score weight as internal_bus and keeps the device out of
-- v_removable_device, so an unknown is treated as cautiously as a known
-- internal disk — under-claiming, which is the direction to fail in.
SELECT s.physical_device_id, 'usb_attachment_not_observed',
       'storage with no USB enumeration in this collection, and no fixed-bus '
       || 'enumeration either'
FROM present s
WHERE s.fact = 'storage_identity'
  AND NOT EXISTS (SELECT 1 FROM present u
                  WHERE u.physical_device_id = s.physical_device_id
                    AND u.fact = 'usb_attached')
  AND NOT EXISTS (SELECT 1 FROM v_device_group g
                  WHERE g.physical_device_id = s.physical_device_id
                    AND split_part(g.device_key, '\', 1) IN
                        ('SCSI', 'IDE', 'ATA', 'NVME', 'PCI', 'RAID'))
UNION ALL
-- A programme ran from a volume this device carried.
--
-- Read from v_prefetch_device_link rather than from the attribution table,
-- because the facts are consolidated before the attribution is and this view
-- would otherwise see the previous run's rows. The chain is the same one, and
-- it is decided in that view either way.
SELECT g.physical_device_id, 'executable_run_from_removable',
       count(DISTINCT p.executable)
           || ' programme(s) ran from a volume this device carried, including '
           || min(p.executable)
FROM v_prefetch_device_link p
JOIN v_device_group g ON g.device_key = p.device_key
-- A contradicted letter is left out because this fact carries score weight and
-- says the device carried the volume, which is the very thing in doubt. The
-- execution is still reported — it is in the attribution, the timeline and the
-- headline findings, labelled with the disagreement — but the conclusion is not
-- drawn against a device the volume's own label says it was not on.
WHERE p.ran_from AND NOT p.letter_contradicted
GROUP BY g.physical_device_id
UNION ALL
SELECT d.physical_device_id, 'unknown_class',
       'no recognised setup class and no USB base class'
FROM (SELECT DISTINCT physical_device_id FROM v_device_group) d
LEFT JOIN (SELECT DISTINCT physical_device_id FROM present WHERE fact = 'known_class') k
       ON k.physical_device_id = d.physical_device_id
LEFT JOIN interfaces i ON i.physical_device_id = d.physical_device_id
WHERE k.physical_device_id IS NULL AND i.physical_device_id IS NULL;

CREATE VIEW v_device_fact_computed AS
SELECT physical_device_id, fact,
       string_agg(DISTINCT evidence, '; ' ORDER BY evidence) AS evidence,
       count(*) AS evidence_count
FROM (SELECT * FROM v_device_fact_evidence
      UNION ALL SELECT * FROM v_device_derived_fact)
GROUP BY physical_device_id, fact
ORDER BY physical_device_id, fact;

-- Consolidated once for the same reason as the grouping: the rule matcher and
-- the score both read every fact, and recomputing thirty-odd branches for each
-- would make the classification the slowest thing in the run.
CREATE VIEW v_device_fact AS
SELECT physical_device_id, fact, evidence, evidence_count
FROM device_fact
ORDER BY physical_device_id, fact, evidence_count;

-- Every rule that matched, not only the one that won.
-- Expressed as joins rather than as a correlated subquery per rule per device.
-- The fact pipeline walks the whole grouping closure, and asking it once per
-- (device, rule) pair turned a four second run into one that did not finish.
CREATE VIEW v_device_rule_match AS
WITH device_fact AS (
    SELECT DISTINCT physical_device_id, fact FROM v_device_fact
),
required AS (
    SELECT rule_id, count(*) AS conditions
    FROM rule_condition WHERE NOT coalesce(negate, false)
    GROUP BY rule_id
),
satisfied AS (
    SELECT f.physical_device_id, c.rule_id, count(*) AS met
    FROM device_fact f
    JOIN rule_condition c ON c.fact = f.fact AND NOT coalesce(c.negate, false)
    GROUP BY f.physical_device_id, c.rule_id
),
-- A negated condition whose fact is present rules the whole rule out, which is
-- how "a portable device that never appeared under USBSTOR" is expressed.
excluded AS (
    SELECT DISTINCT f.physical_device_id, c.rule_id
    FROM device_fact f
    JOIN rule_condition c ON c.fact = f.fact AND coalesce(c.negate, false)
)
SELECT s.physical_device_id, r.rule_id, r.category, r.tier, r.priority, r.note
FROM satisfied s
JOIN required q ON q.rule_id = s.rule_id AND q.conditions = s.met
JOIN rule r ON r.rule_id = s.rule_id
WHERE NOT EXISTS (
    SELECT 1 FROM excluded e
    WHERE e.physical_device_id = s.physical_device_id AND e.rule_id = s.rule_id)
ORDER BY s.physical_device_id, r.priority DESC, r.rule_id;

CREATE VIEW v_device_classification AS
WITH chosen AS (
    SELECT physical_device_id, rule_id, category, tier, note,
           row_number() OVER (PARTITION BY physical_device_id
                              ORDER BY priority DESC, rule_id) AS choice
    FROM v_device_rule_match
),
matched AS (
    SELECT physical_device_id,
           string_agg(rule_id, '; ' ORDER BY priority DESC, rule_id) AS matched_rules,
           count(*) AS rules_matched
    FROM v_device_rule_match
    GROUP BY physical_device_id
),
scored AS (
    SELECT f.physical_device_id,
           sum(i.weight) AS raw_score,
           string_agg(f.fact || ' ' ||
                      CASE WHEN i.weight >= 0 THEN '+' ELSE '' END ||
                      round(i.weight, 1), ', '
                      ORDER BY abs(i.weight) DESC, f.fact) AS score_reason
    FROM v_device_fact f
    JOIN rule_indicator i USING (fact)
    GROUP BY f.physical_device_id
),
-- Review is scoped to things somebody plugged in. A software-enumerated node
-- has no serial and no vendor id because it is not a device, and the machine's
-- own disk is not a USB finding: flagging all of those put 81 of 82 devices in
-- review, which is the same as flagging none of them.
review AS (
    SELECT f.physical_device_id,
           string_agg(r.note, ' ' ORDER BY r.fact) AS review_reason
    FROM v_device_fact f
    JOIN rule_review_fact r USING (fact)
    WHERE NOT EXISTS (
        SELECT 1 FROM v_device_fact x
        WHERE x.physical_device_id = f.physical_device_id
          AND x.fact IN ('software_device', 'internal_bus',
                         'usb_attachment_not_observed'))
      -- And the fact is dropped where the device is one of the classes it is
      -- normal for. A keyboard has no serial and never did: flagged on every
      -- such device the absence buries the cases where it is the finding.
      AND NOT EXISTS (
        SELECT 1 FROM rule_review_exception e
        JOIN v_device_fact y
          ON y.physical_device_id = f.physical_device_id
         AND y.fact = e.unless_fact
        WHERE e.fact = f.fact)
    GROUP BY f.physical_device_id
),
facts AS (
    SELECT physical_device_id,
           string_agg(fact, ', ' ORDER BY fact) AS facts,
           string_agg(fact || ' (' || evidence || ')', '; ' ORDER BY fact) AS fact_evidence
    FROM v_device_fact
    GROUP BY physical_device_id
),
winner AS (
    SELECT * FROM chosen WHERE choice = 1
)
SELECT
    d.physical_device_id,
    coalesce(c.category, 'Unknown')                         AS category,
    coalesce(c.tier, 3)                                     AS tier,
    coalesce(g.relevance, 'review')                         AS relevance,
    -- Clamped so two cases can be compared. raw_score is kept beside it because
    -- a clamp is a presentation choice, not a finding.
    coalesce(greatest(0, least(100, round(s.raw_score))), 0) AS score,
    coalesce(round(s.raw_score, 1), 0)                      AS raw_score,
    (SELECT max(profile) FROM rule_indicator)               AS profile,
    coalesce(c.rule_id, '')                                 AS rule_id,
    coalesce(m.matched_rules, '')                           AS matched_rules,
    coalesce(m.rules_matched, 0)                            AS rules_matched,
    -- Why this category, naming the rule and the evidence under it. A
    -- classification an analyst cannot interrogate is one they should not trust.
    CASE WHEN c.rule_id IS NULL
         THEN 'no rule matched; facts: ' || coalesce(f.facts, 'none derived')
         ELSE 'matched ' || c.rule_id ||
              CASE WHEN coalesce(c.note, '') = '' THEN '' ELSE ' — ' || c.note END ||
              '; facts: ' || coalesce(f.facts, 'none derived')
    END                                                     AS classification_reason,
    coalesce(s.score_reason, '')                            AS score_reason,
    -- A separate flag, not a tier. A tier 3 keyboard with a duplicated serial
    -- still needs looking at, and demoting it would hide that.
    r.review_reason IS NOT NULL                             AS review_required,
    coalesce(r.review_reason, '')                           AS review_reason,
    coalesce(f.facts, '')                                   AS facts,
    coalesce(f.fact_evidence, '')                           AS fact_evidence
FROM v_physical_device d
LEFT JOIN winner  c USING (physical_device_id)
LEFT JOIN rule_category g ON g.category = c.category
LEFT JOIN matched m USING (physical_device_id)
LEFT JOIN scored  s USING (physical_device_id)
LEFT JOIN review  r USING (physical_device_id)
LEFT JOIN facts   f USING (physical_device_id)
ORDER BY tier, score DESC, d.physical_device_id;

-- The name a timeline row shows for a device, taken from the identity the
-- grouping preferred.
--
-- Two things had to be said here that were not.
--
-- **A drive path is not a name.** A portable-device node's FriendlyName is the
-- volume's label, and where a volume has no label Windows writes the drive
-- path into it instead: `D:\`. That is a mount point rather than a device, it
-- moves between devices within one uptime, and two sticks that each held D: get
-- the same name. Reported from real evidence, where the file activity section
-- showed two cards both headed "D:\" and a chip row reading "D:\ D:\" — with
-- the vendor and product sitting in the instance id underneath, unread. Refused
-- here for the same reason the RecentDocs captions refuse `Removable Disk (E:)`:
-- offering a name no volume ever carried is how an attribution gets built on
-- nothing.
--
-- **And the preference has to be applied across the fields, not within each
-- one.** The coalesce asked every identity for a friendly name before it asked
-- the preferred identity for anything else, so a preference 6 software node
-- beat the USBSTOR node it was grouped with. That is what let `D:\` win over a
-- real device description, and it would do the same to any other weak name.
--
-- Where nothing else is left, the vendor and product out of the USBSTOR or SCSI
-- device id are used: a generic stick's node often carries no FriendlyName at
-- all and a DeviceDesc of "@disk.inf,%disk_devdesc%;Disk drive", which names
-- every disk on the host equally well.
CREATE MACRO is_drive_path(name) AS
    regexp_matches(trim(name), '^[A-Za-z]:\\?$');

-- Disk&Ven_Vendor&Prod_Product&Rev_2.00 -> Vendor Product. Empty
-- where the key is not that shape, so the coalesce below falls through it.
CREATE MACRO device_id_product(device_id) AS
    trim(regexp_replace(
        replace(
            regexp_extract(device_id, 'Ven_([^&]*)&Prod_([^&]*)', 1)
            || ' ' ||
            regexp_extract(device_id, 'Ven_([^&]*)&Prod_([^&]*)', 2),
            '_', ' '),
        ' +', ' ', 'g'));

-- Defined above v_device_classified rather than beside the other naming
-- views, because that view now reads it: DuckDB creates these in file
-- order, so a view can only reference one written before it.
CREATE VIEW v_device_label AS
WITH named AS (
    SELECT
        g.physical_device_id,
        g.preference,
        -- A drive path is refused before anything else sees it.
        nullif(CASE WHEN is_drive_path(d.friendly_name) THEN ''
                    ELSE d.friendly_name END, '')     AS friendly_name,
        nullif(device_id_product(d.device_id), '')    AS product,
        nullif(d.device_desc, '')                     AS device_desc,
        nullif(d.bus_reported_desc, '')               AS bus_reported_desc,
        CASE WHEN coalesce(d.serial_is_generated, true) THEN '' ELSE d.serial END
                                                      AS serial
    FROM v_device_group g
    LEFT JOIN v_devnode d ON d.device_key = g.device_key
),
picked AS (
    SELECT
        physical_device_id,
        -- Field first, then preference within the field, which is the order it
        -- has always been in and is right: a product name from a software node
        -- is worth more than "USB Composite Device" from the USB node above it.
        -- Reordering this to preference-first renamed a Fibocom modem after the
        -- composite node it hangs off.
        --
        -- The vendor and product out of the device id sit second, above the
        -- description, because they only produce anything for a Ven_x&Prod_y
        -- key -- the storage node -- and there the description is the INF
        -- template's "Disk drive", which fits every disk on the host equally.
        coalesce(
            arg_min(friendly_name, preference) FILTER (WHERE friendly_name IS NOT NULL),
            arg_min(product, preference) FILTER (WHERE product IS NOT NULL),
            arg_min(device_desc, preference) FILTER (WHERE device_desc IS NOT NULL),
            arg_min(bus_reported_desc, preference) FILTER (WHERE bus_reported_desc IS NOT NULL),
            physical_device_id) AS base,
        arg_min(serial, preference) FILTER (WHERE serial <> '') AS serial
    FROM named
    GROUP BY physical_device_id
),
-- A name two devices share is not a name. Two sticks of one model carry one
-- description, and the report headed both their cards with it and listed the
-- pair as one chip repeated, which reads as a rendering fault rather than as
-- two devices.
--
-- Only a real serial disambiguates. A generated instance id would make every
-- volume shadow copy and root hub on the host carry forty characters of key it
-- shares with nothing -- noise in place of a name, and the card prints the
-- full identity underneath either way.
shared AS (
    SELECT base, count(*) AS devices FROM picked GROUP BY base
)
SELECT
    p.physical_device_id,
    CASE WHEN s.devices > 1 AND p.serial IS NOT NULL
         THEN p.base || ' · ' || p.serial
         ELSE p.base END AS device_label
FROM picked p
JOIN shared s USING (base);

-- The device inventory as an analyst reads it: what it is, how much it matters,
-- and why, beside everything the grouping established about it.
CREATE VIEW v_device_classified AS
SELECT
    c.category, c.tier, c.relevance, c.score, c.review_required,
    -- The name a person recognises, before the identifiers. An analyst opening
    -- devices.csv reads across from the classification looking for something to
    -- hold on to, and forty characters of instance id is not it. The identifiers
    -- follow immediately; nothing is dropped, only ordered.
    d.friendly_name,
    -- The name the rest of the report calls this device, disambiguated by
    -- serial where two devices would otherwise share one. It is the same
    -- v_device_label the timeline chips and the file activity cards read, and
    -- it is here so that every place a device is named on the page reads one
    -- answer: the tier filter offered three pills reading "USB SanDisk
    -- 3.2Gen1 USB Device" because the card path coalesced the fields in Go
    -- instead, which is the Go-side copy this view was written to replace.
    coalesce(n.device_label, d.friendly_name, d.physical_device_id)
                                                          AS device_label,
    d.* EXCLUDE (friendly_name),
    c.raw_score, c.profile, c.rule_id, c.matched_rules, c.rules_matched,
    c.classification_reason, c.score_reason, c.review_reason,
    c.facts, c.fact_evidence
FROM v_physical_device d
JOIN v_device_classification c USING (physical_device_id)
LEFT JOIN v_device_label n ON n.physical_device_id = d.physical_device_id
ORDER BY c.tier, c.score DESC, d.physical_device_id, d.physical_device_id;

-- The rule set as it was applied, exported beside the results. A run reported
-- months later can then be checked against the rules that produced it rather
-- than against whatever the tool ships by then.
CREATE VIEW v_rule AS
SELECT
    r.rule_id,
    r.category,
    r.tier,
    g.relevance,
    r.priority,
    (SELECT string_agg(CASE WHEN c.negate THEN 'NOT ' ELSE '' END || c.fact,
                       ' AND ' ORDER BY c.fact)
     FROM rule_condition c WHERE c.rule_id = r.rule_id) AS conditions,
    r.note
FROM rule r
LEFT JOIN rule_category g ON g.category = r.category
ORDER BY r.priority DESC, r.rule_id;

CREATE VIEW v_rule_indicator AS
SELECT fact, indicator_group, base_weight, weight,
       round(CASE WHEN base_weight = 0 THEN 1 ELSE weight / base_weight END, 3)
           AS profile_multiplier,
       profile, note
FROM rule_indicator
ORDER BY indicator_group, abs(weight) DESC, fact, weight, note;

-- ---- the timeline ----------------------------------------------------------
--
-- One row per timestamped record, whatever artefact holds it.
--
-- The difficulty this view exists to handle is that the records do not carry
-- the same kind of time. An event log record carries a UTC instant. A setupapi
-- section and a shell item's FAT timestamp carry local wall clock with no zone,
-- and converting those needs the host bias — which changes with the season, and
-- neither record says which season it was written in. Merging the two kinds
-- into one sorted column is how a timeline acquires events that never happened,
-- so they are kept apart: time_utc is only ever a UTC instant, time_local is
-- only ever the wall clock exactly as recorded, and time_basis says which of
-- the two the row rests on.

-- The host's biases, ready to apply. Zero rows means the time zone was not
-- recoverable, in which case a wall clock has no UTC reading at all rather than
-- one computed from an assumed offset.
CREATE VIEW v_host_time_zone AS
SELECT
    key_name,
    standard_name,
    daylight_name,
    bias_minutes,
    standard_bias_minutes,
    daylight_bias_minutes,
    active_bias_minutes,
    bias_minutes + standard_bias_minutes AS standard_offset_minutes,
    bias_minutes + standard_bias_minutes + daylight_bias_minutes
        AS daylight_offset_minutes,
    standard_start_month,
    daylight_start_month,
    dynamic_daylight_disabled,
    -- Whether the host actually changes its clock, which decides whether a wall
    -- clock recorded on it has one reading or two.
    --
    -- The daylight bias alone does not answer it. DaylightBias belongs to the
    -- zone's definition and is stored whether or not the transitions are ever
    -- taken: W. Australia Standard Time carries -60 with both rules empty,
    -- because Western Australia abolished daylight saving in 2009. Read from
    -- the bias alone, every Perth host was reported as seasonally ambiguous and
    -- given a UTC+9 alternative reading no evidence supported — 88 entries on
    -- USB-LENOVO-Multi-USBs. Windows says "no daylight saving" by leaving
    -- wMonth zero in the transition rules, and a user can say it a second way
    -- with DynamicDaylightTimeDisabled.
    daylight_bias_minutes <> 0
        AND coalesce(standard_start_month, 0) <> 0
        AND coalesce(daylight_start_month, 0) <> 0
        AND NOT coalesce(dynamic_daylight_disabled, false)
        AS observes_daylight_saving,
    registry_key,
    control_set,
    source_id
FROM host_time_zone
ORDER BY control_set, key_name, source_id;

-- A recorded local wall clock as a timestamp. Two layouts reach here: the
-- "2026-07-26 10:00:06" the shell item parsers write, and the slash-separated
-- form with milliseconds that setupapi.dev.log uses.
CREATE MACRO local_timestamp(text) AS
    coalesce(try_cast(nullif(text, '') AS TIMESTAMP),
             try_strptime(nullif(text, ''), '%Y/%m/%d %H:%M:%S.%f'));

-- A timestamp that came from a clock's default rather than from a clock, named.
--
-- Two shapes of this reach the artefacts Boobook reads.
--
-- The first is the zero of a storage format, which is what the field holds when
-- nothing was written into it: 1601-01-01 is FILETIME zero, 1970-01-01 is the
-- Unix epoch, and 1980-01-01 is the FAT/DOS epoch and what a zeroed DOS date
-- widens into.
--
-- The second is a device whose real-time clock lost power. Cheap flash media,
-- cameras and dashcams restart at 2000-01-01, so a file written on one carries
-- a date in 2000 that measures the device's uptime and not the moment. This is
-- the population a USB tool examines, which is why 2000-01-01 earns a place
-- here that it would not earn in a general-purpose date library.
--
-- Both are matched by range rather than exactly, which is a deliberate
-- departure from how wintime refuses the stored forms. wintime compares the
-- value as the artefact holds it, where an exact match is right and a range
-- would discard a genuine old timestamp. By the time a value reaches here it
-- has survived that check and then been converted, or was written by a clock
-- that was merely wrong rather than unset: a wall clock of 1980-01-01 00:00
-- read on a host at UTC+10 arrives as 1979-12-31 14:00, which is the same
-- sentinel and no longer equal to it, and a file written thirty seconds after a
-- device reset at 2000-01-01 00:00 in UTC+11 arrives as 1999-12-31 13:00:30.
-- Both were seen on real evidence; the first set the head of a report's span.
--
-- Fourteen hours either side covers every offset a real zone uses, UTC-12 to
-- UTC+14. For the three format zeros the window costs nothing, because those
-- dates predate the evidence: no Windows host wrote a USB record in 1601 or
-- 1970, and 1980-01-01 is the first date FAT can express at all.
--
-- The last arm is the weakest and is the one to revisit if it ever misfires.
-- A device that reset to 2000-01-01 keeps running, so its files spread forward
-- from there, and what they spread into is not a sentinel: eight jump list
-- entries on live evidence named PDFs on one volume at 04:05:02, 05:36:20,
-- 05:39:58, 05:42:32, 05:44:52, 05:53:44, 05:57:46 and 17:54:20 on 2000-01-04
-- — seven of them minutes apart in one session, which is a person opening
-- documents and not a placeholder, on a clock three days into its reset. So
-- the rest of January 2000 is claimed, and nothing beyond it: a month is long
-- enough to cover a device left powered, and short enough that the flag does
-- not creep across years of genuine dates. It labels and excludes from the
-- span; it never drops a row, so the cost of being wrong about a real file
-- written in January 2000 is a label an analyst can dismiss.
-- The same defaults, tested against a wall clock exactly as the artefact
-- recorded it — before any host bias is applied to it.
--
-- This runs first, and where it matches nothing is converted. A device whose
-- real-time clock reset to 2000-01-01 wrote that value using its own clock,
-- which has no zone at all; applying the examiner's host bias to it produces
-- an instant that appears in no artefact and never happened. On a host at
-- UTC+11 the placeholder surfaced as 1999-12-31 13:00:30, which reads as a
-- genuine twentieth-century date and sorted like one.
--
-- No window is needed here and none is used. epoch_default_name has to allow
-- fourteen hours either side because it sees a value an offset has already
-- moved; this sees the value as written, so the match is the calendar date
-- itself and cannot swallow a real timestamp from the day before.
CREATE MACRO epoch_default_local(ts) AS
    CASE
        WHEN ts IS NULL THEN ''
        WHEN CAST(ts AS DATE) = DATE '1601-01-01' THEN 'FILETIME zero, 1601-01-01'
        WHEN CAST(ts AS DATE) = DATE '1970-01-01' THEN 'the Unix epoch, 1970-01-01'
        WHEN CAST(ts AS DATE) = DATE '1980-01-01' THEN 'the FAT epoch, 1980-01-01'
        WHEN CAST(ts AS DATE) = DATE '2000-01-01'
            THEN 'an unset device clock at 2000-01-01'
        WHEN ts >= TIMESTAMP '2000-01-01 00:00:00'
             AND ts <  TIMESTAMP '2000-02-01 00:00:00'
            THEN 'an unset device clock running on from 2000-01-01'
        ELSE '' END;

CREATE MACRO epoch_default_name(ts) AS
    CASE
        WHEN ts IS NULL THEN ''
        WHEN ts BETWEEN TIMESTAMP '1600-12-31 10:00:00'
                    AND TIMESTAMP '1601-01-01 14:00:00'
            THEN 'FILETIME zero, 1601-01-01'
        WHEN ts BETWEEN TIMESTAMP '1969-12-31 10:00:00'
                    AND TIMESTAMP '1970-01-01 14:00:00'
            THEN 'the Unix epoch, 1970-01-01'
        WHEN ts BETWEEN TIMESTAMP '1979-12-31 10:00:00'
                    AND TIMESTAMP '1980-01-01 14:00:00'
            THEN 'the FAT epoch, 1980-01-01'
        WHEN ts BETWEEN TIMESTAMP '1999-12-31 10:00:00'
                    AND TIMESTAMP '2000-01-01 14:00:00'
            THEN 'an unset device clock at 2000-01-01'
        WHEN ts >= TIMESTAMP '2000-01-01 00:00:00'
             AND ts <  TIMESTAMP '2000-02-01 00:00:00'
            THEN 'an unset device clock running on from 2000-01-01'
        ELSE '' END;

CREATE VIEW v_timeline AS
WITH
-- The confidence each candidate device earned for a record, best route first.
-- A device reached by two routes keeps the stronger; the weaker one is not
-- evidence against it.
per_device AS (
    SELECT activity_id, device_key,
           min(CASE confidence WHEN 'confirmed' THEN 1 WHEN 'strong' THEN 2
                               WHEN 'probable'  THEN 3 ELSE 4 END) AS confidence_rank,
           -- The rank the contest below uses, which is not the one reported.
           --
           -- A contradicted route is the record's own label saying this letter
           -- names the wrong device, so it does not get to tie with a route
           -- nothing contradicts. Ranked below every real confidence rather
           -- than dropped: the row keeps its place and its reasoning in
           -- file-attribution.csv, and what it loses is the right to make the
           -- timeline say nothing by drawing level.
           --
           -- A device reached by a contradicted route *and* an uncontradicted
           -- one keeps the better rank, because the contradiction is a fact
           -- about the route rather than about the device.
           min(CASE WHEN contradicted THEN 5
                    WHEN confidence = 'confirmed' THEN 1
                    WHEN confidence = 'strong'    THEN 2
                    WHEN confidence = 'probable'  THEN 3
                    ELSE 4 END)                              AS contest_rank
    FROM v_file_attribution
    GROUP BY activity_id, device_key
),
ranked AS (
    SELECT *, min(contest_rank) OVER (PARTITION BY activity_id) AS best_rank
    FROM per_device
),
-- One device per file record: the one the strongest route reached.
--
-- This once required every route to agree and named nothing otherwise, which
-- was right while the routes could tie. They no longer routinely do. The letter
-- route is demoted wherever no connection window places the device, so on
-- USB-LENOVO-Multi-USBs the label route reaches GEN32GBF32 at probable while
-- the stale E: mapping reaches the SanDisk at possible — and refusing to name
-- either threw away an answer the evidence had settled, leaving ten file opens
-- on a timeline with no device against them.
--
-- A tie at the top is still unnamed. Two devices reached with equal confidence
-- is a question the evidence has not settled, and picking one would settle it
-- by fiat rather than by evidence. That is what best_candidates counts, and it
-- is the count the naming turns on: candidates alone would refuse to name the
-- winner of a contest it won.
attributed AS (
    SELECT
        activity_id,
        count(DISTINCT device_key) AS candidates,
        count(DISTINCT device_key) FILTER (WHERE contest_rank = best_rank)
            AS best_candidates,
        min(device_key) FILTER (WHERE contest_rank = best_rank) AS device_key,
        -- The confidence reported is the winner's own, not the contest rank:
        -- where every candidate is contradicted the best rank is 5, which is
        -- not a confidence and would index off the end of this list.
        list_extract(['confirmed', 'strong', 'probable', 'possible'],
            min(confidence_rank) FILTER (WHERE contest_rank = best_rank))
            AS confidence
    FROM ranked
    GROUP BY activity_id
),
entry AS (

    -- Event log records other than arrivals and departures. Those are left to
    -- the connection windows below, which already fold the several channels
    -- reporting one arrival into the single transition they describe.
    SELECT
        -- A session record is about the host, not about a device, and putting
        -- it under 'device' with an empty device column made it read as a
        -- device event whose device could not be worked out. It is its own
        -- category because it answers a different question: not what happened
        -- to a device, but whether the machine was on to record anything.
        CASE WHEN e.kind = 'session' THEN 'session'
             -- A logon names a person, not a device. Under 'device' with an
             -- empty device column it would read as a device event whose
             -- device could not be worked out.
             WHEN e.kind = 'logon'   THEN 'logon'
             ELSE 'device' END                      AS category,
        e.kind                                      AS event,
        -- Where the catalogue gave the rule no wording, the row still has to
        -- say what its timestamp is. The record's own write time is the honest
        -- fallback, and it is what the channel actually recorded.
        -- A capacity-zero disk record says something the rule's wording cannot:
        -- the partition driver described a disk with no capacity, which is what
        -- a device going away looks like from that channel. It closes no window
        -- — see v_disk_departure_candidate for why — and a reader who is not
        -- told what the zero means has no way to reach it.
        CASE WHEN EXISTS (
                 SELECT 1 FROM v_disk_departure_candidate z
                 WHERE z.record_id = e.record_id AND z.source_id = e.source_id)
             THEN 'the partition driver described this disk with no capacity, '
               || 'which is what a removal looks like from this channel. It is '
               || 'not treated as one: an empty slot in a card reader reports '
               || 'the same thing while the reader stays in the port'
             ELSE coalesce(nullif(e.meaning, ''),
                 'the time this record was written to ' || e.channel) END AS meaning,
        e.time_utc                                  AS time_utc,
        ''                                          AS time_local,
        e.device_key                                AS device_key,
        ''                                          AS drive_letter,
        ''                                          AS path,
        ''                                          AS profile,
        'confirmed'                                 AS confidence,
        'windows_event_log'                         AS artefact,
        e.channel || ' event ' || e.event_id
            || coalesce(' (' || nullif(e.rule_id, '') || ')', '') AS detail,
        e.record_id                                 AS record_id,
        e.source_id                                 AS source_id,
        e.source_path                               AS source_path
    FROM v_event e
    WHERE e.time_utc IS NOT NULL
      AND e.kind NOT IN ('connect', 'disconnect')

    UNION ALL

    -- The opening of a connection window: the earliest record placing the
    -- device on the machine, with the count of records that agree.
    SELECT
        'connection', 'device_connected',
        'the earliest record placing this device on the machine',
        c.started_utc, '', c.device_key, '', '', '', 'confirmed',
        'connection_window',
        'opened by ' || c.opened_by || '; ' || c.supporting_records
            || ' record(s) support this window; '
            || CASE WHEN c.ended_before_utc IS NOT NULL
                    THEN 'no removal was recorded after it, and the device '
                         || 'arrived again at ' || c.ended_before_utc
                         || ', so it left at some unrecorded point before that'
                    -- A shutdown with a device still in the port writes no
                    -- departure record, so it is the ordinary explanation for
                    -- an open window and worth saying rather than leaving the
                    -- reader to wonder whether a record was lost.
                    WHEN c.host_stopped_utc IS NOT NULL
                    THEN 'no removal was recorded after it, and the host went '
                         || 'off at ' || c.host_stopped_utc
                         || ', which is why: a shutdown with the device still '
                         || 'attached records no departure. Nothing places the '
                         || 'device on the machine after that'
                    -- The same explanation with a bound in place of a moment.
                    -- The stop time is not in the evidence, so the sentence
                    -- gives the interval it lies in rather than picking an end
                    -- of that interval and calling it the shutdown.
                    WHEN c.host_stopped_after_utc IS NOT NULL
                    THEN 'no removal was recorded after it, and the host '
                         || 'stopped without shutting down cleanly: the last '
                         || 'record before the outage is ' || c.host_stopped_after_utc
                         || ' and the boot that reported the unclean stop is '
                         || c.host_stopped_before_utc
                         || '. The stop is somewhere between the two and no '
                         || 'record dates it, so nothing places the device on '
                         || 'the machine after the earlier of them'
                    -- The host did go off and nothing dates it. Saying the
                    -- evidence simply ends here would be false, and false in
                    -- the direction that leaves a reader believing the device
                    -- stayed attached to a running machine.
                    WHEN c.host_stopped_undated
                    THEN 'no removal was recorded after it, and the host is '
                         || 'recorded as having stopped without shutting down '
                         || 'cleanly — but the boot that reported that stop is '
                         || 'not in the evidence, so nothing dates it and it '
                         || 'bounds nothing. The window is open because no '
                         || 'record closes it, not because the device is known '
                         || 'to have stayed'
                    WHEN c.open_ended
                    THEN 'no removal was recorded after it, and the host was '
                         || 'not recorded going off either, so the evidence '
                         || 'simply ends with the device attached'
                    ELSE 'the next removal recorded came '
                         || c.span_seconds || ' seconds later' END,
        c.opened_by_record, c.source_id, coalesce(s.path, '')
    FROM v_connection c
    LEFT JOIN source s ON s.id = c.source_id
    WHERE c.started_utc IS NOT NULL

    UNION ALL

    SELECT
        'connection', 'device_removed',
        'the record of this device being removed',
        c.ended_utc, '', c.device_key, '', '', '', 'confirmed',
        'connection_window',
        'closed by ' || c.closed_by
            || CASE WHEN NOT c.start_known
                    THEN '; no arrival was recorded before it, so the device '
                         || 'was already connected when the evidence begins'
                    ELSE '' END,
        c.closed_by_record, c.source_id, coalesce(s.path, '')
    FROM v_connection c
    LEFT JOIN source s ON s.id = c.source_id
    WHERE c.ended_utc IS NOT NULL

    UNION ALL

    -- Driver installs. The log writes local wall clock, so the UTC reading is
    -- derived below from the host biases like every other wall clock here.
    SELECT
        'install', 'setupapi.' || p.kind,
        'the moment this install section opened in setupapi.dev.log',
        CAST(NULL AS TIMESTAMP), p.start_local, p.device_key, '', '', '',
        'confirmed', 'setupapi_log',
        p.operation
            || coalesce(' — exit ' || nullif(p.exit_status, ''), '')
            || coalesce('; ' || nullif(p.problem, ''), ''),
        CAST(p.line_number AS UBIGINT), p.source_id, p.source_file
    FROM setup_section p
    WHERE p.start_local <> '' AND p.device_key <> ''

    UNION ALL

    -- The four PnP lifecycle dates a devnode stores. Each is a single stored
    -- state and not a history: a device connected fifty times has one
    -- LastArrivalDate, and the meaning on every row says so.
    SELECT
        'device_state', 'first_install_date',
        'the registry records this as when this device was first installed on '
            || 'the host',
        l.first_install_date_utc, '', l.device_key, '', '', '', 'confirmed',
        'registry_devnode', 'control set ' || l.control_set,
        CAST(NULL AS UBIGINT), l.source_id, l.source_path
    FROM v_device_lifecycle l
    WHERE l.first_install_date_utc IS NOT NULL

    UNION ALL

    SELECT
        'device_state', 'driver_install_date',
        'the registry records this as when the current driver for this device '
            || 'was installed',
        l.install_date_utc, '', l.device_key, '', '', '', 'confirmed',
        'registry_devnode', 'control set ' || l.control_set,
        CAST(NULL AS UBIGINT), l.source_id, l.source_path
    FROM v_device_lifecycle l
    WHERE l.install_date_utc IS NOT NULL

    UNION ALL

    SELECT
        'device_state', 'last_arrival_date',
        'the registry records this as the most recent time this device was '
            || 'connected; it is one stored state and not a connection history',
        l.last_arrival_date_utc, '', l.device_key, '', '', '', 'confirmed',
        'registry_devnode', 'control set ' || l.control_set,
        CAST(NULL AS UBIGINT), l.source_id, l.source_path
    FROM v_device_lifecycle l
    WHERE l.last_arrival_date_utc IS NOT NULL

    UNION ALL

    SELECT
        'device_state', 'last_removal_date',
        'the registry records this as the most recent time this device was '
            || 'removed; it is one stored state and not a connection history',
        l.last_removal_date_utc, '', l.device_key, '', '', '', 'confirmed',
        'registry_devnode', 'control set ' || l.control_set,
        CAST(NULL AS UBIGINT), l.source_id, l.source_path
    FROM v_device_lifecycle l
    WHERE l.last_removal_date_utc IS NOT NULL

    UNION ALL

    -- When Windows last wrote the device's own key. For a device with no
    -- events at all this is the only time the evidence offers for it, which is
    -- why it is here and not left in devnodes.csv.
    SELECT
        'device_state', 'registry_key_written',
        'when this device key was last written, which is the last time Windows '
            || 'changed something about the device and not necessarily when it '
            || 'was used',
        d.key_last_write_utc, '', d.device_key, '', '', '', 'confirmed',
        'registry_devnode', d.registry_key,
        CAST(NULL AS UBIGINT), d.source_id, d.source_path
    FROM v_devnode d
    WHERE d.device_key <> '' AND d.key_last_write_utc IS NOT NULL

    UNION ALL

    -- File and folder records, carrying whichever device the attribution
    -- routes reached and the confidence they earned.
    SELECT
        -- A launch is an execution, not a file listing. UserAssist flows
        -- through this arm rather than one of its own so that it picks up the
        -- attribution above — it carries a drive letter, which is the only
        -- thing that can reach a device from it — and a second arm would have
        -- put every launch on the timeline twice.
        CASE WHEN a.artefact = 'user_assist' THEN 'execution' ELSE 'file' END,
        -- The event names what the row's *time* evidences, not what the
        -- artefact evidences. A shortcut proves its target was opened whatever
        -- time it carries — but a row placed at the target's own write time
        -- and called file_opened puts a user at a machine at a moment nothing
        -- says they were there. On USB-LENOVO-Multi-USBs that read three
        -- documents as opened from a stick twenty minutes before it was
        -- plugged in.
        --
        -- recorded_meaning already said which time it was. It said so in prose,
        -- under an event name that contradicted it, and the name is what a
        -- reader filters and counts on.
        --
        -- The rule was applied to shortcuts and jump lists and to nothing else,
        -- by matching recorded_meaning with LIKE — a string comparison against
        -- prose, which breaks silently the day the prose is reworded. It reads
        -- recorded_basis now, and it is applied to every artefact here:
        --
        --   *_key_written    the registry key was written then. A bag key is
        --                    updated for view state as well as for a folder
        --                    being displayed, and an MRU key write dates the
        --                    top of its list. Calling either one a folder being
        --                    displayed or a file being listed states a user
        --                    action the key write does not establish.
        --   *_no_later_than  every MRU entry below position 0. One key write
        --                    dates one entry and bounds the rest, by an amount
        --                    nothing records. 43 of the 51 MRU rows on the
        --                    reference collection are in this state and every
        --                    one of them was being drawn at the key's own time
        --                    as though it happened there.
        --   shortcut_written a link outside a shell-maintained folder. The file
        --                    was written then; a user may have made, edited,
        --                    pinned or copied it rather than opened anything.
        CASE
             WHEN a.artefact = 'user_assist' THEN 'program_launched'
             WHEN a.recorded_basis = 'not_after_bound'
                  THEN CASE WHEN a.artefact = 'mru' THEN 'file_listed_no_later_than'
                            ELSE 'record_no_later_than' END
             WHEN a.artefact = 'shell_bag'   THEN 'shell_bag_key_written'
             WHEN a.artefact = 'mru'         THEN 'mru_key_written'
             WHEN a.recorded_basis = 'target_metadata'
                                             THEN 'target_file_written'
             WHEN a.recorded_basis = 'link_written'
                                             THEN 'shortcut_written'
             WHEN a.artefact IN ('shell_link', 'jump_list')
                                             THEN 'file_opened'
             ELSE 'file_listed' END,
        a.recorded_meaning,
        a.recorded_utc, '',
        CASE WHEN f.best_candidates = 1 THEN f.device_key ELSE '' END,
        a.drive_letter, a.path, a.profile,
        coalesce(f.confidence, 'unattributed'),
        a.artefact,
        -- A named device that beat other candidates says so. The row is a
        -- judgement between routes, and a reader deciding what to do with it
        -- needs to know one was made.
        a.detail || CASE
            WHEN f.best_candidates > 1
                THEN '; ' || f.best_candidates || ' devices reached with equal '
                  || 'confidence, so none is named'
            WHEN f.candidates > 1
                THEN '; ' || f.candidates || ' candidate devices, and this is '
                  || 'the one the strongest route reached'
            ELSE '' END,
        CAST(NULL AS UBIGINT), a.source_id, a.source_file
    FROM v_file_activity a
    LEFT JOIN attributed f USING (activity_id)
    -- Prefetch is excluded and handled by the arm below. Its row here carries
    -- only the most recent execution, and a timeline that showed one execution
    -- of a programme Windows recorded eight of would be quietly incomplete.
    WHERE a.recorded_utc IS NOT NULL AND a.artefact <> 'prefetch'

    UNION ALL

    -- Programme executions, every recorded slot.
    --
    -- The device and the confidence come from the attribution of the prefetch
    -- file as a whole, because that is what was attributed: the volume the
    -- executable ran from does not change between slot one and slot eight.
    --
    -- The detail states the run count beside the number of slots on every row.
    -- Windows keeps the last eight executions and overwrites the rest, so a
    -- programme run four hundred times shows two timeline entries, and an
    -- analyst reading the gap as "it only ran twice" would be wrong.
    SELECT
        'execution', 'program_executed',
        CASE WHEN x.slot = 1
             THEN 'the most recent execution of this programme Windows recorded'
             ELSE 'an earlier execution of this programme Windows still records'
        END,
        x.time_utc, '',
        CASE WHEN f.best_candidates = 1 THEN f.device_key ELSE '' END,
        '',
        -- The same reading as the file activity arm: executable_path is the
        -- package identity rather than a location for a packaged application,
        -- and the path column has to hold a place or a name, not both.
        CASE WHEN starts_with(r.executable_path, '\') THEN r.executable_path
             ELSE r.executable END,
        '',
        coalesce(f.confidence, 'unattributed'),
        'prefetch',
        'slot ' || x.slot || ' of ' || r.times_recorded
            || ' recorded; Windows counts ' || r.run_count
            || ' execution(s) of this programme in total'
            || CASE
                    WHEN f.best_candidates > 1
                        THEN '; ' || f.best_candidates || ' devices reached '
                          || 'with equal confidence, so none is named'
                    WHEN f.candidates > 1
                        THEN '; ' || f.candidates || ' candidate devices, and '
                          || 'this is the one the strongest route reached'
                    ELSE '' END,
        CAST(NULL AS UBIGINT), x.source_id, x.source_file
    FROM prefetch_execution x
    JOIN prefetch_run r ON r.source_file = x.source_file
    LEFT JOIN v_file_activity a
           ON a.artefact = 'prefetch' AND a.source_file = x.source_file
    LEFT JOIN attributed f ON f.activity_id = a.activity_id
    WHERE x.time_utc IS NOT NULL

    UNION ALL

    -- The FAT timestamps shell items carry. These are the wall clock the
    -- recording machine displayed, and on a removable volume they can be the
    -- only surviving record that a file existed at all.
    SELECT
        'file', 'shell_item_modified',
        'the modified time the shell item stored, recorded as local wall clock '
            || 'with no zone',
        CAST(NULL AS TIMESTAMP), b.modified_local, '',
        b.drive_letter, b.path, b.profile, 'unattributed', 'shell_bag',
        -- The key goes in the detail and the hive file in source_path. They
        -- were the other way round, which left the row naming a registry path
        -- under a heading that means "the file this was read from" — so a bag
        -- row and an event row put different kinds of thing in one column.
        b.hive || ' bag, depth ' || b.depth
            || coalesce(' · ' || nullif(b.registry_path, ''), ''),
        CAST(NULL AS UBIGINT), b.source_id, coalesce(sb.path, '')
    FROM shell_bag b
    LEFT JOIN source sb ON sb.id = b.source_id
    WHERE b.modified_local <> '' AND b.path <> ''

    UNION ALL

    SELECT
        'file', 'shell_item_modified',
        'the modified time the shell item stored, recorded as local wall clock '
            || 'with no zone',
        CAST(NULL AS TIMESTAMP), m.modified_local, '',
        m.drive_letter, coalesce(nullif(m.path, ''), m.name), m.profile,
        'unattributed', 'mru',
        m.source_list || coalesce(' · ' || nullif(m.registry_path, ''), ''),
        CAST(NULL AS UBIGINT), m.source_id, coalesce(sm.path, '')
    FROM mru_entry m
    LEFT JOIN source sm ON sm.id = m.source_id
    WHERE m.modified_local <> ''

    UNION ALL

    SELECT
        'file', 'shell_item_modified',
        'the modified time the link''s own shell item stored, recorded as '
            || 'local wall clock with no zone',
        CAST(NULL AS TIMESTAMP), t.target_item_modified_local, '',
        t.drive_letter, coalesce(nullif(t.target_item_path, ''), t.path),
        t.profile, 'unattributed', t.origin,
        CASE WHEN t.origin = 'jump_list' AND t.app_id <> ''
             THEN 'app ' || t.app_id ELSE '' END,
        CAST(NULL AS UBIGINT), t.source_id, t.source_file
    FROM file_target t
    WHERE t.target_item_modified_local <> ''

    UNION ALL

    -- Mount point keys. The write dates the mapping, not the device: a letter
    -- is reused, and this says when the current mapping was last changed.
    SELECT
        'volume', 'mount_point_written',
        'when the mount point key was last written, which dates the most recent '
            || 'change to this mapping and not any use of the volume',
        p.key_last_write_utc, '', '', p.drive_letter, '', p.profile,
        'confirmed', 'registry_mount_points',
        p.kind || coalesce(' ' || nullif(p.volume_guid, ''), '')
               || coalesce(' ' || nullif(p.remote_path, ''), '')
               || coalesce(' · ' || nullif(p.registry_path, ''), ''),
        CAST(NULL AS UBIGINT), p.source_id, coalesce(sp.path, '')
    FROM mount_point p
    LEFT JOIN source sp ON sp.id = p.source_id
    WHERE p.key_last_write_utc IS NOT NULL

    UNION ALL

    -- The collector reading a disk layout. It dates the collection rather than
    -- anything the device did, which is what makes it worth having on the
    -- timeline: it is the right-hand edge of what the evidence can show.
    SELECT
        'disk', 'disk_layout_recorded',
        'when the collector read this disk layout, which dates the collection '
            || 'and not the device',
        d.time_utc, '', d.device_key, '', '', '', 'confirmed', 'disk_layout',
        'disk ' || d.disk_number || coalesce(' ' || nullif(d.model, ''), '')
            || coalesce(' (' || nullif(d.style, '') || ')', ''),
        d.record_id, d.source_id, coalesce(d.source_path, '')
    FROM v_disk d
    WHERE d.time_utc IS NOT NULL
),
zone AS (SELECT * FROM v_host_time_zone LIMIT 1),
resolved AS (
    SELECT
        e.*,
        -- A wall clock is converted here, in one place, using the host biases
        -- the registry recorded. With no time zone there is no reading and the
        -- column stays NULL, because a fabricated instant is worse than none.
        --
        -- A wall clock sitting on a format's zero or an unset device clock is
        -- not converted at all. It is a placeholder rather than a reading, so
        -- there is no instant to derive and offsetting it only moves the
        -- placeholder somewhere less recognisable. The row keeps the value as
        -- the artefact wrote it, in time_local, and epoch_default names it.
        CASE WHEN e.time_utc IS NOT NULL THEN e.time_utc
             WHEN epoch_default_local(local_timestamp(e.time_local)) <> ''
                  THEN NULL
             WHEN z.standard_offset_minutes IS NULL THEN NULL
             ELSE local_timestamp(e.time_local)
                  + to_minutes(z.standard_offset_minutes) END AS resolved_utc,
        -- The other seasonal reading. The record does not say whether daylight
        -- saving was in force when it was written, so both are offered. A
        -- placeholder has no seasons either.
        CASE WHEN e.time_utc IS NULL AND z.observes_daylight_saving
                  AND epoch_default_local(local_timestamp(e.time_local)) = ''
             THEN local_timestamp(e.time_local)
                  + to_minutes(z.daylight_offset_minutes) END AS resolved_utc_alt,
        CASE WHEN e.time_utc IS NOT NULL THEN 'recorded_utc'
             WHEN epoch_default_local(local_timestamp(e.time_local)) <> ''
                  THEN 'local_wall_clock, a default no clock ever left'
             WHEN z.standard_offset_minutes IS NULL
                  THEN 'local_wall_clock, no host time zone recovered'
             WHEN z.observes_daylight_saving THEN 'standard_time / daylight_time'
             ELSE 'standard_time' END AS resolved_basis
    FROM entry e
    LEFT JOIN zone z ON true
)
SELECT
    -- The ordering has to be total, for the reason activity_id had to be: a
    -- row_number over a tie may number the tied rows either way round on each
    -- evaluation, and entry_id is what a case note cites. Time, category,
    -- event, device and path leave ties — on USB-LENOVO-Multi-USBs a jump list
    -- entry and a shell link share a wall clock and a path and swapped ids 775
    -- and 776 between two runs of one binary. A citation that names a different
    -- row on a rerun is worse than no citation.
    --
    -- Every column the view exposes is in the key. Two rows still tied after
    -- that are identical in everything a reader can see, so which takes which
    -- id cannot be observed.
    row_number() OVER (ORDER BY
        coalesce(r.resolved_utc, local_timestamp(r.time_local)) NULLS LAST,
        r.category, r.event, r.device_key, r.path,
        r.resolved_utc NULLS LAST, r.resolved_utc_alt NULLS LAST,
        r.time_local, r.resolved_basis, r.meaning, r.drive_letter,
        r.profile, r.confidence, r.artefact, r.detail,
        r.record_id NULLS LAST, r.source_id, r.source_path) AS entry_id,
    -- Where a wall clock could not be converted the row is still placed by
    -- reading it as though it were UTC, because dropping it to the end of the
    -- timeline hides it. time_basis on the row says that is what happened.
    coalesce(r.resolved_utc, local_timestamp(r.time_local)) AS sort_utc,
    r.resolved_utc                        AS time_utc,
    r.resolved_utc_alt                    AS time_utc_alt,
    r.time_local,
    r.resolved_basis                      AS time_basis,
    (r.resolved_utc_alt IS NOT NULL)      AS time_ambiguous,
    -- Named where the time this row is placed by is a format's zero rather than
    -- a moment. Empty otherwise, so the column reads as the absence it is.
    --
    -- The row stays on the timeline. It is a real record with an unusable time,
    -- and dropping it would lose the record to fix the date; what it must not
    -- do is set the edge of the evidence span, which is a claim about when the
    -- case begins and ends.
    -- Each kind of time is asked in its own terms. A recorded instant goes to
    -- epoch_default_name, whose fourteen-hour window covers whatever offset a
    -- device applied before storing it. A wall clock goes to
    -- epoch_default_local, which reads the value as written and so matches the
    -- date exactly — and which has already stopped the conversion above, so
    -- coalescing on resolved_utc would find nothing here.
    CASE WHEN r.time_utc IS NOT NULL THEN epoch_default_name(r.time_utc)
         ELSE coalesce(
             nullif(epoch_default_local(local_timestamp(r.time_local)), ''),
             epoch_default_name(r.resolved_utc)) END AS epoch_default,
    r.category,
    r.event,
    r.meaning,
    r.device_key,
    coalesce(g.physical_device_id, '')    AS physical_device_id,
    coalesce(n.device_label, '')          AS device_label,
    r.drive_letter,
    r.path,
    r.profile,
    r.confidence,
    r.artefact,
    r.detail,
    r.record_id,
    r.source_id,
    -- A source with no path is a source the ledger never saw. It is coalesced
    -- so a NULL never reaches the CSV, where an empty field and a missing one
    -- would look the same to a reader.
    coalesce(r.source_path, '') AS source_path
FROM resolved r
LEFT JOIN v_device_group g ON g.device_key = r.device_key
LEFT JOIN v_device_label n ON n.physical_device_id = g.physical_device_id
ORDER BY sort_utc NULLS LAST, r.category, r.event, entry_id;

-- The timeline an analyst reads first: entries belonging to a device the
-- classification put in tier 1 or tier 2, plus every file record that reached a
-- device at all.
--
-- Nothing is deleted by this view. It is the full timeline with a filter on it,
-- and v_timeline is exported beside it, so narrowing the question never means
-- losing the answer to the wider one.
CREATE VIEW v_timeline_significant AS
SELECT t.*, c.category AS device_category, c.tier, c.score
FROM v_timeline t
JOIN v_device_classification c
  ON c.physical_device_id = t.physical_device_id
WHERE c.tier <= 2
ORDER BY t.sort_utc NULLS LAST, t.category, t.event, t.entry_id;

-- ---- timeline moments ------------------------------------------------------
--
-- One arrival is recorded many times over, and the timeline listed every record
-- separately. On USB-LENOVO-Multi-USBs, GEN32GBF32 arriving at 2026-08-04
-- 02:07:06 put twenty-nine rows on the page — at twenty distinct instants inside
-- sixty milliseconds, which the page then rendered as one repeated second, so
-- they read as duplicates of one another when they are not.
--
-- Twenty-four of the twenty-nine are one claim repeated per devnode: four
-- registry lifecycle values and two Kernel-PnP records, each recorded against
-- USB, USBSTOR, STORAGE\Volume and SWD\WPDBUSENUM. The standing rule is
-- physical devices, not devnodes, and the grouping honours it everywhere else;
-- the timeline was unrolling the group back out one record at a time. The
-- remaining five each say something the others do not — the StorageVolume
-- mount, the setupapi install section, the partition driver's inventory, the
-- disk layout and PnP 430.
--
-- So the records that evidence a connection are gathered under the connection
-- they evidence, and the report states the conclusion with the records folded
-- beneath it. Nothing is dropped and nothing is decided in Go: every record is
-- still in timeline.csv under its own id, the membership is exported beside it,
-- and the fold is a checkbox the print stylesheet forces open.
--
-- Two things bound what a moment is allowed to absorb.
--
-- It is anchored on a connection window rather than on a clock bucket.
-- v_connection has already decided which records constitute one arrival,
-- against a tolerance calibrated on real evidence, and a second independent
-- bucket here would be a second number to defend — with the first already the
-- thinnest calibration in this file. The same fifteen seconds is reused. It is
-- not load-bearing at this level: on the reference collection a tolerance of
-- one second gathers 134 records and thirty seconds gathers 152, because the
-- records genuinely arrive together. That flatness is why reusing the number is
-- safe here and why choosing a new one would have been arbitrary.
--
-- And a moment absorbs only what evidences the connection itself, never what
-- evidences use of the device. A file opened in the second a stick was plugged
-- in is the finding an analyst came for, and folding it into "device connected"
-- would bury the one row on the page that matters. The categories are listed
-- affirmatively rather than excluded, so a category added later sits outside a
-- moment until somebody decides otherwise — the safe direction, because the
-- cost of leaving a record on the page is a longer list and the cost of
-- absorbing the wrong one is a finding nobody sees.

-- The endpoints a moment can be anchored on: an arrival, and a removal.
--
-- Keyed on the physical device rather than on the devnode the window was
-- recorded against. The records being gathered are spread across every devnode
-- the device enumerates under, and the window is recorded against one of them,
-- so joining on the devnode would gather a quarter of them and leave the rest
-- on the page looking exactly as they do now.
CREATE VIEW v_connection_endpoint AS
SELECT g.physical_device_id,
       'arrival'      AS moment_kind,
       c.started_utc  AS moment_utc,
       c.device_key,
       c.opened_by    AS moment_rule
FROM v_connection c
JOIN v_device_group g USING (device_key)
WHERE c.started_utc IS NOT NULL AND c.start_known
UNION ALL
SELECT g.physical_device_id, 'removal', c.ended_utc, c.device_key, c.closed_by
FROM v_connection c
JOIN v_device_group g USING (device_key)
WHERE c.ended_utc IS NOT NULL;

-- One anchor per arrival or removal of a physical device.
--
-- Endpoints are clustered before they are used, with the same tolerance and for
-- the same reason v_connection clusters state changes: two devnodes of one
-- device can each carry a window, and two anchors a few milliseconds apart
-- would split one arrival's records into two folds that both claim to be the
-- arrival. No reference collection shows that shape — every window on all five
-- is recorded against the USBSTOR key alone — which is exactly why it is worth
-- handling here rather than discovering later on a host that does.
CREATE VIEW v_timeline_moment_anchor AS
WITH ordered AS (
    SELECT *, lag(moment_utc) OVER w AS previous_utc
    FROM v_connection_endpoint
    WINDOW w AS (PARTITION BY physical_device_id, moment_kind
                 ORDER BY moment_utc, device_key)
),
clustered AS (
    SELECT *,
           sum(CASE WHEN previous_utc IS NULL
                     OR date_diff('millisecond', previous_utc, moment_utc) > 15000
                    THEN 1 ELSE 0 END) OVER (
               PARTITION BY physical_device_id, moment_kind
               ORDER BY moment_utc, device_key
               ROWS UNBOUNDED PRECEDING) AS cluster_index
    FROM ordered
)
SELECT
    row_number() OVER (ORDER BY physical_device_id, moment_kind, cluster_index)
                                          AS moment_id,
    physical_device_id,
    moment_kind,
    min(moment_utc)                       AS moment_utc,
    count(*)                              AS window_count,
    string_agg(DISTINCT moment_rule, '; ' ORDER BY moment_rule) AS moment_rules
FROM clustered
GROUP BY physical_device_id, moment_kind, cluster_index;

-- Which timeline entry belongs to which moment.
--
-- A record within the tolerance of two anchors — a device connected and removed
-- inside fifteen seconds — goes to the nearer, and to the lower moment id where
-- it is equidistant. The tie-break is arbitrary and is written down rather than
-- left to the plan, because a record that changed folds between two runs would
-- change the report's own hash.
--
-- A record whose time is a format's zero is never gathered. Its distance from
-- an anchor is a distance from a placeholder, and proximity is the whole of the
-- evidence for membership here.
CREATE VIEW v_timeline_moment_member_computed AS
WITH candidate AS (
    SELECT t.entry_id,
           a.moment_id,
           abs(date_diff('millisecond', a.moment_utc, t.sort_utc)) AS distance_ms
    FROM v_timeline t
    JOIN v_timeline_moment_anchor a
      ON a.physical_device_id = t.physical_device_id
    WHERE t.sort_utc IS NOT NULL
      AND t.physical_device_id <> ''
      AND t.epoch_default = ''
      AND t.category IN ('connection', 'device', 'device_state', 'install', 'disk')
      AND abs(date_diff('millisecond', a.moment_utc, t.sort_utc)) <= 15000
),
nearest AS (
    SELECT entry_id, moment_id, distance_ms,
           row_number() OVER (PARTITION BY entry_id
                              ORDER BY distance_ms, moment_id) AS choice
    FROM candidate
)
SELECT entry_id, moment_id, distance_ms
FROM nearest
WHERE choice = 1;

-- What everything downstream reads, filled by the consolidation step.
--
-- entry_id is unique here — a record belongs to at most one moment — so the
-- order is total and the exported file is the same bytes every run.
CREATE VIEW v_timeline_moment_member AS
SELECT entry_id, moment_id, distance_ms
FROM timeline_moment_member
ORDER BY moment_id, entry_id;

-- What each moment rests on, one row per kind of record it gathered. Exported
-- as its own file: a summary that says "29 records" and cannot be broken down
-- is a number an analyst has to take on trust.
CREATE VIEW v_timeline_moment_support AS
SELECT m.moment_id,
       t.category,
       t.event,
       count(*)                      AS records,
       -- Identities rather than devnodes, and the distinction is not pedantry:
       -- this stick's four registry keys — USB, USBSTOR, STORAGE\Volume and
       -- SWD\WPDBUSENUM — normalise to two device identities, so a row saying
       -- "across 4 devnodes" and a row saying "across 2" would both be true of
       -- the same records and neither would say which was being counted.
       -- device-identities.csv is the file this number can be checked against.
       count(DISTINCT t.device_key)  AS identities,
       string_agg(DISTINCT t.artefact, ', ' ORDER BY t.artefact) AS artefacts
FROM v_timeline_moment_member m
JOIN v_timeline t USING (entry_id)
GROUP BY m.moment_id, t.category, t.event
ORDER BY m.moment_id, t.category, t.event;

-- The moment as one row.
--
-- A moment needs two records before it is worth making. Replacing a single
-- record with a summary of that record plus a fold to open is strictly worse
-- than leaving the record where it was, and the HAVING is what keeps every
-- connection on a quiet host reading exactly as it did.
CREATE VIEW v_timeline_moment AS
WITH member AS (
    SELECT m.moment_id, m.distance_ms, t.*
    FROM v_timeline_moment_member m
    JOIN v_timeline t USING (entry_id)
),
support AS (
    SELECT moment_id,
           string_agg(
               records || ' ' || event
                       || CASE WHEN identities > 1
                               THEN ' across ' || identities || ' identities'
                               ELSE '' END,
               '; ' ORDER BY records DESC, event) AS supporting
    FROM v_timeline_moment_support
    GROUP BY moment_id
)
SELECT
    a.moment_id,
    a.physical_device_id,
    a.moment_kind,
    a.moment_utc,
    a.moment_rules,
    -- The moment takes the identity of its earliest record, so a citation to it
    -- lands on a row that exists in timeline.csv.
    min(x.entry_id)                        AS entry_id,
    count(*)                               AS member_count,
    count(DISTINCT x.device_key)           AS identity_count,
    count(DISTINCT x.source_id)            AS source_count,
    max(x.device_label)                    AS device_label,
    s.supporting,
    -- Promoted out of the fold, because "this is the first time this device was
    -- seen on this host" is the sort of thing a reader must not have to open a
    -- disclosure to find.
    bool_or(x.event = 'first_install_date') AS first_install_recorded,
    bool_or(x.artefact = 'setupapi_log')    AS setupapi_recorded,
    -- The window's own source, so the summary line cites the record that opened
    -- or closed it rather than whichever member happened to sort first.
    coalesce(arg_min(x.source_id, x.entry_id)
                 FILTER (WHERE x.category = 'connection'),
             arg_min(x.source_id, x.entry_id))   AS source_id,
    coalesce(arg_min(x.source_path, x.entry_id)
                 FILTER (WHERE x.category = 'connection'),
             arg_min(x.source_path, x.entry_id)) AS source_path
FROM v_timeline_moment_anchor a
JOIN member x USING (moment_id)
LEFT JOIN support s USING (moment_id)
GROUP BY a.moment_id, a.physical_device_id, a.moment_kind, a.moment_utc,
         a.moment_rules, s.supporting
HAVING count(*) >= 2
ORDER BY a.moment_id;

-- The timeline the report renders: every entry that no moment gathered, and one
-- row for each moment that gathered any.
--
-- Merged here rather than in Go. Go may group rows into cards and chips, but
-- the order two kinds of row appear in among each other is a statement about
-- the evidence, and a statement about the evidence is a view.
CREATE VIEW v_report_timeline AS
SELECT
    'moment'                     AS row_kind,
    m.moment_id,
    m.entry_id,
    m.moment_utc                 AS sort_utc,
    -- A connection endpoint comes from an event log record, so it is a recorded
    -- UTC instant and never a converted wall clock. Stated rather than carried
    -- from a member, whose time may be either.
    m.moment_utc                 AS time_utc,
    CAST(NULL AS TIMESTAMP)      AS time_utc_alt,
    ''                           AS time_local,
    'recorded_utc'               AS time_basis,
    false                        AS time_ambiguous,
    ''                           AS epoch_default,
    'connection'                 AS category,
    CASE m.moment_kind WHEN 'arrival' THEN 'device_connected'
                       ELSE 'device_removed' END AS event,
    CASE m.moment_kind
         WHEN 'arrival' THEN 'this device was connected to the machine'
         ELSE 'this device was removed from the machine' END
      || ', and ' || m.member_count || ' records evidence it'
      || CASE WHEN m.identity_count > 1
              THEN ', across ' || m.identity_count
                   || ' of the identities this device enumerates under'
              ELSE '' END
                                 AS meaning,
    ''                           AS device_key,
    m.physical_device_id,
    m.device_label,
    ''                           AS drive_letter,
    ''                           AS path,
    ''                           AS profile,
    'confirmed'                  AS confidence,
    'connection_window'          AS artefact,
    'opened by ' || m.moment_rules AS detail,
    m.source_id,
    m.source_path,
    m.member_count,
    m.supporting,
    -- Claimed on an arrival only. A device removed and re-plugged inside the
    -- tolerance — SAN64FAT32 on USB-LENOVO-Multi-USBs goes out at 11:37:16 and
    -- comes back at 11:37:17 — puts its install records a second from both
    -- anchors, and the nearer of the two can be the removal. Which moment
    -- gathered the record is then close to arbitrary and saying so is fine;
    -- "this is the first time the device was seen on this host" printed against
    -- a removal is not, because it reads as a claim about the removal.
    m.first_install_recorded AND m.moment_kind = 'arrival'
                                 AS first_install_recorded,
    c.tier
FROM v_timeline_moment m
JOIN v_device_classification c ON c.physical_device_id = m.physical_device_id
WHERE c.tier <= 2

UNION ALL

SELECT
    'entry', 0, t.entry_id, t.sort_utc, t.time_utc, t.time_utc_alt,
    t.time_local, t.time_basis, t.time_ambiguous, t.epoch_default,
    t.category, t.event, t.meaning, t.device_key, t.physical_device_id,
    t.device_label, t.drive_letter, t.path, t.profile, t.confidence,
    t.artefact, t.detail, t.source_id, t.source_path,
    0, '', false, t.tier
FROM v_timeline_significant t
LEFT JOIN v_timeline_moment_member m ON m.entry_id = t.entry_id
LEFT JOIN v_timeline_moment g       ON g.moment_id = m.moment_id
WHERE g.moment_id IS NULL
ORDER BY sort_utc NULLS LAST, entry_id, row_kind;

-- The records inside one moment's fold, in the order they happened.
CREATE VIEW v_report_timeline_member AS
-- The moment is tested for with IN rather than joined to: it carries an
-- entry_id of its own — the identity it took from its earliest record — and
-- joining it here would put two different entry_ids in scope under one name.
SELECT m.moment_id, m.distance_ms, t.*
FROM v_timeline_moment_member m
JOIN v_timeline t ON t.entry_id = m.entry_id
WHERE m.moment_id IN (SELECT moment_id FROM v_timeline_moment)
ORDER BY m.moment_id, t.sort_utc NULLS LAST, t.entry_id;

-- ---- the report ------------------------------------------------------------
--
-- The report is a document rather than a data file, so Go renders it. What it
-- must not do is work anything out: every figure and every sentence below is a
-- view, read by the renderer the same way the console summary reads one, so a
-- number in the prose and a number in a CSV cannot disagree.

-- The headline counts, as one row.
--
-- The tier counts come from one pass with FILTER rather than five subqueries
-- over the same view. Asked separately they cost five evaluations of the
-- classification, which is two seconds of a run for five numbers that one scan
-- produces.
CREATE VIEW v_report_summary AS
WITH device AS MATERIALIZED (
    SELECT tier, review_required FROM v_device_classified
),
tiers AS (
    SELECT count(*)                                  AS devices,
           count(*) FILTER (WHERE tier = 1)          AS tier_1,
           count(*) FILTER (WHERE tier = 2)          AS tier_2,
           count(*) FILTER (WHERE tier = 3)          AS tier_3,
           count(*) FILTER (WHERE review_required)   AS review_required
    FROM device
)
SELECT
    t.devices,
    t.tier_1,
    t.tier_2,
    t.tier_3,
    t.review_required,
    (SELECT count(*) FROM v_device)                                  AS identities,
    (SELECT count(*) FROM v_connection)                              AS connections,
    (SELECT count(*) FROM v_file_activity)                           AS file_records,
    (SELECT count(DISTINCT activity_id) FROM v_file_attribution)     AS attributed_records,
    (SELECT count(*) FROM v_removable_volume)                        AS removable_volumes,
    (SELECT count(*) FROM v_timeline)                                AS timeline_entries,
    -- How much of the timeline is placed by conversion rather than by a
    -- recorded instant. It qualifies every time in the report.
    (SELECT count(*) FROM v_timeline WHERE time_basis <> 'recorded_utc')
                                                                     AS wall_clock_entries,
    -- Of those, the ones with two readings an hour apart, because the host
    -- observes daylight saving and the record does not say which season it was
    -- written in. Counted apart from the wall clock total: on a host that keeps
    -- one offset all year there are none, and a report that said so anyway
    -- would be describing a difficulty it does not have.
    (SELECT count(*) FROM v_timeline WHERE time_ambiguous)           AS ambiguous_entries,
    -- Entries placed by a format's zero rather than by a recorded moment. They
    -- are counted so the report can say they were set aside, and excluded from
    -- the span below, which is the number they were corrupting: one shortcut
    -- carrying the FAT epoch dragged a whole case's reported start back to 1979.
    (SELECT count(*) FROM v_timeline WHERE epoch_default <> '')
                                                                     AS epoch_default_entries,
    (SELECT min(sort_utc) FROM v_timeline WHERE epoch_default = '')  AS earliest_utc,
    (SELECT max(sort_utc) FROM v_timeline WHERE epoch_default = '')  AS latest_utc,
    -- The host's own starts and stops. These qualify every silence in the
    -- report: an hour with no records is a quiet hour or an hour switched off,
    -- and a connection that never closed is a stick pulled out unrecorded or a
    -- machine shut down with it still in the port. A reader cannot tell which
    -- without knowing whether the session evidence is there at all, so the
    -- count is stated even when it is zero.
    (SELECT count(*) FROM v_session_event WHERE state = 'started')   AS host_starts,
    (SELECT count(*) FROM v_session_event
      WHERE state IN ('stopped', 'stopped_unexpectedly'))            AS host_stops,
    (SELECT count(*) FROM v_session_event
      WHERE state = 'stopped_unexpectedly')                          AS host_stops_unexpected,
    -- Open windows a shutdown explains, which is the finding the session
    -- records were read for.
    (SELECT count(*) FROM v_connection
      WHERE host_stopped_utc IS NOT NULL
         OR host_stopped_after_utc IS NOT NULL)
                                                                     AS connections_ended_by_shutdown,
    (SELECT count(*) FROM v_source)                                  AS sources,
    (SELECT count(*) FROM v_warning WHERE severity = 'failed')       AS failed_sources,
    (SELECT count(*) FROM v_warning WHERE severity = 'absent')       AS absent_artefacts
FROM tiers t;

-- The headline findings, in sentences, with what each rests on.
--
-- They are derived here and not written in Go so that a finding can be checked
-- against the evidence: basis names the view a reader can open to argue with
-- it. A finding with no rows behind it does not appear at all — a report should
-- not say "0 storage devices were found" in the place its answers go.
CREATE VIEW v_report_finding AS
WITH
-- Materialised because five branches below read it, and each read is a full
-- evaluation of the grouping, the facts and the rules otherwise.
device AS MATERIALIZED (SELECT * FROM v_device_classified),
attribution AS MATERIALIZED (SELECT * FROM v_file_attribution_summary),
finding AS (

    SELECT 1 AS rank, 'storage' AS kind,
        count(*) || ' storage device' || CASE WHEN count(*) = 1 THEN '' ELSE 's' END
            || ' ' || CASE WHEN count(*) = 1 THEN 'was' ELSE 'were' END
            || ' attached to this host'                             AS headline,
        -- One device per line, and the renderer gives each its own row. A
        -- semicolon-joined paragraph of four devices was four lines of prose
        -- that had to be read to be counted. The separator is a newline
        -- because no field joined here can contain one, so the split back into
        -- rows cannot cut a device name in half.
        string_agg(coalesce(nullif(friendly_name, ''),
                            nullif(device_desc, ''), physical_device_id)
                   || CASE WHEN serial <> '' THEN ' (serial ' || serial || ')'
                           ELSE ' (no serial recorded)' END,
                   chr(10) ORDER BY physical_device_id)             AS detail,
        'devices.csv, category Storage'                             AS basis
    FROM device
    WHERE category = 'Storage' AND tier = 1
    HAVING count(*) > 0

    UNION ALL

    -- The one finding that outranks the storage inventory. A device presenting
    -- a keyboard alongside storage or networking is the shape of a
    -- keystroke-injection tool, and it belongs at the top of the page.
    SELECT 0, 'offensive',
        count(*) || ' device' || CASE WHEN count(*) = 1 THEN '' ELSE 's' END
            || ' present' || CASE WHEN count(*) = 1 THEN 's' ELSE '' END
            || ' interfaces that do not match '
            || CASE WHEN count(*) = 1 THEN 'its' ELSE 'their' END
            || ' apparent purpose',
        string_agg(coalesce(nullif(friendly_name, ''), physical_device_id)
                   || ' — ' || classification_reason,
                   chr(10) ORDER BY physical_device_id),
        'devices.csv, category PotentialOffensiveDevice'
    FROM device
    WHERE category = 'PotentialOffensiveDevice'
    HAVING count(*) > 0

    UNION ALL

    -- A programme run off a removable volume. It sits above the storage
    -- inventory's neighbours because it is a different kind of claim: the other
    -- findings say a device was present and files were recorded against it,
    -- and this one says code on it was executed.
    --
    -- The headline names programmes and devices and does not say who ran them.
    -- A prefetch file is written by the loader, and a scheduled task and a
    -- double-click produce the same record.
    SELECT 1, 'execution',
        count(DISTINCT p.executable) || ' programme'
            || CASE WHEN count(DISTINCT p.executable) = 1 THEN '' ELSE 's' END
            || ' ran from a volume carried by '
            || count(DISTINCT p.device_key) || ' removable device'
            || CASE WHEN count(DISTINCT p.device_key) = 1 THEN '' ELSE 's' END,
        string_agg(DISTINCT p.executable || ' (' || p.drive_letter || ':)',
                   chr(10)
                   ORDER BY p.executable || ' (' || p.drive_letter || ':)')
            || chr(10)
            || 'prefetch records that a programme ran, not that a person ran '
            || 'it, and Windows keeps only the last eight executions of each.',
        'prefetch-runs.csv, ran_from_removable'
    FROM v_prefetch_device_link p
    WHERE p.ran_from
    HAVING count(*) > 0

    UNION ALL

    -- What a user launched from a drive letter, from the shell's own record.
    --
    -- A separate finding from the prefetch one above and a stronger kind of
    -- claim: prefetch says a programme ran, this says a person started it, and
    -- it counts how long they had it in front of them. On USB-CTF it is the
    -- only thing that reports `F:\KAPE\gkape.exe` at all — a forensic tool
    -- launched twice from a drive letter, with 83 seconds of foreground focus.
    --
    -- Every launch that names a letter is listed rather than only those that
    -- reached a device. The letter is often all there is: UserAssist records no
    -- serial and no label, and on that collection nothing in the evidence maps
    -- F: to anything. Withholding the row until a device could be named would
    -- have suppressed the most useful execution finding in the case, which is
    -- the failure this project was written to avoid.
    SELECT 1, 'user_launched',
        count(*) || ' programme'
            || CASE WHEN count(*) = 1 THEN ' was' ELSE 's were' END
            || ' launched from a drive letter by a user',
        string_agg(
            u.drive_letter || ':  ' || u.name
                || CASE WHEN u.run_count > 0
                        THEN ' — launched ' || u.run_count || ' time(s)'
                        ELSE ' — no launch recorded' END
                || CASE WHEN u.focus_count > 0
                        THEN ', in the foreground for '
                             || round(u.focus_seconds, 1) || 's'
                        ELSE '' END,
            chr(10) ORDER BY u.drive_letter, u.name)
            || chr(10)
            || 'UserAssist is per user and records what the shell started, so '
            || 'unlike prefetch it evidences a person rather than a process. It '
            || 'records no volume serial and no label, so the drive letter is '
            || 'the only route it offers to a device.',
        'user-assist.csv, drive_letter'
    FROM user_assist u
    WHERE NOT u.bookkeeping AND u.drive_letter <> ''
    HAVING count(*) > 0

    UNION ALL

    -- The weaker neighbour of the finding above, and a separate claim. A
    -- programme on the system disk that opened one file on a stick reaches the
    -- device through the same chain, and folding the two together would report
    -- it as having run from the device.
    SELECT 1, 'execution_read',
        count(DISTINCT p.executable) || ' programme'
            || CASE WHEN count(DISTINCT p.executable) = 1 THEN '' ELSE 's' END
            || ' read files from a volume carried by '
            || count(DISTINCT p.device_key) || ' removable device'
            || CASE WHEN count(DISTINCT p.device_key) = 1 THEN '' ELSE 's' END,
        string_agg(DISTINCT p.executable || ' (' || p.drive_letter || ':)',
                   chr(10)
                   ORDER BY p.executable || ' (' || p.drive_letter || ':)')
            || chr(10)
            || 'these ran from elsewhere; the prefetch record says the loader '
            || 'touched a file on this volume, not that the programme was on it.',
        'prefetch-files-removable.csv'
    FROM v_prefetch_device_link p
    WHERE NOT p.ran_from
    HAVING count(*) > 0

    UNION ALL

    SELECT 2, 'mobile',
        count(*) || ' mobile device' || CASE WHEN count(*) = 1 THEN '' ELSE 's' END
            || ' ' || CASE WHEN count(*) = 1 THEN 'was' ELSE 'were' END
            || ' attached to this host',
        string_agg(coalesce(nullif(friendly_name, ''),
                            nullif(device_desc, ''), physical_device_id),
                   chr(10) ORDER BY physical_device_id),
        'devices.csv, category MobileDevice'
    FROM device
    WHERE category = 'MobileDevice'
    HAVING count(*) > 0

    UNION ALL

    SELECT 3, 'file_activity',
        count(DISTINCT a.activity_id) || ' file record'
            || CASE WHEN count(DISTINCT a.activity_id) = 1 THEN '' ELSE 's' END
            || ' reached a device, across '
            || count(DISTINCT a.device_key) || ' device'
            || CASE WHEN count(DISTINCT a.device_key) = 1 THEN '' ELSE 's' END,
        'strongest route reached: ' || coalesce(list_extract(
            ['confirmed', 'strong', 'probable', 'possible'],
            min(CASE a.confidence WHEN 'confirmed' THEN 1 WHEN 'strong' THEN 2
                                  WHEN 'probable' THEN 3 ELSE 4 END)), 'none')
            || '. A drive letter is reused, so a letter-based link says which '
            || 'device holds the letter now and not which held it when the file '
            || 'was opened.',
        'file-attribution.csv'
    FROM v_file_attribution a
    HAVING count(*) > 0

    UNION ALL

    -- A gap reported as a gap. Records that reach no device are the part of the
    -- evidence the tool could not answer, and leaving them out would make the
    -- attributed set look complete.
    SELECT 4, 'unattributed',
        count(*) || ' file record'
            || CASE WHEN count(*) = 1 THEN '' ELSE 's' END
            || ' reached no device at all',
        'no USB device is linked to the drive letter these records name, so what '
            || 'they sat on is not established by this evidence',
        'file-attribution-summary.csv, candidate_devices = 0'
    FROM attribution
    WHERE candidate_devices = 0
    HAVING count(*) > 0

    UNION ALL

    SELECT 5, 'contested',
        count(*) || ' file record'
            || CASE WHEN count(*) = 1 THEN '' ELSE 's' END
            || ' reached more than one candidate device',
        'two routes disagree about which device held the volume. That is a '
            || 'question the evidence has not settled rather than an answer to '
            || 'pick between.',
        'file-attribution-summary.csv, candidate_devices > 1'
    FROM attribution
    WHERE candidate_devices > 1
    HAVING count(*) > 0

    UNION ALL

    SELECT 6, 'review',
        count(*) || ' device'
            || CASE WHEN count(*) = 1 THEN '' ELSE 's' END
            || ' ' || CASE WHEN count(*) = 1 THEN 'needs' ELSE 'need' END
            || ' a closer look',
        'review is not a tier: a low-value device with a duplicated serial or a '
            || 'class nothing identified still needs looking at',
        'devices.csv, review_required'
    FROM device
    WHERE review_required
    HAVING count(*) > 0

    UNION ALL

    -- Absence of the arrival records is a fact about the collection, not about
    -- the devices, and an empty timeline with no explanation reads as "nothing
    -- was ever connected".
    SELECT 7, 'no_connections',
        'no connection window could be derived',
        'no arrival or removal record was selected from the event logs, so how '
            || 'long a device was attached is not established. What is known '
            || 'about when each device was present is in its install and '
            || 'lifecycle dates.',
        'connections.csv, empty'
    FROM (SELECT 1) WHERE NOT EXISTS (SELECT 1 FROM v_connection)

    UNION ALL

    SELECT 8, 'identity',
        count(*) || ' device'
            || CASE WHEN count(*) = 1 THEN '' ELSE 's' END
            || ' cannot be told apart from another of the same model',
        'no identity in the group reported a serial, or Windows generated one. '
            || 'Two visits by two identical devices and two visits by one are '
            || 'the same shape in this evidence.',
        'devices.csv, identity_not_unique'
    FROM device
    WHERE identity_not_unique AND tier <= 2
    HAVING count(*) > 0
)
-- Ordered by kind as well as rank: two findings can share a rank where they are
-- two readings of the same evidence, and an order that depends on which arm the
-- planner evaluated first would move them between runs.
SELECT row_number() OVER (ORDER BY rank, kind) AS finding_id,
       rank, kind, headline, coalesce(detail, '') AS detail, basis
FROM finding
ORDER BY rank, kind;

-- What was read, what failed and what was not there. Coverage is a finding in
-- its own right: a report that does not say what it could not see invites its
-- silences to be read as absences of evidence.
CREATE VIEW v_report_coverage AS
SELECT
    s.artefact,
    count(*)                                  AS sources,
    sum(s.size_bytes)                         AS bytes,
    count(*) FILTER (WHERE s.replayed)        AS replayed,
    -- A hive that no transaction-log page reached may be missing its most
    -- recent writes, which is exactly the window an examiner cares about most.
    -- Two different things land here — recovery failing, and recovery running
    -- and changing nothing — and replay_note distinguishes them per hive.
    count(*) FILTER (WHERE s.replayed IS false) AS not_replayed,
    coalesce((SELECT count(*) FROM v_warning w
              WHERE w.artefact = s.artefact AND w.severity = 'failed'), 0) AS failed,
    coalesce((SELECT count(*) FROM v_warning w
              WHERE w.artefact = s.artefact AND w.severity = 'malformed'), 0) AS malformed
FROM v_source s
GROUP BY s.artefact
ORDER BY s.artefact;

-- What the run could not read, and what was not there to read. Kept apart from
-- coverage because "the file was absent" and "the file was there and would not
-- parse" are different claims about the collection.
CREATE VIEW v_report_limitation AS
SELECT severity, artefact, path, message, count(*) OVER () AS total
FROM v_warning
WHERE severity IN ('failed', 'absent', 'malformed', 'truncated', 'partial')
-- message last: one file can fail in several ways, and two warnings on one
-- path are otherwise interchangeable to the sort.
--
-- 'partial' sits above 'absent' because a record that was read only in part is
-- present in the outputs and can be relied on by someone who has not seen this
-- section, where an absent artefact reports nothing to rely on.
ORDER BY CASE severity WHEN 'failed' THEN 0 WHEN 'malformed' THEN 1
                       WHEN 'truncated' THEN 2 WHEN 'partial' THEN 3
                       ELSE 4 END,
         artefact, path, message;

-- A device's programme executions, gathered so they can be read together.
--
-- Prefetch already reached the report through the headline findings, the device
-- facts, the file activity section and the timeline. That is enough to be found
-- and not enough to be read as a body of evidence: an analyst asking "what ran
-- off this stick, when, and what did those programmes touch on it" had to
-- assemble the answer from four places.
--
-- One row per device and prefetch file. ran_from is the distinction the whole
-- section turns on and is kept as a column rather than folded into a count: a
-- programme on the system disk that opened one file on a stick reaches this
-- device through the same chain as one executed off it, and reporting them
-- together would say four programmes ran from a device when one did.
CREATE VIEW v_report_prefetch AS
WITH link AS MATERIALIZED (
    SELECT DISTINCT
        g.physical_device_id,
        p.source_file,
        p.executable,
        p.drive_letter,
        p.volume_label,
        p.volume_serial_hex,
        p.volume_route,
        p.volume_confidence,
        p.letter_contradicted,
        p.ran_from
    FROM v_prefetch_device_link p
    JOIN v_device_group g ON g.device_key = p.device_key
),
-- The executions this file still holds. Windows keeps the last eight and
-- overwrites the rest, so this is a floor on how often the programme ran and
-- run_count is what it counted — the two are reported side by side rather than
-- reconciled, because they answer different questions.
runs AS (
    SELECT source_file,
           count(*)          AS times_recorded,
           min(time_utc)     AS first_run_utc,
           max(time_utc)     AS last_run_utc,
           string_agg(strftime(time_utc, '%Y-%m-%d %H:%M:%S'), chr(10)
                      ORDER BY time_utc DESC) AS execution_times
    FROM prefetch_execution
    WHERE time_utc IS NOT NULL
    GROUP BY source_file
),
-- What each programme loaded from this particular volume. Not from the file
-- list as a whole: a prefetch file names every volume the loader touched, and
-- the question here is what came off *this* device.
loaded AS (
    SELECT source_file, volume_serial_hex,
           count(*) AS files_loaded,
           -- The volume prefix is trimmed: the volume is named in its own
           -- column beside this, so repeating \VOLUME{…} on every line is
           -- noise. The whole path stays in prefetch-files-removable.csv, the
           -- same division the report already makes for source paths.
           string_agg(
               CASE WHEN device_path <> '' AND starts_with(path, device_path)
                    THEN substr(path, length(device_path) + 1)
                    ELSE path END,
               chr(10) ORDER BY path) AS files
    FROM v_prefetch_file_on_removable
    GROUP BY source_file, volume_serial_hex
)
SELECT
    l.physical_device_id,
    coalesce(n.device_label, l.physical_device_id) AS device_label,
    coalesce(c.tier, 3)                            AS tier,
    l.executable,
    l.ran_from,
    r.run_count,
    coalesce(x.times_recorded, 0)                  AS times_recorded,
    x.first_run_utc,
    x.last_run_utc,
    coalesce(x.execution_times, '')                AS execution_times,
    coalesce(f.files_loaded, 0)                    AS files_loaded,
    coalesce(f.files, '')                          AS files,
    l.drive_letter,
    l.volume_label,
    l.volume_serial_hex,
    l.volume_route,
    l.volume_confidence,
    -- The record's own label names a different device than the letter does. The
    -- row is kept and the reader told, because choosing between two disagreeing
    -- routes is the analyst's call.
    l.letter_contradicted,
    r.parse_warnings,
    r.source_id,
    l.source_file,
    coalesce(sp.path, '')                          AS source_path,
    coalesce(sp.sha256, '')                        AS source_sha256
FROM link l
JOIN prefetch_run r ON r.source_file = l.source_file
LEFT JOIN runs x   ON x.source_file = l.source_file
LEFT JOIN loaded f ON f.source_file = l.source_file
                  AND f.volume_serial_hex = l.volume_serial_hex
LEFT JOIN v_device_label n ON n.physical_device_id = l.physical_device_id
LEFT JOIN v_device_classification c
       ON c.physical_device_id = l.physical_device_id
LEFT JOIN source sp ON sp.id = r.source_id
-- Ran-from first: it is the stronger claim and the one a reader is looking for.
ORDER BY tier, l.physical_device_id, l.ran_from DESC,
         x.last_run_utc DESC NULLS LAST, l.executable, l.source_file;

-- ---- the device cards ------------------------------------------------------

-- Where each field on a device card came from.
--
-- This is the view the first stated requirement rests on: any finding must be
-- traceable back to its source easily. A card says "serial E0D55EA4…"; this
-- says which registry key in which file, with that file's hash, carried it.
--
-- The value shown is the one the preferred identity supplied, and the source is
-- that identity's, so the pair always agrees. Reading the value from the group
-- and the source from whichever member happened to sort first would produce a
-- citation for a value that member never held.
CREATE VIEW v_report_device_field AS
WITH member AS (
    SELECT g.physical_device_id, g.preference, d.*
    FROM v_devnode d
    JOIN v_device_group g USING (device_key)
),
field AS (
    SELECT physical_device_id, preference, 'friendly_name' AS field,
           friendly_name AS value, 1 AS ordinal,
           registry_key AS locator, source_id, source_path, source_sha256
    FROM member WHERE friendly_name <> ''
    UNION ALL
    SELECT physical_device_id, preference, 'device_description', device_desc, 2,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE device_desc <> ''
    UNION ALL
    SELECT physical_device_id, preference, 'bus_reported_description',
           bus_reported_desc, 3,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE bus_reported_desc <> ''
    UNION ALL
    SELECT physical_device_id, preference, 'manufacturer', mfg, 4,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE mfg <> ''
    UNION ALL
    -- A generated serial is not a serial. It is shown, because it is what the
    -- evidence holds, and the caveat rides in note rather than in value: the
    -- ranking below compares values, and decorating one would change which
    -- record the citation points at.
    SELECT physical_device_id, preference, 'serial', serial, 5,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE serial <> ''
    UNION ALL
    SELECT physical_device_id, preference, 'device_class', class, 6,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE class <> ''
    UNION ALL
    SELECT physical_device_id, preference, 'driver_service', service, 7,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE service <> ''
    UNION ALL
    SELECT physical_device_id, preference, 'hardware_id', hardware_id, 8,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE hardware_id <> ''
    UNION ALL
    SELECT physical_device_id, preference, 'compatible_ids', compatible_ids, 9,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE compatible_ids <> ''
    UNION ALL
    SELECT physical_device_id, preference, 'container_id', container_id, 10,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE is_real_container(container_id)
    UNION ALL
    SELECT physical_device_id, preference, 'location', location_information, 11,
           registry_key, source_id, source_path, source_sha256
    FROM member WHERE location_information <> ''
),
ranked AS (
    -- The ordering has to reproduce, exactly, how v_physical_device picked the
    -- value: the lowest-preference identity that carries the field, and within
    -- one identity the greatest value, because v_device aggregates across
    -- control sets with max(). Order by anything else and the card shows one
    -- value while the citation beside it points at another — a WPDBUSENUM node
    -- saying "PATRIOT" under a heading that reads "PATRIOT USB Device".
    SELECT *, row_number() OVER (PARTITION BY physical_device_id, field
                                 ORDER BY preference, value DESC, locator) AS rank
    FROM field
),
-- Counted once by a group-by rather than by a subquery per row. Asked per row,
-- this re-walks the whole union for every field of every device, which is the
-- same shape that took the fact pipeline from four seconds to not finishing.
spread AS (
    SELECT physical_device_id, field, count(DISTINCT value) AS distinct_values
    FROM field GROUP BY physical_device_id, field
)
SELECT physical_device_id, field, value, ordinal,
       CASE WHEN field = 'serial' AND EXISTS (
                SELECT 1 FROM v_device_identity i
                WHERE i.physical_device_id = ranked.physical_device_id
                  AND i.serial = ranked.value AND i.serial_is_generated)
            THEN 'generated by Windows, not read from the device'
            ELSE '' END AS note,
       locator, source_id,
       -- A source the ledger never recorded has no path or hash. Coalesced so
       -- no NULL reaches the report, where an unknown source and a source with
       -- an empty path would render identically.
       coalesce(source_path, '')   AS source_path,
       coalesce(source_sha256, '') AS source_sha256,
       -- How many identities in the group carried this field. Where they
       -- disagree the analyst should know there was a choice.
       spread.distinct_values
FROM ranked
JOIN spread USING (physical_device_id, field)
WHERE rank = 1
ORDER BY physical_device_id, ordinal, field;

-- Every file the evidence for a device was read from, with its hash.
CREATE VIEW v_report_device_source AS
SELECT
    g.physical_device_id,
    e.evidence,
    coalesce(s.artefact, '')    AS artefact,
    coalesce(s.source_path, e.source_path, '') AS source_path,
    coalesce(s.sha256, '')      AS sha256,
    count(*)                    AS records
FROM v_device_evidence e
JOIN v_device_group g ON g.device_key = e.device_key
LEFT JOIN v_source s ON s.source_id = e.source_id
GROUP BY ALL
ORDER BY g.physical_device_id, e.evidence, source_path, artefact, sha256;

-- One row per device the report leads with, carrying the counts a card shows.
--
-- The counts are here rather than on v_physical_device because they cross into
-- the volume and file layers, and a device inventory that had to walk the file
-- attribution to be read would be slow for every reader that did not want it.
CREATE VIEW v_report_device AS
WITH file_use AS (
    SELECT g.physical_device_id,
           count(DISTINCT a.activity_id) AS file_records,
           count(DISTINCT a.path)        AS file_paths,
           count(DISTINCT a.drive_letter) FILTER (WHERE a.drive_letter <> '')
                                         AS letters_seen,
           min(a.recorded_utc)           AS first_file_utc,
           max(a.recorded_utc)           AS last_file_utc,
           -- The strongest route that reached this device. A card that showed
           -- only a count would say nothing about how firmly it was reached.
           coalesce(list_extract(['confirmed', 'strong', 'probable', 'possible'],
               min(CASE a.confidence WHEN 'confirmed' THEN 1 WHEN 'strong' THEN 2
                                     WHEN 'probable' THEN 3 ELSE 4 END)),
               'unattributed')           AS best_confidence
    FROM v_file_attribution a
    JOIN v_device_group g ON g.device_key = a.device_key
    GROUP BY g.physical_device_id
),
windows AS (
    SELECT g.physical_device_id,
           count(*)                                       AS connection_windows,
           count(*) FILTER (WHERE c.open_ended)           AS open_ended_windows,
           count(*) FILTER (WHERE NOT c.start_known)      AS unknown_start_windows,
           min(c.started_utc)                             AS first_started_utc,
           max(c.ended_utc)                               AS last_ended_utc
    FROM v_connection c
    JOIN v_device_group g ON g.device_key = c.device_key
    GROUP BY g.physical_device_id
),
volumes AS (
    SELECT g.physical_device_id,
           string_agg(DISTINCT nullif(l.drive_letter, ''), ', '
                      ORDER BY nullif(l.drive_letter, '')) AS drive_letters,
           string_agg(DISTINCT nullif(l.volume_label, ''), ', '
                      ORDER BY nullif(l.volume_label, '')) AS volume_labels,
           count(*)                                             AS volume_links
    FROM v_device_volume_link l
    JOIN v_device_group g ON g.device_key = l.device_key
    GROUP BY g.physical_device_id
)
SELECT
    d.*,
    coalesce(v.drive_letters, '')            AS linked_drive_letters,
    coalesce(v.volume_labels, '')            AS volume_labels,
    coalesce(v.volume_links, 0)              AS volume_links,
    coalesce(w.connection_windows, 0)        AS connection_windows,
    coalesce(w.open_ended_windows, 0)        AS open_ended_windows,
    coalesce(w.unknown_start_windows, 0)     AS unknown_start_windows,
    w.first_started_utc,
    w.last_ended_utc,
    coalesce(f.file_records, 0)              AS file_records,
    coalesce(f.file_paths, 0)                AS file_paths,
    coalesce(f.letters_seen, 0)              AS file_letters,
    f.first_file_utc,
    f.last_file_utc,
    coalesce(f.best_confidence, 'unattributed') AS file_confidence
FROM v_device_classified d
LEFT JOIN volumes  v USING (physical_device_id)
LEFT JOIN windows  w USING (physical_device_id)
LEFT JOIN file_use f USING (physical_device_id)
ORDER BY d.tier, d.score DESC, d.physical_device_id;

-- File and folder activity, per device, as the report groups it.
--
-- One row per device and record, carrying the strongest route that reached that
-- pairing and the reasoning behind it. The reasoning is on the row rather than
-- in a legend because "probable" means something different depending on how it
-- was arrived at, and a reader deciding what to do with a link needs to see the
-- route, not a word ranking it.
CREATE VIEW v_report_file_activity AS
WITH
-- Materialised because the spread and the ranking both read it, and each read
-- is otherwise a full evaluation of the grouping under the attribution.
attributed AS MATERIALIZED (
    SELECT g.physical_device_id, f.activity_id, f.route, f.confidence,
           f.detail AS reason, f.contradicted,
           CASE f.confidence WHEN 'confirmed' THEN 1 WHEN 'strong' THEN 2
                             WHEN 'probable'  THEN 3 ELSE 4 END AS confidence_rank
    FROM v_file_attribution f
    JOIN v_device_group g ON g.device_key = f.device_key
),
-- How many devices claim the record at all. A file linked to one device and a
-- file linked to three are different claims, and the second must not be shown
-- on a card as though the device were the only candidate.
spread AS (
    SELECT activity_id, count(DISTINCT physical_device_id) AS candidate_devices
    FROM attributed
    GROUP BY activity_id
),
best AS (
    -- Confidence first, then the fallback route last, then the name. Two routes
    -- can tie at probable and not be worth the same to a reader: every route
    -- but one reaches the device through something the record itself carries —
    -- a serial, a label, a letter — while sole_connected_device reaches it
    -- through the connection windows alone, and exists for the records nothing
    -- else can reach. Ranked alphabetically it sorted above volume_label_unique
    -- and the card stopped saying that the volume's own label named the device,
    -- which is the firmer half of that finding.
    --
    -- A contradicted route sorts last of all, ahead of even that: the record's
    -- own label says this letter names the wrong device, so it is the last
    -- reason a card should give for the link.
    SELECT *, row_number() OVER (
               PARTITION BY physical_device_id, activity_id
               ORDER BY confidence_rank,
                        contradicted,
                        (route = 'sole_connected_device'),
                        route) AS pick
    FROM attributed
)
SELECT
    b.physical_device_id,
    coalesce(n.device_label, b.physical_device_id) AS device_label,
    c.tier,
    c.score,
    b.activity_id,
    b.confidence,
    b.confidence_rank,
    b.route,
    b.reason,
    s.candidate_devices,
    a.artefact,
    a.detail,
    a.path,
    a.drive_letter,
    a.volume_label,
    a.profile,
    a.recorded_utc,
    a.recorded_meaning,
    -- Named where the recorded time is a format's zero. wintime refuses the
    -- stored sentinels exactly, so this should stay empty here; it is carried
    -- because a date in 1979 reaching a page is a defect an analyst has to
    -- catch, and the check costs nothing.
    epoch_default_name(a.recorded_utc) AS epoch_default,
    a.source_id,
    coalesce(src.path, '')   AS source_path,
    coalesce(src.sha256, '') AS source_sha256
FROM best b
JOIN spread s USING (activity_id)
JOIN v_file_activity a USING (activity_id)
JOIN v_device_classification c ON c.physical_device_id = b.physical_device_id
LEFT JOIN v_device_label n ON n.physical_device_id = b.physical_device_id
LEFT JOIN source src ON src.id = a.source_id
WHERE b.pick = 1
-- Device order follows the cards, so the two sections read in the same order.
-- activity_id last because everything above it ties: one file opened twice at
-- the same recorded moment, or two MRU lists naming one path, come back in
-- either order otherwise, and the rendered report is hashed in the manifest.
ORDER BY c.tier, c.score DESC, b.physical_device_id,
         b.confidence_rank, a.recorded_utc NULLS LAST, a.path, a.activity_id;

-- File and folder records that reached no device, and why.
--
-- A gap that is not shown is a gap that reads as an absence of activity. Each
-- row says what stopped it: usually that the record names a letter no USB
-- device is linked to, which for the system drive is the expected answer and
-- for a removable letter is a finding.
CREATE VIEW v_report_file_unattributed AS
SELECT
    a.activity_id,
    a.artefact,
    a.detail,
    a.path,
    a.drive_letter,
    a.profile,
    a.recorded_utc,
    a.recorded_meaning,
    CASE
        WHEN a.drive_letter = '' AND a.volume_serial_hex = ''
             AND a.volume_label = ''
        THEN 'the record carries no drive letter, volume serial or label, so '
             || 'there is nothing to match a device on'
        WHEN a.drive_letter = ''
        THEN 'the record carries no drive letter, and its volume serial and '
             || 'label match no device in this evidence'
        ELSE 'drive letter ' || a.drive_letter || ' is linked to no USB device '
             || 'in this evidence'
    END AS reason,
    epoch_default_name(a.recorded_utc) AS epoch_default,
    a.source_id,
    coalesce(src.path, '')   AS source_path,
    coalesce(src.sha256, '') AS source_sha256
FROM v_file_activity a
LEFT JOIN v_file_attribution f USING (activity_id)
LEFT JOIN source src ON src.id = a.source_id
WHERE f.activity_id IS NULL
-- activity_id last, because drive letter and path tie: two MRU lists on one
-- host record the same file under the same letter, and ordered on those alone
-- the two rows came back either way round. That changed the rendered report
-- between two runs over one evidence root, and the manifest hashes the report.
ORDER BY a.drive_letter, a.path, a.activity_id;
